{"id":"b01e94a5-38e4-5cad-ac2b-e1cc75f3680e","key":"90-90-hold","name_fr":"Maintien 90/90","name_en":"90/90 Hold","aliases_fr":["Position 90/90","90/90 hip stretch"],"aliases_en":["90/90 stretch"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["hip_flexors"],"secondary_muscles":["gluteus_maximus","gluteus_medius"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":["Assieds-toi au sol et fléchis ta jambe avant devant toi pour que le tibia soit en travers du corps et le genou fléchi à environ 90 degrés.","Place ta jambe arrière sur le côté, ce genou aussi fléchi à environ 90 degrés, tibia pointant vers l'arrière.","Pose les mains au sol à côté des hanches pour t'appuyer.","Redresse-toi, poitrine haute et les deux ischions aussi proches du sol que possible.","Tiens la position en respirant lentement, avec un étirement sur l'extérieur de la hanche de la jambe avant et sur l'avant de la hanche de la jambe arrière.","Tiens pendant la durée prévue, puis inverse les jambes et recommence de l'autre côté."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-90-90-hold"],"attribution_required":true,"exportable":false},
