{"id":"c7e65a35-ae64-52e4-bcd8-3c937d192f9a","key":"back-lever","name_fr":"Back lever","name_en":"Back Lever","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["pull_up_bar"],"primary_muscles":["erector_spinae","latissimus_dorsi"],"secondary_muscles":["anterior_deltoid","gluteus_maximus","rectus_abdominis"],"difficulty":"advanced","metrics":["duration_s"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Suspends-toi à une barre en pronation et fais basculer le corps vers l'arrière en passant par les bras jusqu'à être inversé.","Descends le corps vers l'avant et vers le bas jusqu'à ce qu'il soit horizontal, face au sol.","Garde les bras tendus et tout le corps en une ligne rigide de la tête aux talons.","Gaine les abdominaux et serre les fessiers pour que les hanches et les épaules ne s'affaissent pas.","Tiens pendant la durée voulue, puis remonte en contrôlant."],"image_main":"/exercises/back-lever/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-back-lever"],"attribution_required":true,"exportable":false},
