{"id":"ea8f937c-9e49-59c6-8371-e39e2652a675","key":"banded-adductor-stretch","name_fr":"Étirement adducteurs élastique","name_en":"Banded Adductor Stretch","aliases_fr":[],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["resistance_band"],"primary_muscles":["adductors"],"secondary_muscles":["hamstrings"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Allonge-toi sur le dos avec un élastique passé autour d'un pied.","Lève cette jambe et laisse-la s'ouvrir sur le côté.","Tiens l'élastique pour contrôler la descente de la jambe.","Tiens la position 20 à 30 secondes en respirant calmement.","Change de côté et recommence."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-banded-adductor-stretch"],"attribution_required":true,"exportable":false},
{"id":"186a402a-83ac-56cc-9843-04eea9ab041c","key":"banded-ankle-stretch","name_fr":"Étirement cheville élastique","name_en":"Banded Ankle Stretch","aliases_fr":[],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["resistance_band"],"primary_muscles":["gastrocnemius"],"secondary_muscles":["soleus"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Assieds-toi avec une jambe tendue et un élastique autour de l'avant du pied.","Tiens l'élastique à deux mains.","Tire pour ramener les orteils vers ton tibia.","Tiens la position 20 à 30 secondes en respirant calmement.","Change de côté et recommence."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-banded-ankle-stretch"],"attribution_required":true,"exportable":false},
{"id":"13b114be-6a3b-573c-b381-11604380a087","key":"banded-calf-stretch","name_fr":"Étirement mollets élastique","name_en":"Banded Calf Stretch","aliases_fr":[],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["resistance_band"],"primary_muscles":["gastrocnemius"],"secondary_muscles":["soleus"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Allonge-toi sur le dos et passe un élastique autour de l'avant d'un pied.","Lève la jambe en la gardant presque tendue.","Tire l'élastique pour ramener les orteils vers ton tibia.","Tiens la position 20 à 30 secondes en respirant calmement.","Change de côté et recommence."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-banded-calf-stretch"],"attribution_required":true,"exportable":false},
{"id":"88441849-3195-5c67-a328-2fe72a76c521","key":"banded-chest-stretch","name_fr":"Étirement pectoraux élastique","name_en":"Banded Chest Stretch","aliases_fr":[],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["resistance_band"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Tiens un élastique derrière ton dos à deux mains.","Tends les bras et écarte-les.","Sors la poitrine et rapproche les omoplates.","Tiens la position 20 à 30 secondes en respirant calmement."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-banded-chest-stretch"],"attribution_required":true,"exportable":false},
{"id":"e45dcf97-c94c-5ace-9acf-4e792d53c4e8","key":"banded-clamshell","name_fr":"Clamshell mini-bande","name_en":"Banded Clamshell","aliases_fr":["Coquillage mini-bande"],"aliases_en":["Banded clam"],"category":"strength","visibility":"active","disciplines":["strength","warmup"],"hyrox_station":null,"family":"hip-abduction","variant_of":null,"equipment":["mini_band"],"primary_muscles":["gluteus_medius"],"secondary_muscles":["gluteus_maximus"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs"],"instructions_fr":["Allonge-toi sur le côté, hanches et genoux fléchis à environ 45 degrés, pieds empilés.","Place une mini-bande autour des deux jambes, au-dessus des genoux.","Garde les pieds collés et le bassin stable, sans basculer en arrière pendant le mouvement.","Ouvre le genou du dessus vers le haut contre la bande, comme une coquille qui s'ouvre, jusqu'à sentir le fessier travailler.","Marque une courte pause en haut, puis redescends sous contrôle.","Fais toutes les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/banded-clamshell/start.webp","image_end":"/exercises/banded-clamshell/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-banded-clamshell"],"attribution_required":true,"exportable":false},
{"id":"77955141-0449-5871-b5d8-1d3796d709c6","key":"banded-figure-4-stretch","name_fr":"Étirement figure 4 élastique","name_en":"Banded Figure-4 Stretch","aliases_fr":["Étirement du 4 élastique"],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["resistance_band"],"primary_muscles":["gluteus_maximus"],"secondary_muscles":["gluteus_medius"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Allonge-toi sur le dos et croise une cheville sur la cuisse opposée.","Passe un élastique autour de la cuisse d'appui.","Avec l'élastique, tire les deux jambes vers ta poitrine.","Tiens la position 20 à 30 secondes en respirant calmement.","Change de côté et recommence."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-banded-figure-4-stretch"],"attribution_required":true,"exportable":false},
{"id":"fc3151a6-3b5f-5047-8fb7-2d9cf8bdfdb1","key":"banded-fire-hydrant","name_fr":"Fire hydrant mini-bande","name_en":"Banded Fire Hydrant","aliases_fr":["Fire hydrant élastique"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"hip-abduction","variant_of":null,"equipment":["mini_band"],"primary_muscles":["gluteus_medius"],"secondary_muscles":["gluteus_maximus"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":true,"bodyweight":false,"tags":["legs","glutes"],"instructions_fr":["Place une mini-bande juste au-dessus des genoux et mets-toi à quatre pattes, mains sous les épaules et genoux sous les hanches.","Gaine les abdominaux et garde le dos plat, colonne neutre pendant tout le mouvement.","Lève lentement un genou sur le côté, en gardant le genou fléchi à 90 degrés, jusqu'à ce que la cuisse soit parallèle au sol.","Maintiens brièvement en haut en contractant le fessier, puis redescends lentement la jambe à la position de départ avec contrôle.","Fais toutes les répétitions d'un côté avant de changer."],"image_main":null,"image_start":"/exercises/banded-fire-hydrant/start.webp","image_end":"/exercises/banded-fire-hydrant/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-banded-fire-hydrant"],"attribution_required":true,"exportable":false},
{"id":"093b0d0f-96d7-52c7-9a7b-767879010b5b","key":"banded-glute-bridge","name_fr":"Pont fessier avec mini-bande","name_en":"Banded Glute Bridge","aliases_fr":[],"aliases_en":["Banded bridge"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"hip-thrust","variant_of":null,"equipment":["mini_band"],"primary_muscles":["gluteus_maximus"],"secondary_muscles":["gluteus_medius","hamstrings"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs"],"instructions_fr":["Allonge-toi sur le dos, genoux fléchis et pieds à plat au sol, à largeur d'épaules.","Place une mini-bande autour des deux jambes, juste au-dessus des genoux.","Plaque le bas du dos au sol et gaine les abdominaux.","Pousse dans les talons et serre les fessiers pour monter les hanches en pont. Garde la tension de la bande en poussant les genoux vers l'extérieur.","En haut, le corps forme une ligne droite des épaules aux genoux. Marque une courte pause.","Redescends de façon contrôlée jusqu'au départ et répète pour le nombre de répétitions prévu."],"image_main":null,"image_start":"/exercises/banded-glute-bridge/start.webp","image_end":"/exercises/banded-glute-bridge/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-banded-glute-bridge"],"attribution_required":true,"exportable":false},
{"id":"f0a3f2b3-e3b3-50d5-afc6-f40cc3c8b247","key":"banded-good-morning","name_fr":"Good morning élastique","name_en":"Banded Good Morning","aliases_fr":["Good morning mini-bande"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"deadlift","variant_of":null,"equipment":["mini_band"],"primary_muscles":["gluteus_maximus","hamstrings"],"secondary_muscles":["erector_spinae"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull","legs"],"instructions_fr":["Monte avec les deux pieds sur une mini-bande et passe-la derrière la nuque.","Place les pieds à largeur de hanches, genoux légèrement fléchis.","Penche-toi en charnière de hanches en poussant les fesses vers l'arrière, dos plat.","Descends jusqu'à sentir un étirement des ischio-jambiers.","Pousse les hanches vers l'avant pour te redresser."],"image_main":null,"image_start":"/exercises/banded-good-morning/start.webp","image_end":"/exercises/banded-good-morning/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-banded-good-morning"],"attribution_required":true,"exportable":false},
{"id":"f40d982e-2dcd-5055-a5ce-5491c7d08d44","key":"banded-hamstring-stretch","name_fr":"Étirement ischio-jambiers élastique","name_en":"Banded Hamstring Stretch","aliases_fr":[],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["resistance_band"],"primary_muscles":["hamstrings"],"secondary_muscles":["gastrocnemius"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Allonge-toi sur le dos et passe un élastique autour d'un pied.","Lève cette jambe à la verticale en tenant l'élastique à deux mains.","Tire doucement sur l'élastique pour ramener la jambe vers toi.","Tiens la position 20 à 30 secondes en respirant calmement.","Change de côté et recommence."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-banded-hamstring-stretch"],"attribution_required":true,"exportable":false},
