{"id":"517f8439-21af-568e-a026-1129d5687049","key":"bench-bulgarian-split-stretch","name_fr":"Étirement squat bulgare sur banc","name_en":"Bench Bulgarian Split Stretch","aliases_fr":["Étirement fente bulgare"],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["bench"],"primary_muscles":["hip_flexors","quadriceps"],"secondary_muscles":["gluteus_maximus"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Pose le dessus du pied arrière sur un banc derrière toi.","Place le pied avant à plat et plie ce genou.","Descends les hanches à la verticale.","Tiens la position 20 à 30 secondes en respirant calmement.","Change de côté et recommence."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-bench-bulgarian-split-stretch"],"attribution_required":true,"exportable":false},
