{"id":"65afd0b7-fa1c-5ca7-a9dd-96f86b7feeb2","key":"bench-childs-pose","name_fr":"Posture de l'enfant sur banc","name_en":"Bench Child's Pose","aliases_fr":["Child's pose sur banc"],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["bench"],"primary_muscles":["erector_spinae","latissimus_dorsi"],"secondary_muscles":[],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Mets-toi à genoux au sol face à un banc.","Tends les deux bras vers l'avant et pose-les sur le banc.","Recule les hanches vers les talons et laisse la poitrine descendre.","Tiens la position 20 à 30 secondes en respirant calmement."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-bench-childs-pose"],"attribution_required":true,"exportable":false},
{"id":"42dd4db4-b14e-5e32-84ce-083866bdc056","key":"bench-couch-stretch","name_fr":"Couch stretch","name_en":"Bench Couch Stretch","aliases_fr":["Étirement des fléchisseurs de hanche sur banc","Étirement du canapé","Étirement quadriceps sur banc","Étirement fléchisseur de hanche au canapé"],"aliases_en":["Couch stretch"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["bench"],"primary_muscles":["hip_flexors","quadriceps"],"secondary_muscles":[],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Mets-toi à genoux avec le tibia arrière contre l'avant d'un banc.","Pose le pied avant à plat au sol.","Redresse le buste jusqu'à sentir l'avant de la cuisse s'étirer.","Tiens la position 20 à 30 secondes en respirant calmement.","Change de côté et recommence."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-bench-couch-stretch","coory-couch-stretch"],"attribution_required":true,"exportable":false},
{"id":"0bb9d629-b9a8-5f30-b966-3f3e0b559eaf","key":"bench-decline-plank-hold","name_fr":"Planche pieds sur banc (maintien)","name_en":"Bench Decline Plank Hold","aliases_fr":["Planche déclinée"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"plank","variant_of":null,"equipment":["bench"],"primary_muscles":["rectus_abdominis","transverse_abdominis"],"secondary_muscles":["anterior_deltoid","obliques","serratus_anterior"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":["core","calisthenics"],"instructions_fr":["Place un banc derrière toi et pose le dessus des pieds dessus, puis mets les mains au sol sous les épaules, bras tendus.","Avance les mains jusqu'à ce que ton corps soit aligné de la tête aux talons.","Serre les fessiers, gaine les abdominaux et repousse le sol pour que les épaules ne s'affaissent pas entre les omoplates.","Garde la nuque dans l'alignement de la colonne et regarde le sol entre tes mains.","Tiens la position pendant le temps prévu en respirant lentement.","Pose les genoux au sol et repose-toi."],"image_main":"/exercises/bench-decline-plank-hold/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-bench-decline-plank-hold"],"attribution_required":true,"exportable":false},
{"id":"abce3421-ef8d-500b-9ad2-100e3bc2cde2","key":"bench-dips","name_fr":"Dips sur banc","name_en":"Bench Dips","aliases_fr":["Dips entre deux bancs"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"dips","variant_of":null,"equipment":["bench"],"primary_muscles":["triceps_brachii"],"secondary_muscles":["anterior_deltoid","pectoralis_major"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Assieds-toi sur un banc et place les mains sur le bord, à côté des hanches.","Fais glisser les hanches hors du banc, jambes tendues.","Descends le corps en fléchissant les coudes à 90 degrés.","Pousse dans les paumes pour revenir à la position de départ.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/bench-dips/start.webp","image_end":"/exercises/bench-dips/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-bench-dips"],"attribution_required":true,"exportable":false},
{"id":"c382bddd-67a2-5499-9730-abf376779276","key":"bench-figure-4-glute-stretch","name_fr":"Étirement fessiers figure 4 sur banc","name_en":"Bench Figure-4 Glute Stretch","aliases_fr":[],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["bench"],"primary_muscles":["gluteus_maximus"],"secondary_muscles":["gluteus_medius"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Assieds-toi au bout d'un banc.","Croise une cheville sur le genou opposé.","Garde le dos plat et penche-toi en avant au-dessus de la jambe croisée.","Tiens la position 20 à 30 secondes en respirant calmement.","Change de côté et recommence."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-bench-figure-4-glute-stretch"],"attribution_required":true,"exportable":false},
{"id":"72f72ecc-e40c-59e9-81ba-df2cd4bb8037","key":"bench-hamstring-stretch","name_fr":"Étirement ischio-jambiers sur banc","name_en":"Bench Hamstring Stretch","aliases_fr":[],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["bench"],"primary_muscles":["hamstrings"],"secondary_muscles":["erector_spinae"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Pose un talon sur un banc, cette jambe tendue.","Reste grand sur la jambe d'appui.","Penche-toi en avant en pliant aux hanches au-dessus de la jambe levée.","Tiens la position 20 à 30 secondes en respirant calmement.","Change de côté et recommence."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-bench-hamstring-stretch"],"attribution_required":true,"exportable":false},
{"id":"ec1802c0-3b5b-5a6e-b9b1-46a3cf37f90e","key":"bench-hollow-hold","name_fr":"Hollow hold sur banc","name_en":"Bench Hollow Hold","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"static-hold","variant_of":null,"equipment":["bench"],"primary_muscles":["hip_flexors","rectus_abdominis"],"secondary_muscles":["obliques","quadriceps","transverse_abdominis"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":false,"bodyweight":false,"tags":["core","calisthenics"],"instructions_fr":["Allonge-toi sur le dos sur un banc plat, fessiers et bas du dos sur le coussin, jambes tendues.","Tends les bras au-dessus de la tête, le long des oreilles.","Gaine les abdominaux et plaque le bas du dos contre le banc.","Lève les épaules et les jambes tendues de quelques centimètres pour former un léger creux.","Maintiens la position en respirant régulièrement, puis redescends pour te reposer."],"image_main":"/exercises/bench-hollow-hold/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-bench-hollow-hold"],"attribution_required":true,"exportable":false},
{"id":"2832ea39-d026-57db-adad-f60a7064573f","key":"bench-lat-stretch","name_fr":"Étirement dorsaux sur banc","name_en":"Bench Lat Stretch","aliases_fr":[],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["bench"],"primary_muscles":["latissimus_dorsi"],"secondary_muscles":["posterior_deltoid"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Mets-toi à genoux au sol face à un banc.","Pose les deux mains sur le dessus du banc.","Recule les hanches et laisse la poitrine descendre.","Tiens la position 20 à 30 secondes en respirant calmement."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-bench-lat-stretch"],"attribution_required":true,"exportable":false},
{"id":"f3da07b2-03b3-596e-8d8e-d11f0b0c419f","key":"bench-leg-pull-in","name_fr":"Relevé de jambes assis sur banc","name_en":"Bench Leg Pull-In","aliases_fr":["Leg pull-in sur banc"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["bench"],"primary_muscles":["rectus_abdominis"],"secondary_muscles":["hip_flexors","obliques"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["core","calisthenics"],"instructions_fr":["Assieds-toi sur un banc plat, attrape ses bords à côté ou juste derrière tes hanches et penche légèrement le buste en arrière.","Tends les jambes devant toi, pieds décollés du sol.","Ramène les genoux vers la poitrine en amenant légèrement le buste vers l'avant à leur rencontre.","Étends à nouveau les jambes en contrôlant, sans laisser les pieds toucher le sol.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/bench-leg-pull-in/start.webp","image_end":"/exercises/bench-leg-pull-in/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-bench-leg-pull-in"],"attribution_required":true,"exportable":false},
{"id":"922f5540-60d1-5443-bc49-55c3f5964cf3","key":"bench-press","name_fr":"Développé couché barre","name_en":"Barbell Bench Press","aliases_fr":["Bench press"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bench-press","variant_of":null,"equipment":["barbell","bench"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["powerlifting","push"],"instructions_fr":["Allonge-toi à plat sur un banc, les yeux sous la barre.","Prends la barre un peu plus large que les épaules.","Décroche la barre et descends-la au milieu de la poitrine.","Repousse la barre jusqu'à l'extension complète des bras.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/bench-press/start.webp","image_end":"/exercises/bench-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-bench-press"],"attribution_required":true,"exportable":false},
{"id":"ecacee00-9819-5d95-af5b-81650ed02bfe","key":"bench-pull","name_fr":"Tirage sur banc","name_en":"Bench Pull","aliases_fr":["Rowing allongé sur banc"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"row","variant_of":null,"equipment":["barbell"],"primary_muscles":["latissimus_dorsi","rhomboids"],"secondary_muscles":["biceps_brachii","posterior_deltoid","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Allonge-toi sur le ventre sur un banc surélevé, bras pendant à la verticale.","Saisis une barre ou des haltères sous toi.","Tire la charge vers le dessous du banc.","Serre les omoplates en haut.","Redescends de façon contrôlée et répète."],"image_main":null,"image_start":"/exercises/bench-pull/start.webp","image_end":"/exercises/bench-pull/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-bench-pull"],"attribution_required":true,"exportable":false},
{"id":"b966db10-3224-5278-b086-8a22f4eeaed5","key":"bent-arm-barbell-pullover","name_fr":"Pull-over barre bras fléchis","name_en":"Bent Arm Barbell Pullover","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"pullover","variant_of":null,"equipment":["barbell","bench"],"primary_muscles":["latissimus_dorsi","pectoralis_major"],"secondary_muscles":["serratus_anterior","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Allonge-toi sur un banc, une barre tenue au-dessus de la poitrine, coudes fléchis.","Garde les coudes fléchis pendant tout le mouvement.","Descends la barre derrière la tête en arc de cercle.","Ramène la barre au-dessus de la poitrine en utilisant les dorsaux.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/bent-arm-barbell-pullover/start.webp","image_end":"/exercises/bent-arm-barbell-pullover/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-bent-arm-barbell-pullover"],"attribution_required":true,"exportable":false},
{"id":"27245d7a-f7bb-573e-a15b-ea2014df3f6f","key":"bent-arm-ez-bar-pullover","name_fr":"Pull-over barre EZ bras fléchis","name_en":"Bent-Arm EZ-Bar Pullover","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"pullover","variant_of":null,"equipment":["ez_bar","bench"],"primary_muscles":["latissimus_dorsi","pectoralis_major"],"secondary_muscles":["posterior_deltoid","serratus_anterior","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull"],"instructions_fr":["Allonge-toi sur un banc plat, une barre EZ tenue en prise serrée en pronation sur les courbes intérieures.","Pars avec la barre au-dessus de la poitrine, coudes fléchis à environ 90 degrés.","Garde l'angle des coudes fixe et descends la barre en arc de cercle derrière la tête jusqu'à sentir un étirement profond des dorsaux et des pectoraux.","Ramène la barre au-dessus de la poitrine sur le même arc, sans tendre les coudes.","Répète pour le nombre de répétitions prévu."],"image_main":null,"image_start":"/exercises/bent-arm-ez-bar-pullover/start.webp","image_end":"/exercises/bent-arm-ez-bar-pullover/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-bent-arm-ez-bar-pullover"],"attribution_required":true,"exportable":false},
{"id":"26421b6d-1b34-599c-b63a-95422897e326","key":"bent-knee-copenhagen-raises","name_fr":"Copenhagen plank genou fléchi (relevés)","name_en":"Bent-Knee Copenhagen Raises","aliases_fr":["Relevés Copenhagen genou fléchi"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"plank","variant_of":null,"equipment":["bench"],"primary_muscles":["adductors","obliques"],"secondary_muscles":["gluteus_medius","quadratus_lumborum","transverse_abdominis"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":true,"bodyweight":false,"tags":["core","calisthenics"],"instructions_fr":["Allonge-toi sur le côté près d'un banc plat et pose l'intérieur de la jambe ou du pied du dessus dessus, genou du dessus légèrement fléchi ou tendu.","Appuie-toi sur le coude du bras du dessous, juste sous l'épaule.","Soulève les hanches pour que le corps forme une ligne droite de la tête à la jambe du dessus, et fléchis le genou de la jambe du dessous.","Monte le genou fléchi du dessous vers le banc en gardant les hanches hautes.","Redescends le genou lentement sans laisser tomber les hanches, et répète pour le nombre de répétitions prévu.","Repose-toi, puis change de côté."],"image_main":null,"image_start":"/exercises/bent-knee-copenhagen-raises/start.webp","image_end":"/exercises/bent-knee-copenhagen-raises/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-bent-knee-copenhagen-raises"],"attribution_required":true,"exportable":false},
{"id":"7ccd3e27-f7a6-5f82-8f94-f9f606fb5f67","key":"bent-over-db-row","name_fr":"Rowing haltères buste penché","name_en":"Bent-Over Dumbbell Row","aliases_fr":["Rowing haltères"],"aliases_en":["DB bent over row"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"row","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["latissimus_dorsi","rhomboids"],"secondary_muscles":["biceps_brachii","posterior_deltoid","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull","back"],"instructions_fr":["Tiens-toi debout, pieds à largeur de hanches, un haltère dans chaque main le long du corps, paumes face à face.","Penche le buste en partant des hanches, dos plat, jusqu'à environ 30 à 45 degrés par rapport à l'horizontale, haltères pendant à la verticale sous les épaules.","Gaine les abdominaux et tire les deux haltères vers le haut et légèrement vers l'arrière, en emmenant les coudes au-delà des côtes.","Serre le haut du dos en haut, coudes près du corps.","Redescends de façon contrôlée jusqu'à la position de départ, bras complètement tendus.","Répète pour le nombre de répétitions recommandé."],"image_main":null,"image_start":"/exercises/bent-over-db-row/start.webp","image_end":"/exercises/bent-over-db-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-bent-over-db-row"],"attribution_required":true,"exportable":false},
{"id":"c4a074e5-20a6-5cad-855c-d86db61664f8","key":"bent-over-ez-bar-row","name_fr":"Rowing barre EZ buste penché","name_en":"Bent-Over EZ-Bar Row","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"row","variant_of":null,"equipment":["ez_bar"],"primary_muscles":["latissimus_dorsi","rhomboids"],"secondary_muscles":["biceps_brachii","posterior_deltoid"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull"],"instructions_fr":["Tiens une barre EZ en pronation et penche le buste à 45 degrés en partant des hanches.","Tire la barre vers le bas de la cage thoracique.","Redescends de façon contrôlée.","Répète."],"image_main":null,"image_start":"/exercises/bent-over-ez-bar-row/start.webp","image_end":"/exercises/bent-over-ez-bar-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-bent-over-ez-bar-row"],"attribution_required":true,"exportable":false},
{"id":"22def43f-bb1f-5ad6-abf0-896d985a98da","key":"bicep-curl","name_fr":"Curl biceps haltères","name_en":"Dumbbell Bicep Curl","aliases_fr":["Curl haltères"],"aliases_en":["DB curl"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["biceps_brachii"],"secondary_muscles":["brachialis","forearm_flexors"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms"],"instructions_fr":["Tiens-toi debout avec des haltères le long du corps, paumes vers l'avant.","Monte les haltères vers les épaules.","Serre en haut, puis redescends de façon contrôlée.","Répète."],"image_main":null,"image_start":"/exercises/bicep-curl/start.webp","image_end":"/exercises/bicep-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-bicep-curl"],"attribution_required":true,"exportable":false},
{"id":"5400126b-46ab-577e-a8b3-fc9849bf7e2a","key":"bicycle-crunch","name_fr":"Crunch vélo","name_en":"Bicycle Crunch","aliases_fr":["Bicycle crunch"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"crunch","variant_of":null,"equipment":[],"primary_muscles":["obliques","rectus_abdominis"],"secondary_muscles":["hip_flexors"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["core"],"instructions_fr":["Allonge-toi sur le dos, mains derrière la tête, jambes levées.","Ramène un genou vers la poitrine en tournant le buste pour amener le coude opposé à sa rencontre.","Tends cette jambe en ramenant l'autre genou.","Continue en alternant, comme si tu pédalais.","Répète."],"image_main":null,"image_start":"/exercises/bicycle-crunch/start.webp","image_end":"/exercises/bicycle-crunch/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-bicycle-crunch"],"attribution_required":true,"exportable":false},
{"id":"0f257af5-998c-521b-a276-ad0f190be378","key":"bird-dog","name_fr":"Bird dog","name_en":"Bird-Dog","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"back-extension","variant_of":null,"equipment":[],"primary_muscles":["erector_spinae","transverse_abdominis"],"secondary_muscles":["gluteus_maximus"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["core"],"instructions_fr":["Place-toi à quatre pattes, la colonne neutre.","Étends en même temps le bras droit vers l'avant et la jambe gauche vers l'arrière.","Marque une courte pause, puis reviens.","Répète de l'autre côté.","Alterne."],"image_main":null,"image_start":"/exercises/bird-dog/start.webp","image_end":"/exercises/bird-dog/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-bird-dog"],"attribution_required":true,"exportable":false},
{"id":"f5f7181c-19d5-562f-9b5f-9199e10cde54","key":"bird-dog-hold","name_fr":"Bird dog isométrique","name_en":"Bird Dog Hold","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"back-extension","variant_of":null,"equipment":[],"primary_muscles":["erector_spinae","rectus_abdominis"],"secondary_muscles":["gluteus_maximus","obliques","posterior_deltoid"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Place-toi à quatre pattes, mains sous les épaules et genoux sous les hanches.","Étends un bras vers l'avant et la jambe opposée vers l'arrière.","Garde les abdominaux gainés et le corps à plat.","Tiens la position sans tourner le buste.","Tiens pendant la durée prévue. Fais un côté, puis change."],"image_main":"/exercises/bird-dog-hold/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-bird-dog-hold"],"attribution_required":true,"exportable":false},
{"id":"eab0acd0-7d96-5c8e-9a89-4894b50c197f","key":"boat-pose","name_fr":"Posture du bateau","name_en":"Boat Pose","aliases_fr":["Boat pose"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["hip_flexors","rectus_abdominis"],"secondary_muscles":["erector_spinae","quadriceps"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":["core","calisthenics"],"instructions_fr":["Assieds-toi au sol, genoux fléchis et pieds à plat, mains posées derrière les cuisses.","Penche-toi en arrière jusqu'à t'équilibrer juste derrière les ischions et lève la poitrine pour garder la colonne allongée.","Lève les tibias jusqu'à ce qu'ils soient parallèles au sol, puis tends les jambes autant que le dos reste plat.","Tends les bras devant toi à côté des jambes et maintiens la position pendant la durée prescrite.","Repose les pieds en contrôlant pour terminer."],"image_main":"/exercises/boat-pose/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-boat-pose"],"attribution_required":true,"exportable":false},
{"id":"f4a5891b-91c1-5d86-8c32-c6d33c28c7fd","key":"bodyweight-calf-raise","name_fr":"Extension des mollets au poids du corps","name_en":"Bodyweight Calf Raise","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"calf-raise","variant_of":null,"equipment":[],"primary_muscles":["gastrocnemius"],"secondary_muscles":["soleus"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Tiens-toi debout, pieds à largeur de hanches, sur une surface plane.","Monte sur l'avant des pieds le plus haut possible.","Serre les mollets en haut.","Redescends les talons au sol de façon contrôlée.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/bodyweight-calf-raise/start.webp","image_end":"/exercises/bodyweight-calf-raise/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-bodyweight-calf-raise"],"attribution_required":true,"exportable":false},
{"id":"648cd321-a3c1-5ca8-8433-e3ea2a307f02","key":"bodyweight-good-morning","name_fr":"Good morning au poids du corps","name_en":"Bodyweight Good Morning","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"deadlift","variant_of":null,"equipment":[],"primary_muscles":["erector_spinae","hamstrings"],"secondary_muscles":["gluteus_maximus"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Tiens-toi debout, pieds à largeur de hanches, mains derrière la tête.","Garde les genoux légèrement fléchis et gaine les abdominaux.","Penche-toi en charnière de hanches et descends le buste vers l'horizontale.","Pousse les hanches vers l'avant pour te redresser.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/bodyweight-good-morning/start.webp","image_end":"/exercises/bodyweight-good-morning/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-bodyweight-good-morning"],"attribution_required":true,"exportable":false},
{"id":"f2e82862-2e24-5a40-b234-4b00e265c8f3","key":"bodyweight-lateral-raise","name_fr":"Élévations latérales au poids du corps","name_en":"Bodyweight Lateral Raise","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["lateral_deltoid"],"secondary_muscles":["anterior_deltoid","trapezius"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["shoulders","push"],"instructions_fr":["Tiens-toi debout, bras le long du corps.","Lève les deux bras sur les côtés, coudes légèrement fléchis, jusqu'à ce qu'ils soient parallèles au sol.","Marque une courte pause en haut.","Redescends lentement à la position de départ.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/bodyweight-lateral-raise/start.webp","image_end":"/exercises/bodyweight-lateral-raise/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-bodyweight-lateral-raise"],"attribution_required":true,"exportable":false},
{"id":"2ed74150-8491-514d-a7b7-b83b999c2cab","key":"bodyweight-overhead-press","name_fr":"Développé militaire au poids du corps","name_en":"Bodyweight Overhead Press","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-press","variant_of":null,"equipment":[],"primary_muscles":["anterior_deltoid","triceps_brachii"],"secondary_muscles":["serratus_anterior","trapezius"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Tiens-toi droit, pieds à largeur de hanches, les mains en poings souples à hauteur d'épaules, paumes vers l'avant et coudes sous les poignets.","Gaine les abdominaux et serre les fessiers pour garder les côtes rentrées.","Pousse les deux bras à la verticale jusqu'à avoir les coudes complètement tendus et les bras à côté des oreilles.","Redescends les mains à hauteur d'épaules de façon contrôlée.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/bodyweight-overhead-press/start.webp","image_end":"/exercises/bodyweight-overhead-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-bodyweight-overhead-press"],"attribution_required":true,"exportable":false},
{"id":"3d09239b-e152-5140-ba5b-d05e3f425207","key":"bodyweight-reverse-lunge","name_fr":"Fentes arrière au poids du corps","name_en":"Bodyweight Reverse Lunge","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"lunge","variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["hamstrings"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":true,"bodyweight":true,"tags":["legs"],"instructions_fr":["Tiens-toi droit, pieds à largeur de hanches.","Recule une jambe et descends le genou vers le sol.","Descends jusqu'à ce que la cuisse avant soit parallèle au sol.","Pousse dans le talon avant pour revenir debout.","Répète des deux côtés."],"image_main":null,"image_start":"/exercises/bodyweight-reverse-lunge/start.webp","image_end":"/exercises/bodyweight-reverse-lunge/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-bodyweight-reverse-lunge"],"attribution_required":true,"exportable":false},
{"id":"f04352aa-2058-573f-a105-76a1fbf32543","key":"bodyweight-squat","name_fr":"Squat au poids du corps","name_en":"Bodyweight Squat","aliases_fr":["Air squat"],"aliases_en":["Air squat"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"squat","variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["erector_spinae","gluteus_medius","hamstrings"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Tiens-toi debout, pieds à largeur d'épaules, bras tendus devant toi.","Assieds-toi vers l'arrière et vers le bas en fléchissant les hanches et les genoux.","Descends jusqu'à ce que les cuisses soient parallèles au sol.","Pousse dans les talons pour te relever.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/bodyweight-squat/start.webp","image_end":"/exercises/bodyweight-squat/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-bodyweight-squat"],"attribution_required":true,"exportable":false},
{"id":"3e78b544-6322-597b-81fd-6a13ee2c957d","key":"bow-pose","name_fr":"Posture de l'arc","name_en":"Bow Pose","aliases_fr":["Bow pose"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["erector_spinae","gluteus_maximus"],"secondary_muscles":["hamstrings","pectoralis_major"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":["calisthenics"],"instructions_fr":["Allonge-toi sur le ventre, bras le long du corps et front posé sur le tapis.","Fléchis les genoux et attrape l'extérieur des deux chevilles.","Pousse les tibias vers l'arrière dans les mains pour que la poitrine et les cuisses se soulèvent du sol.","Maintiens la position levée pendant la durée prescrite, nuque allongée et regard vers l'avant.","Relâche les chevilles et redescends en contrôlant."],"image_main":"/exercises/bow-pose/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-bow-pose"],"attribution_required":true,"exportable":false},
{"id":"316d1dd9-7346-568d-8b20-1a8cb00493c6","key":"box-jump","name_fr":"Box jump","name_en":"Box Jump","aliases_fr":["Saut sur box"],"aliases_en":[],"category":"cardio","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["plyo_box"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["gastrocnemius","hamstrings","soleus"],"difficulty":"intermediate","metrics":["reps","height_cm"],"unilateral":false,"bodyweight":false,"tags":["legs","conditioning","plyometrics"],"instructions_fr":["Place-toi à environ 30 cm devant un box solide, pieds à largeur d'épaules.","Descends en quart de squat et balance les bras vers l'arrière.","Lance les bras vers le haut et décolle explosivement du sol pour atterrir sur le box.","Réceptionne-toi en douceur avec les deux pieds à plat et les genoux fléchis.","Redescends en marchant, sans sauter, et replace-toi."],"image_main":null,"image_start":"/exercises/box-jump/start.webp","image_end":"/exercises/box-jump/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-box-jump"],"attribution_required":true,"exportable":false},
{"id":"f3f5d81c-760c-5bc3-aca8-1c06d1fe0db0","key":"box-squat","name_fr":"Box squat","name_en":"Box Squat","aliases_fr":["Squat sur box"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"squat","variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["erector_spinae","gluteus_medius","hamstrings"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Tiens-toi devant une box ou un banc, pieds à largeur d'épaules, bras tendus devant toi pour l'équilibre.","Pousse les hanches vers l'arrière et fléchis les genoux, en t'asseyant vers la box plutôt que tout droit vers le bas.","Touche légèrement la box avec les fessiers sans t'effondrer dessus.","Pousse dans les pieds pour te relever, en serrant les fessiers en haut.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/box-squat/start.webp","image_end":"/exercises/box-squat/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-box-squat"],"attribution_required":true,"exportable":false},
{"id":"dbcfd370-ed95-5183-ae56-660e1d55b897","key":"bulgarian-split-squat","name_fr":"Squat bulgare haltères","name_en":"Bulgarian Split Squat","aliases_fr":["Squat bulgare"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"squat","variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["hamstrings"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["legs"],"instructions_fr":["Tiens-toi devant un banc et pose un pied derrière toi sur le banc.","Tiens des haltères le long du corps.","Descends jusqu'à ce que la cuisse avant soit parallèle au sol.","Pousse dans le talon avant pour te relever.","Répète des deux côtés."],"image_main":null,"image_start":"/exercises/bulgarian-split-squat/start.webp","image_end":"/exercises/bulgarian-split-squat/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-bulgarian-split-squat"],"attribution_required":true,"exportable":false},
