{"id":"15fe21ca-a65a-5f7d-9572-cd648e5f7b22","key":"butterfly-stretch","name_fr":"Étirement papillon","name_en":"Butterfly Stretch","aliases_fr":["Posture du papillon"],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["adductors"],"secondary_muscles":["hip_flexors"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Assieds-toi bien droit et joins les plantes des pieds.","Laisse tes genoux s'ouvrir vers le sol.","Tiens tes pieds et reste grand.","Tiens la position 20 à 30 secondes en respirant calmement."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-butterfly-stretch"],"attribution_required":true,"exportable":false},
{"id":"e6729f71-3483-5140-880a-f00213fae87d","key":"cable-bent-over-row","name_fr":"Rowing à la poulie buste penché","name_en":"Cable Bent-Over Row","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"row","variant_of":null,"equipment":["cable"],"primary_muscles":["latissimus_dorsi","rhomboids"],"secondary_muscles":["biceps_brachii","posterior_deltoid"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull"],"instructions_fr":["Fixe une barre droite ou une barre en V à une poulie basse.","Penche le buste en partant des hanches, genoux légèrement fléchis.","Tire la poignée vers le bas de la poitrine.","Serre les omoplates en haut.","Redescends de façon contrôlée et répète."],"image_main":null,"image_start":"/exercises/cable-bent-over-row/start.webp","image_end":"/exercises/cable-bent-over-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cable-bent-over-row"],"attribution_required":true,"exportable":false},
{"id":"1a13f2f7-d88a-5181-ab1f-5b2efd32f79f","key":"cable-chest-press","name_fr":"Développé couché à la poulie","name_en":"Cable Chest Press","aliases_fr":["Développé pectoraux à la poulie"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bench-press","variant_of":null,"equipment":["cable"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid","serratus_anterior","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Règle les poulies à hauteur de poitrine et tourne le dos à la machine.","Prends une poignée dans chaque main et avance d'un pas en position décalée.","Pousse les poignées vers l'avant jusqu'à ce que tes bras soient tendus.","Serre les pectoraux en haut.","Reviens de façon contrôlée et répète."],"image_main":null,"image_start":"/exercises/cable-chest-press/start.webp","image_end":"/exercises/cable-chest-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cable-chest-press"],"attribution_required":true,"exportable":false},
{"id":"1ea4fa73-a490-5438-a6fb-fd24dd2f61e7","key":"cable-crunch","name_fr":"Crunch à la poulie","name_en":"Cable Crunch","aliases_fr":["Crunch à la poulie haute"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"crunch","variant_of":null,"equipment":["cable"],"primary_muscles":["rectus_abdominis"],"secondary_muscles":["obliques","transverse_abdominis"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Mets-toi à genoux face à une poulie haute équipée d'une corde.","Tiens la corde près du front, coudes fléchis.","Enroule le buste vers le bas en fléchissant la colonne et amène les coudes vers les cuisses.","Contracte fortement les abdominaux en bas du mouvement.","Reviens à la position de départ et répète."],"image_main":null,"image_start":"/exercises/cable-crunch/start.webp","image_end":"/exercises/cable-crunch/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cable-crunch"],"attribution_required":true,"exportable":false},
{"id":"1974bf2f-0bd6-557a-a058-b2fd264fe480","key":"cable-curl","name_fr":"Curl à la poulie","name_en":"Cable Curl","aliases_fr":["Curl poulie basse"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["cable"],"primary_muscles":["biceps_brachii"],"secondary_muscles":["brachialis"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms"],"instructions_fr":["Place-toi face à une poulie basse avec une barre droite ou une barre EZ.","Prends la barre en supination, les coudes le long du corps.","Monte la barre vers les épaules.","Redescends de façon contrôlée.","Répète."],"image_main":null,"image_start":"/exercises/cable-curl/start.webp","image_end":"/exercises/cable-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cable-curl"],"attribution_required":true,"exportable":false},
{"id":"d22a0a73-c9e1-5983-a8f6-e862d0082daa","key":"cable-external-rotation","name_fr":"Rotation externe à la poulie","name_en":"Cable External Rotation","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["cable"],"primary_muscles":["infraspinatus_teres_minor"],"secondary_muscles":["posterior_deltoid"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Règle une poulie à hauteur de coude et attrape la poignée.","Place-toi de côté par rapport à la machine, coude du bras de travail fléchi à 90 degrés.","Garde le coude collé à ton flanc et fais pivoter l'avant-bras vers l'extérieur.","Marque une pause en fin de mouvement.","Reviens en contrôlant. Fais toutes les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/cable-external-rotation/start.webp","image_end":"/exercises/cable-external-rotation/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cable-external-rotation"],"attribution_required":true,"exportable":false},
{"id":"1d13a703-c300-5f15-873e-2c90ee0f2a94","key":"cable-fly","name_fr":"Écarté à la poulie","name_en":"Cable Fly","aliases_fr":["Croisé poulie"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"chest-fly","variant_of":null,"equipment":["cable"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Place-toi entre deux colonnes de poulies, les poignées fixées aux poulies hautes.","Avec les coudes légèrement fléchis, ouvre grand les bras.","Rapproche les mains devant la poitrine comme pour serrer quelqu'un dans tes bras.","Reviens lentement à la position de départ.","Répète."],"image_main":null,"image_start":"/exercises/cable-fly/start.webp","image_end":"/exercises/cable-fly/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cable-fly"],"attribution_required":true,"exportable":false},
{"id":"73e000e8-7447-5e9c-8f24-e1f11e0d20cf","key":"cable-front-raise","name_fr":"Élévation frontale à la poulie","name_en":"Cable Front Raise","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"front-raise","variant_of":null,"equipment":["cable"],"primary_muscles":["anterior_deltoid"],"secondary_muscles":["lateral_deltoid","pectoralis_major"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Tiens-toi debout dos à une poulie basse équipée d'une poignée.","Tiens la poignée bras tendu à hauteur de cuisse.","Lève le bras devant toi jusqu'à hauteur d'épaules en le gardant tendu.","Marque une pause en haut.","Redescends sous contrôle et répète."],"image_main":null,"image_start":"/exercises/cable-front-raise/start.webp","image_end":"/exercises/cable-front-raise/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cable-front-raise"],"attribution_required":true,"exportable":false},
{"id":"6494188a-7c9a-5a62-b15a-88e20cd31f0b","key":"cable-hammer-curl","name_fr":"Curl marteau à la poulie","name_en":"Cable Hammer Curl","aliases_fr":["Curl corde à la poulie"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["cable"],"primary_muscles":["biceps_brachii","brachialis","brachioradialis"],"secondary_muscles":["forearm_flexors"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms","pull"],"instructions_fr":["Fixe une corde à une poulie basse et place-toi face à la machine.","Prends la corde en prise neutre (marteau), paumes face à face.","Monte la corde vers les épaules en gardant les coudes collés au corps.","Serre en haut, puis redescends lentement jusqu'à l'extension complète.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/cable-hammer-curl/start.webp","image_end":"/exercises/cable-hammer-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cable-hammer-curl"],"attribution_required":true,"exportable":false},
{"id":"73554192-f1cd-542d-993e-5abc3848e61f","key":"cable-kickback","name_fr":"Kickback fessier à la poulie","name_en":"Cable Glute Kickback","aliases_fr":["Extension de hanche à la poulie"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["cable"],"primary_muscles":["gluteus_maximus"],"secondary_muscles":["hamstrings"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["arms","push"],"instructions_fr":["Fixe une chevillère sur une poulie basse et attache-la autour d'une cheville.","Place-toi face à la machine, tiens légèrement le bâti pour l'équilibre et penche-toi un peu en avant depuis les hanches.","Envoie la jambe équipée droit vers l'arrière, en étendant complètement la hanche, genou presque tendu.","Serre le fessier en extension complète de la hanche, puis ramène lentement le pied au départ.","Fais toutes les répétitions d'un côté avant de changer."],"image_main":null,"image_start":"/exercises/cable-kickback/start.webp","image_end":"/exercises/cable-kickback/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cable-kickback"],"attribution_required":true,"exportable":false},
{"id":"6fa9e93a-4563-5241-ab4b-dade4326c8e9","key":"cable-lateral-raise","name_fr":"Élévations latérales à la poulie à un bras","name_en":"Cable Lateral Raise","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["cable"],"primary_muscles":["lateral_deltoid"],"secondary_muscles":["anterior_deltoid","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["shoulders","push"],"instructions_fr":["Place-toi de côté face à une poulie basse et attrape la poignée avec la main la plus éloignée de la machine.","Garde le coude légèrement fléchi et laisse le câble passer devant ton corps.","Monte le bras sur le côté jusqu'à ce qu'il soit parallèle au sol.","Redescends en contrôlant. Fais toutes les répétitions d'un côté, puis change.","Garde la tension en continu : ne laisse pas la charge se poser en bas."],"image_main":null,"image_start":"/exercises/cable-lateral-raise/start.webp","image_end":"/exercises/cable-lateral-raise/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cable-lateral-raise"],"attribution_required":true,"exportable":false},
{"id":"2d2a2a31-d5a7-5470-b58c-9a23db7c0ca4","key":"cable-overhead-tricep-extension","name_fr":"Extension triceps poulie au-dessus de la tête","name_en":"Cable Overhead Tricep Extension","aliases_fr":["Extension triceps corde poulie basse"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-tricep-extension","variant_of":null,"equipment":["cable"],"primary_muscles":["triceps_brachii"],"secondary_muscles":["anterior_deltoid"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Fixe une corde à la poulie basse et choisis une charge légère.","Prends la corde à deux mains, tourne le dos au poids et fais un pas en avant en fente décalée pour que le câble te tire en arrière.","Monte la corde au-dessus de la tête, coudes fléchis et bras près des oreilles, mains derrière la tête.","Gaine le buste et garde les bras immobiles, puis tends les coudes pour pousser la corde vers le haut jusqu'à l'extension complète des bras.","Marque une courte pause en haut, puis fléchis les coudes pour redescendre la corde derrière la tête en contrôlant.","Répète pour le nombre de répétitions prévu."],"image_main":null,"image_start":"/exercises/cable-overhead-tricep-extension/start.webp","image_end":"/exercises/cable-overhead-tricep-extension/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cable-overhead-tricep-extension"],"attribution_required":true,"exportable":false},
{"id":"bca287a2-3750-51bd-b3c9-aa6119d2a62f","key":"cable-pallof-press","name_fr":"Pallof press à la poulie","name_en":"Cable Pallof Press","aliases_fr":[],"aliases_en":["Pallof press"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["cable"],"primary_muscles":["obliques","transverse_abdominis"],"secondary_muscles":["anterior_deltoid","erector_spinae","gluteus_medius","rectus_abdominis"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["core"],"instructions_fr":["Règle la poulie à hauteur de poitrine et prends la poignée à deux mains, de côté par rapport à la machine.","Éloigne-toi jusqu'à sentir une vraie tension sur le câble, pieds écartés à largeur d'épaules et genoux légèrement fléchis.","Amène la poignée au centre de la poitrine et gaine le tronc et les fessiers.","Pousse la poignée droit devant toi jusqu'à tendre les bras, en résistant à la traction qui veut te faire pivoter vers la machine.","Reste un instant bras tendus, puis ramène la poignée vers la poitrine en contrôlant.","Fais le nombre de répétitions voulu, puis retourne-toi et recommence de l'autre côté."],"image_main":null,"image_start":"/exercises/cable-pallof-press/start.webp","image_end":"/exercises/cable-pallof-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cable-pallof-press"],"attribution_required":true,"exportable":false},
{"id":"c6ebb5d7-6603-5b61-b944-881fdc416444","key":"cable-pull-through","name_fr":"Pull-through à la poulie","name_en":"Cable Pull-Through","aliases_fr":["Tirage entre les jambes à la poulie"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"deadlift","variant_of":null,"equipment":["cable"],"primary_muscles":["gluteus_maximus","hamstrings"],"secondary_muscles":["erector_spinae"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs","glutes"],"instructions_fr":["Fixe une corde à la poulie basse et place-toi dos à la machine, la corde passant entre les jambes.","Avance d'un pas jusqu'à ce que le câble soit tendu, puis gaine le tronc et assouplis les genoux.","Pousse les hanches vers l'arrière en gardant la colonne neutre et les bras tendus.","Pousse les hanches vers l'avant et contracte les fessiers pour te redresser.","Enchaîne sur la charnière suivante sans laisser retomber les poids."],"image_main":null,"image_start":"/exercises/cable-pull-through/start.webp","image_end":"/exercises/cable-pull-through/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cable-pull-through"],"attribution_required":true,"exportable":false},
{"id":"d0a926d6-a89e-5da4-895d-013eb01a3b5c","key":"cable-reverse-fly","name_fr":"Oiseau à la poulie","name_en":"Cable Reverse Fly","aliases_fr":["Oiseau poulies croisées"],"aliases_en":["Cable rear delt fly"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"reverse-fly","variant_of":null,"equipment":["cable"],"primary_muscles":["posterior_deltoid"],"secondary_muscles":["rhomboids","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull"],"instructions_fr":["Règle les deux poulies à hauteur d'épaules et place-toi au centre, entre les deux tours de poulie.","Prends la poignée gauche de la main droite et la poignée droite de la main gauche, pour que les câbles se croisent devant toi.","Tiens-toi droit, bras tendus devant toi à hauteur d'épaules, avec une légère flexion des coudes.","Ouvre les bras vers l'extérieur et vers l'arrière en un large arc, en menant avec les coudes, jusqu'à les aligner avec les épaules.","Serre brièvement les omoplates sans cambrer le bas du dos.","Ramène lentement les poignées en position croisée de départ et répète pour le nombre de répétitions prévu."],"image_main":null,"image_start":"/exercises/cable-reverse-fly/start.webp","image_end":"/exercises/cable-reverse-fly/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cable-reverse-fly"],"attribution_required":true,"exportable":false},
{"id":"e37600bf-cfa6-50a7-ad9b-7433d3e448ec","key":"cable-tricep-kickback","name_fr":"Kickback triceps à la poulie","name_en":"Cable Tricep Kickback","aliases_fr":["Extension triceps buste penché à la poulie"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"tricep-kickback","variant_of":null,"equipment":["cable"],"primary_muscles":["triceps_brachii"],"secondary_muscles":["posterior_deltoid"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Fixe une poignée sur une poulie basse et penche le buste vers l'avant en charnière de hanches.","Colle le haut du bras contre ton flanc, coude fléchi à 90 degrés.","Étends le coude pour pousser la poignée vers l'arrière.","Serre les triceps en fin de mouvement.","Reviens en contrôlant. Fais toutes les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/cable-tricep-kickback/start.webp","image_end":"/exercises/cable-tricep-kickback/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cable-tricep-kickback"],"attribution_required":true,"exportable":false},
{"id":"a36aa6d1-600f-57e8-bf60-7711ef393690","key":"cable-upright-row","name_fr":"Tirage menton à la poulie","name_en":"Cable Upright Row","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"upright-row","variant_of":null,"equipment":["cable"],"primary_muscles":["lateral_deltoid","trapezius"],"secondary_muscles":["anterior_deltoid","biceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Place-toi face à une poulie et attrape une barre droite ou une corde à hauteur de cuisses.","Tire la barre vers le menton en menant avec les coudes.","Redescends en contrôlant.","Répète."],"image_main":null,"image_start":"/exercises/cable-upright-row/start.webp","image_end":"/exercises/cable-upright-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cable-upright-row"],"attribution_required":true,"exportable":false},
{"id":"25fe1f6f-fca8-5f7e-90f3-0f2b8d50df1e","key":"cable-wrist-curl","name_fr":"Curl poignets à la poulie","name_en":"Cable Wrist Curl","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"wrist-curl","variant_of":null,"equipment":["cable"],"primary_muscles":["forearm_flexors"],"secondary_muscles":[],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Fixe une barre droite courte sur une poulie basse et assieds-toi sur un banc plat face à la poulie, pieds à plat au sol.","Prends la barre en supination, paumes vers le haut, mains à peu près à largeur d'épaules.","Pose les avant-bras sur les cuisses, poignets et mains dépassant juste après les genoux.","Laisse le câble tirer les poignets vers le bas jusqu'à sentir un étirement dans les avant-bras.","Remonte la barre en fléchissant les poignets, avant-bras toujours posés sur les cuisses.","Redescends la barre en contrôlant et répète pour le nombre de répétitions prévu."],"image_main":null,"image_start":"/exercises/cable-wrist-curl/start.webp","image_end":"/exercises/cable-wrist-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cable-wrist-curl"],"attribution_required":true,"exportable":false},
{"id":"36751d39-e069-57bf-84d0-404a6560a4b9","key":"calf-raise-hold","name_fr":"Maintien sur la pointe des pieds","name_en":"Calf Raise Hold","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"calf-raise","variant_of":null,"equipment":[],"primary_muscles":["gastrocnemius"],"secondary_muscles":["soleus"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":["legs","calves"],"instructions_fr":["Tiens-toi bien droit, pieds à peu près à largeur de hanches, les bras relâchés le long du corps.","Pousse sur l'avant des pieds et monte sur la pointe des pieds le plus haut possible.","Garde les genoux tendus et ton poids au milieu des pieds, sans rouler vers les petits orteils.","Arrête-toi en haut et tiens la position, talons le plus haut possible.","Garde les hanches de niveau, la poitrine haute et la respiration lente pendant la durée prévue.","Redescends les talons lentement au sol et récupère."],"image_main":"/exercises/calf-raise-hold/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-calf-raise-hold"],"attribution_required":true,"exportable":false},
{"id":"5bf24533-1626-52e2-b2c1-6cb7a8c5f980","key":"camel-pose","name_fr":"Posture du chameau","name_en":"Camel Pose","aliases_fr":[],"aliases_en":["Ustrasana"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["erector_spinae","hip_flexors"],"secondary_muscles":["pectoralis_major","quadriceps"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Mets-toi à genoux, genoux écartés à largeur de hanches, hanches à l'aplomb des genoux.","Pose les mains au bas du dos, doigts vers le bas, et sors la poitrine.","Pousse les hanches vers l'avant et cambre-toi en arrière, en allant chercher les talons si la position reste confortable.","Tiens la posture le temps prévu, la nuque dans l'alignement de la colonne.","Ramène les mains au bassin et remonte en menant avec la poitrine."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-camel-pose"],"attribution_required":true,"exportable":false},
{"id":"cc51ebf5-66d0-5b0d-9b9e-0879fad76635","key":"captains-chair-knee-raise","name_fr":"Relevé de genoux à la chaise romaine","name_en":"Captain's Chair Knee Raise","aliases_fr":["Relevé de genoux en appui sur les avant-bras"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["hip_flexors","rectus_abdominis"],"secondary_muscles":["obliques","transverse_abdominis"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["core"],"instructions_fr":["Installe-toi sur la chaise romaine, dos bien plaqué contre le dossier et avant-bras sur les accoudoirs.","Laisse tes jambes pendre à la verticale.","Gaine les abdominaux et monte les genoux vers la poitrine.","Marque une courte pause en haut, puis redescends lentement jusqu'à la position de départ.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/captains-chair-knee-raise/start.webp","image_end":"/exercises/captains-chair-knee-raise/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-captains-chair-knee-raise"],"attribution_required":true,"exportable":false},
{"id":"b2ac8ae6-8403-5529-9775-9841c04585e1","key":"captains-chair-leg-raise","name_fr":"Relevé de jambes à la chaise romaine","name_en":"Captain's Chair Leg Raise","aliases_fr":["Relevé de jambes en appui sur les avant-bras"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["hip_flexors","rectus_abdominis"],"secondary_muscles":["obliques","transverse_abdominis"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["core"],"instructions_fr":["Installe-toi sur la chaise romaine, dos bien plaqué contre le dossier et avant-bras sur les accoudoirs.","Laisse tes jambes pendre à la verticale.","Jambes tendues, monte-les jusqu'à la parallèle au sol ou plus haut.","Marque une courte pause en haut, puis redescends lentement.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/captains-chair-leg-raise/start.webp","image_end":"/exercises/captains-chair-leg-raise/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-captains-chair-leg-raise"],"attribution_required":true,"exportable":false},
