{"id":"4915257e-72f7-53ea-9ecf-0926269c896c","key":"cat-cow","name_fr":"Chat-vache","name_en":"Cat-Cow","aliases_fr":["Mobilité dos chat-vache"],"aliases_en":["Cat cow","Cat cow spinal mobility"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["erector_spinae","rectus_abdominis"],"secondary_muscles":["transverse_abdominis","trapezius"],"difficulty":"beginner","metrics":["reps","duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Mets-toi à quatre pattes, mains sous les épaules et genoux sous les hanches.","Expire et arrondis la colonne vers le plafond, en rentrant le coccyx et en laissant la tête tomber.","Inspire et fais l'inverse : laisse le ventre descendre, relève la poitrine et le coccyx, et regarde légèrement devant toi.","Passe lentement d'une position à l'autre, une respiration par position.","Termine avec la colonne neutre et assieds-toi sur les talons."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-cat-cow","coory-cat-cow-spinal-mobility"],"attribution_required":true,"exportable":false},
{"id":"d3690b53-58a9-5951-b5d3-c41104784c5c","key":"cat-stretch","name_fr":"Étirement du chat","name_en":"Cat Stretch","aliases_fr":[],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["erector_spinae"],"secondary_muscles":["rhomboids","trapezius"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Mets-toi à quatre pattes, mains sous les épaules et genoux sous les hanches.","Arrondis la colonne vers le plafond.","Rentre le menton vers la poitrine.","Tiens la position 20 à 30 secondes en respirant calmement."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-cat-stretch"],"attribution_required":true,"exportable":false},
{"id":"558b6c2a-eca2-53bd-b724-d3b33b296384","key":"chair-pose","name_fr":"Posture de la chaise","name_en":"Chair Pose","aliases_fr":["Utkatasana"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["anterior_deltoid","erector_spinae"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":["calisthenics"],"instructions_fr":["Tiens-toi debout, pieds joints ou à largeur de hanches, le poids dans les talons.","Fléchis les genoux et envoie les hanches vers l'arrière, comme pour t'asseoir sur une chaise.","Lève les bras au-dessus de la tête, le long des oreilles, sans ouvrir les côtes.","Tiens la position pendant la durée prévue, poitrine haute et genoux dans l'axe des orteils.","Pousse dans les talons pour te relever."],"image_main":"/exercises/chair-pose/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-chair-pose"],"attribution_required":true,"exportable":false},
{"id":"328613be-1b0f-5674-8d4a-b391b0a6a71e","key":"cheat-curl","name_fr":"Curl triche","name_en":"Cheat Curl","aliases_fr":["Curl avec élan"],"aliases_en":["Cheating curl"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["barbell"],"primary_muscles":["biceps_brachii"],"secondary_muscles":["brachialis","brachioradialis","erector_spinae"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Tiens-toi debout avec une charge à hauteur des cuisses, en supination.","Utilise une légère impulsion des hanches pour lancer le curl.","Monte la charge vers les épaules de façon explosive.","Redescends la charge lentement et de façon contrôlée sur toute l'amplitude.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/cheat-curl/start.webp","image_end":"/exercises/cheat-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cheat-curl"],"attribution_required":true,"exportable":false},
{"id":"ffefc491-95c7-5518-9725-6575a2e94839","key":"chest-press-machine","name_fr":"Développé couché à la machine","name_en":"Machine Chest Press","aliases_fr":["Chest press"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bench-press","variant_of":null,"equipment":["chest_press_machine"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid","triceps_brachii"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Assieds-toi dans la machine, le dos bien à plat contre le dossier.","Prends les poignées à hauteur de poitrine.","Pousse les poignées vers l'avant jusqu'à l'extension complète des bras.","Reviens lentement à la position de départ.","Répète."],"image_main":null,"image_start":"/exercises/chest-press-machine/start.webp","image_end":"/exercises/chest-press-machine/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-chest-press-machine"],"attribution_required":true,"exportable":false},
{"id":"cc0479f2-38f7-5a8f-9c39-abc6001c1518","key":"chest-supported-db-row","name_fr":"Rowing haltères buste appuyé","name_en":"Chest-Supported Dumbbell Row","aliases_fr":["Rowing haltères sur banc incliné"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"row","variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["latissimus_dorsi","rhomboids"],"secondary_muscles":["biceps_brachii","posterior_deltoid"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull"],"instructions_fr":["Allonge-toi sur le ventre sur un banc incliné, haltères pendant sous toi.","Tire les haltères vers le haut, le long de tes flancs.","Serre en haut, puis redescends.","Répète."],"image_main":null,"image_start":"/exercises/chest-supported-db-row/start.webp","image_end":"/exercises/chest-supported-db-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-chest-supported-db-row"],"attribution_required":true,"exportable":false},
{"id":"6c7208ed-1e83-5d3a-ace2-71ad1e68263b","key":"chest-supported-dumbbell-shrug","name_fr":"Shrugs haltères buste appuyé","name_en":"Chest Supported Dumbbell Shrug","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"shrug","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["trapezius"],"secondary_muscles":["posterior_deltoid","rhomboids"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Règle un banc incliné à environ 30 degrés.","Allonge-toi sur le ventre sur le banc, haltères tenus bras tendus.","Hausse les épaules vers le haut et l'arrière, vers les oreilles.","Serre le haut des trapèzes en haut.","Redescends de façon contrôlée et répète."],"image_main":null,"image_start":"/exercises/chest-supported-dumbbell-shrug/start.webp","image_end":"/exercises/chest-supported-dumbbell-shrug/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-chest-supported-dumbbell-shrug"],"attribution_required":true,"exportable":false},
{"id":"03bafa6f-fa23-5cae-967c-343e84d79c7f","key":"chest-supported-kettlebell-row","name_fr":"Rowing kettlebell buste appuyé","name_en":"Chest-Supported Kettlebell Row","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"row","variant_of":null,"equipment":["kettlebell","bench"],"primary_muscles":["latissimus_dorsi","rhomboids"],"secondary_muscles":["biceps_brachii","posterior_deltoid","trapezius"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull"],"instructions_fr":["Allonge-toi sur le ventre sur un banc incliné, bras pendant librement avec un kettlebell dans chaque main.","Gaine les abdominaux et rapproche les omoplates.","Tire les kettlebells vers tes hanches en serrant les omoplates.","Marque une brève pause en haut, en sentant la contraction dans le dos.","Redescends lentement les kettlebells à la position de départ de façon contrôlée."],"image_main":null,"image_start":"/exercises/chest-supported-kettlebell-row/start.webp","image_end":"/exercises/chest-supported-kettlebell-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-chest-supported-kettlebell-row"],"attribution_required":true,"exportable":false},
{"id":"2f4202ba-c6dc-52dc-b6d6-3e0dc923a1c5","key":"chest-supported-machine-row","name_fr":"Rowing à la machine buste appuyé","name_en":"Chest-Supported Machine Row","aliases_fr":["Tirage horizontal machine"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"row","variant_of":null,"equipment":["seated_row_machine"],"primary_muscles":["latissimus_dorsi","rhomboids"],"secondary_muscles":["biceps_brachii","posterior_deltoid","trapezius"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull"],"instructions_fr":["Règle le siège pour que les poignées soient à hauteur du bas de la poitrine, puis assieds-toi la poitrine contre le coussin et les pieds bien posés.","Avance les bras pour saisir les poignées, bras tendus et épaules relâchées.","Gaine le tronc, puis tire les poignées vers l'arrière en emmenant les coudes derrière toi.","Serre les omoplates en fin de tirage sans décoller la poitrine du coussin.","Marque une brève pause, puis tends les bras pour ramener les poignées vers l'avant de façon contrôlée.","Répète pour le nombre de répétitions prévu, en gardant la poitrine sur le coussin tout du long."],"image_main":null,"image_start":"/exercises/chest-supported-machine-row/start.webp","image_end":"/exercises/chest-supported-machine-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-chest-supported-machine-row"],"attribution_required":true,"exportable":false},
{"id":"0324bb5a-f765-56ae-b3ca-7ad43f037463","key":"chest-supported-smith-machine-row","name_fr":"Rowing à la Smith machine buste appuyé","name_en":"Chest-Supported Smith Machine Row","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"row","variant_of":null,"equipment":["smith_machine","bench"],"primary_muscles":["latissimus_dorsi","rhomboids"],"secondary_muscles":["biceps_brachii","posterior_deltoid"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull"],"instructions_fr":["Place un banc incliné dans la Smith machine face à la barre, et règle la barre assez bas pour que tes bras pendent à la verticale quand tu t'appuies sur le coussin.","Tiens-toi à califourchon sur le banc, pieds bien posés, la poitrine appuyée contre le haut du coussin.","Saisis la barre en pronation, un peu plus large que les épaules, et décroche-la, bras tendus.","Tire la barre vers le bas de la poitrine en menant avec les coudes et en serrant les omoplates en haut.","Redescends la barre de façon contrôlée jusqu'à avoir de nouveau les bras tendus, et répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/chest-supported-smith-machine-row/start.webp","image_end":"/exercises/chest-supported-smith-machine-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-chest-supported-smith-machine-row"],"attribution_required":true,"exportable":false},
{"id":"53c1eb63-057f-500c-8d1a-3898091a6383","key":"childs-pose","name_fr":"Posture de l'enfant","name_en":"Child's Pose","aliases_fr":[],"aliases_en":["Balasana"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["erector_spinae","latissimus_dorsi"],"secondary_muscles":["trapezius"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Mets-toi à genoux et recule les hanches vers les talons.","Plie le buste vers l'avant sur les cuisses.","Tends les deux bras au sol devant toi.","Tiens la position 20 à 30 secondes en respirant calmement."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-childs-pose"],"attribution_required":true,"exportable":false},
{"id":"ebb83f64-c1a3-52e4-976c-4c8a3c9c22ad","key":"chin-tuck-hold","name_fr":"Maintien rétraction du menton","name_en":"Chin Tuck Hold","aliases_fr":["Rétraction cervicale"],"aliases_en":["Chin tuck"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["trapezius"],"secondary_muscles":["rhomboids"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Tiens-toi debout ou assis bien droit, épaules relâchées.","Recule le menton tout droit vers l'arrière, comme pour faire un double menton.","Garde la tête de niveau, sans l'incliner.","Tiens la position pendant la durée voulue.","Relâche et enchaîne les séries."],"image_main":"/exercises/chin-tuck-hold/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-chin-tuck-hold"],"attribution_required":true,"exportable":false},
{"id":"b36cb734-41ba-5bec-ab27-d4455615af66","key":"chin-ups","name_fr":"Tractions supination","name_en":"Chin-Ups","aliases_fr":["Chin-ups"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"pull-up","variant_of":null,"equipment":["pull_up_bar"],"primary_muscles":["biceps_brachii","latissimus_dorsi"],"secondary_muscles":["rhomboids"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":false,"tags":["calisthenics","pull"],"instructions_fr":["Suspends-toi à une barre, prise en supination à largeur d'épaules.","Tire-toi jusqu'à ce que le menton passe au-dessus de la barre.","Redescends en contrôlant.","Répète."],"image_main":null,"image_start":"/exercises/chin-ups/start.webp","image_end":"/exercises/chin-ups/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-chin-ups"],"attribution_required":true,"exportable":false},
{"id":"750dd7bf-6b9d-5b96-ba36-1dd94c9e5ec0","key":"clamshells","name_fr":"Clamshell","name_en":"Clamshells","aliases_fr":["Coquillage"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"hip-abduction","variant_of":null,"equipment":[],"primary_muscles":["abductors","gluteus_medius"],"secondary_muscles":["gluteus_maximus"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Allonge-toi sur le côté, genoux fléchis et empilés.","Garde les pieds joints et les hanches empilées.","Ouvre le genou du dessus vers le plafond sans faire pivoter les hanches.","Contracte le fessier externe en haut.","Redescends sous contrôle. Fais toutes les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/clamshells/start.webp","image_end":"/exercises/clamshells/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-clamshells"],"attribution_required":true,"exportable":false},
{"id":"032caccb-562b-5372-b3f8-ad94f29c7df3","key":"clamshells-hold","name_fr":"Clamshell isométrique","name_en":"Clamshell Hold","aliases_fr":["Maintien clamshell"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"hip-abduction","variant_of":null,"equipment":[],"primary_muscles":["abductors","gluteus_medius"],"secondary_muscles":["gluteus_maximus"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Allonge-toi sur le côté, hanches et genoux fléchis à environ 45 et 90 degrés, talons joints et genoux empilés.","Empile épaules et hanches à la verticale et gaine le tronc pour que le bassin ne bascule pas en arrière.","Ouvre le genou du dessus aussi loin que possible sans que le bassin pivote, talons toujours en contact.","Maintiens cette position ouverte pendant le temps prévu, en respirant normalement.","Redescends le genou sous contrôle et répète de l'autre côté."],"image_main":"/exercises/clamshells-hold/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-clamshells-hold"],"attribution_required":true,"exportable":false},
{"id":"efd30d51-d996-5cc4-b931-7302d05c4b6c","key":"clap-push-ups","name_fr":"Pompes claquées","name_en":"Clap Push-Ups","aliases_fr":["Clap push-ups"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"push-up","variant_of":null,"equipment":[],"primary_muscles":["pectoralis_major"],"secondary_muscles":["triceps_brachii"],"difficulty":"advanced","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["calisthenics"],"instructions_fr":["Mets-toi en position de pompe classique.","Descends la poitrine vers le sol.","Pousse de façon explosive pour décoller les mains du sol.","Tape dans les mains, réceptionne-toi en douceur et reviens au départ.","Répète."],"image_main":null,"image_start":"/exercises/clap-push-ups/start.webp","image_end":"/exercises/clap-push-ups/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-clap-push-ups"],"attribution_required":true,"exportable":false},
{"id":"0bf1570b-2eb7-5b8b-a127-cc47f46f79c3","key":"clean","name_fr":"Épaulé","name_en":"Clean","aliases_fr":["Squat clean"],"aliases_en":["Barbell clean"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"clean","variant_of":null,"equipment":["barbell"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["anterior_deltoid","erector_spinae","hamstrings","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg"],"unilateral":false,"bodyweight":false,"tags":["olympic_lifting"],"instructions_fr":["Place-toi au-dessus d'une barre chargée, pieds à largeur de hanches.","Saisis la barre juste à l'extérieur des genoux, en pronation.","Pousse fort avec les jambes et étends les hanches de façon explosive.","Passe sous la barre et réceptionne-la sur l'avant des épaules.","Redresse-toi complètement pour terminer le mouvement."],"image_main":null,"image_start":"/exercises/clean/start.webp","image_end":"/exercises/clean/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-clean"],"attribution_required":true,"exportable":false},
{"id":"4117b551-f00d-5719-a33c-ac33659e6c30","key":"clean-and-jerk","name_fr":"Épaulé-jeté","name_en":"Clean and Jerk","aliases_fr":[],"aliases_en":["Clean & jerk"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"clean","variant_of":null,"equipment":["barbell"],"primary_muscles":["anterior_deltoid","gluteus_maximus","quadriceps"],"secondary_muscles":["erector_spinae","trapezius","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg"],"unilateral":false,"bodyweight":false,"tags":["olympic_lifting"],"instructions_fr":["Tire une barre chargée du sol jusqu'aux épaules comme pour un épaulé.","Redresse-toi complètement, barre en appui sur l'avant des épaules.","Fléchis légèrement les jambes et envoie la barre au-dessus de la tête de façon explosive.","Descends en demi-squat sous la barre pendant que tes bras se verrouillent, pieds à peu près à largeur de hanches.","Redresse-toi complètement et stabilise la barre au-dessus de la tête avant de la redescendre."],"image_main":null,"image_start":"/exercises/clean-and-jerk/start.webp","image_end":"/exercises/clean-and-jerk/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-clean-and-jerk"],"attribution_required":true,"exportable":false},
{"id":"3e45f37b-2f6c-520b-994c-a1a94a402a1e","key":"close-grip-barbell-curl","name_fr":"Curl barre prise serrée","name_en":"Close-Grip Barbell Curl","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"barbell-curl","variant_of":null,"equipment":["barbell"],"primary_muscles":["biceps_brachii"],"secondary_muscles":["brachialis","brachioradialis"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull","arms"],"instructions_fr":["Tiens-toi debout avec une barre en prise supination, les mains plus rapprochées que la largeur des épaules.","Pars avec la barre à hauteur des cuisses, bras tendus, coudes collés au corps.","Monte la barre jusqu'aux épaules en fléchissant les coudes.","Serre les biceps en haut, puis redescends de façon contrôlée.","Répète pour le nombre de répétitions recommandé."],"image_main":null,"image_start":"/exercises/close-grip-barbell-curl/start.webp","image_end":"/exercises/close-grip-barbell-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-close-grip-barbell-curl"],"attribution_required":true,"exportable":false},
{"id":"17ac297a-84e6-53a6-ba35-5de00be14989","key":"close-grip-bench-press","name_fr":"Développé couché prise serrée","name_en":"Close-Grip Bench Press","aliases_fr":[],"aliases_en":["CGBP"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bench-press","variant_of":null,"equipment":["barbell","bench"],"primary_muscles":["triceps_brachii"],"secondary_muscles":["anterior_deltoid","pectoralis_major"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms","push"],"instructions_fr":["Allonge-toi sur un banc plat et prends la barre à largeur d'épaules.","Descends la barre vers le bas de la poitrine en gardant les coudes près du corps.","Repousse jusqu'à l'extension complète.","Répète."],"image_main":null,"image_start":"/exercises/close-grip-bench-press/start.webp","image_end":"/exercises/close-grip-bench-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-close-grip-bench-press"],"attribution_required":true,"exportable":false},
{"id":"389e23bd-ae5e-5f17-b607-ba4ebef08041","key":"close-grip-db-bench-press","name_fr":"Développé couché haltères prise serrée","name_en":"Close-Grip Dumbbell Bench Press","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bench-press","variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["triceps_brachii"],"secondary_muscles":["anterior_deltoid","pectoralis_major"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms","push"],"instructions_fr":["Allonge-toi sur un banc plat et tiens deux haltères collés l'un à l'autre au-dessus de la poitrine.","Descends-les vers la poitrine en gardant les coudes près du corps.","Repousse vers le haut.","Répète."],"image_main":null,"image_start":"/exercises/close-grip-db-bench-press/start.webp","image_end":"/exercises/close-grip-db-bench-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-close-grip-db-bench-press"],"attribution_required":true,"exportable":false},
{"id":"dfe5a909-e8d6-573b-8660-f0abf33058d4","key":"close-grip-ez-bar-bench-press","name_fr":"Développé couché barre EZ prise serrée","name_en":"Close-Grip EZ-Bar Bench Press","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bench-press","variant_of":null,"equipment":["ez_bar","bench"],"primary_muscles":["triceps_brachii"],"secondary_muscles":["anterior_deltoid","pectoralis_major"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms","push"],"instructions_fr":["Allonge-toi sur un banc plat et prends la barre EZ dans les courbes intérieures.","Descends la barre vers la poitrine, coudes serrés.","Repousse jusqu'à l'extension complète.","Répète."],"image_main":null,"image_start":"/exercises/close-grip-ez-bar-bench-press/start.webp","image_end":"/exercises/close-grip-ez-bar-bench-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-close-grip-ez-bar-bench-press"],"attribution_required":true,"exportable":false},
{"id":"6760b32a-669e-5202-989f-46f2d1a3af34","key":"close-grip-ez-bar-curl","name_fr":"Curl barre EZ prise serrée","name_en":"Close-Grip EZ-Bar Curl","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["ez_bar"],"primary_muscles":["biceps_brachii"],"secondary_muscles":["brachialis"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms","pull"],"instructions_fr":["Tiens-toi debout avec une barre EZ, les mains dans les courbes intérieures, paumes vers le haut.","Garde les coudes collés au corps.","Monte la barre à hauteur des épaules en serrant les biceps.","Redescends de façon contrôlée jusqu'à l'étirement complet.","Répète pour le nombre de répétitions prescrit."],"image_main":null,"image_start":"/exercises/close-grip-ez-bar-curl/start.webp","image_end":"/exercises/close-grip-ez-bar-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-close-grip-ez-bar-curl"],"attribution_required":true,"exportable":false},
{"id":"80b6a256-08e4-5ec6-86bf-7c92f7a43dff","key":"close-grip-incline-bench","name_fr":"Développé incliné barre prise serrée","name_en":"Close-Grip Incline Bench Press","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bench-press","variant_of":null,"equipment":["barbell","bench"],"primary_muscles":["triceps_brachii"],"secondary_muscles":["anterior_deltoid","pectoralis_major"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms"],"instructions_fr":["Règle le banc en position inclinée. Prends la barre à largeur d'épaules ou plus serré.","Descends la barre vers le haut de la poitrine.","Repousse vers le haut.","Répète."],"image_main":null,"image_start":"/exercises/close-grip-incline-bench/start.webp","image_end":"/exercises/close-grip-incline-bench/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-close-grip-incline-bench"],"attribution_required":true,"exportable":false},
{"id":"dbd4d48a-1867-5794-9d85-4124a782fdd3","key":"close-grip-lat-pulldown","name_fr":"Tirage vertical prise serrée","name_en":"Close Grip Lat Pulldown","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"pull-up","variant_of":null,"equipment":["cable"],"primary_muscles":["latissimus_dorsi"],"secondary_muscles":["biceps_brachii","brachialis","posterior_deltoid","rhomboids"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Assieds-toi à la machine de tirage vertical et cale tes cuisses sous le coussin.","Prends la poignée prise serrée, paumes face à face.","Tire la poignée vers le haut de la poitrine.","Contracte les dorsaux en bas.","Remonte en contrôlant et répète."],"image_main":null,"image_start":"/exercises/close-grip-lat-pulldown/start.webp","image_end":"/exercises/close-grip-lat-pulldown/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-close-grip-lat-pulldown"],"attribution_required":true,"exportable":false},
{"id":"c505e730-e2fc-53cd-9713-895dc6523045","key":"close-grip-pull-ups","name_fr":"Tractions pronation prise serrée","name_en":"Close-Grip Pull-Ups","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"pull-up","variant_of":null,"equipment":["pull_up_bar"],"primary_muscles":["biceps_brachii","latissimus_dorsi"],"secondary_muscles":["rhomboids"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":false,"tags":["calisthenics"],"instructions_fr":["Suspends-toi à une barre de traction, mains à largeur d'épaules ou plus serrées, paumes vers l'avant.","Tire-toi jusqu'à ce que le menton passe au-dessus de la barre.","Redescends en contrôlant.","Répète."],"image_main":null,"image_start":"/exercises/close-grip-pull-ups/start.webp","image_end":"/exercises/close-grip-pull-ups/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-close-grip-pull-ups"],"attribution_required":true,"exportable":false},
{"id":"95845cd4-4d14-5623-84f8-9c38e7276adc","key":"close-grip-push-ups","name_fr":"Pompes prise serrée","name_en":"Close Grip Push Ups","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"push-up","variant_of":null,"equipment":[],"primary_muscles":["pectoralis_major","triceps_brachii"],"secondary_muscles":["anterior_deltoid","serratus_anterior"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Mets-toi en position de pompe, mains juste sous les épaules.","Garde les coudes collés contre les côtes.","Descends la poitrine vers le sol.","Repousse jusqu'à la position de départ.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/close-grip-push-ups/start.webp","image_end":"/exercises/close-grip-push-ups/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-close-grip-push-ups"],"attribution_required":true,"exportable":false},
{"id":"27d35e31-9103-5ca3-98cc-4ddc9c357cb7","key":"close-stance-leg-press","name_fr":"Presse à cuisses pieds serrés","name_en":"Close-Stance Leg Press","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"leg-press","variant_of":null,"equipment":["leg_press"],"primary_muscles":["quadriceps"],"secondary_muscles":["gluteus_maximus","hamstrings"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs"],"instructions_fr":["Règle le siège et le dossier pour que ton bas du dos reste appuyé pendant toute la répétition.","Place les pieds proches l'un de l'autre au milieu de la plateforme, orteils et genoux dans la même direction.","Descends le chariot en fléchissant les genoux et les hanches, pieds à plat et genoux dans l'axe des orteils.","Pousse la plateforme avec tout le pied jusqu'à avoir les jambes tendues, sans verrouiller brutalement les genoux.","Reviens de façon contrôlée et répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/close-stance-leg-press/start.webp","image_end":"/exercises/close-stance-leg-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-close-stance-leg-press"],"attribution_required":true,"exportable":false},
{"id":"1c0c6e0b-ef76-54c5-910a-820f6dca4690","key":"cobra-stretch","name_fr":"Posture du cobra","name_en":"Cobra Stretch","aliases_fr":["Étirement cobra"],"aliases_en":["Cobra pose"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["rectus_abdominis"],"secondary_muscles":["hip_flexors","transverse_abdominis"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Allonge-toi sur le ventre, les mains sous les épaules.","Appuie sur les mains pour décoller la poitrine du sol.","Garde les hanches et les jambes au sol, les épaules relâchées.","Tiens la position 20 à 30 secondes en respirant calmement."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-cobra-stretch"],"attribution_required":true,"exportable":false},
{"id":"39082704-47a7-577a-813b-cf550b05d7ef","key":"cocoons","name_fr":"Cocoons","name_en":"Cocoons","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["rectus_abdominis"],"secondary_muscles":["hip_flexors","obliques"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["core","calisthenics"],"instructions_fr":["Allonge-toi sur le dos, bras tendus au-dessus de la tête et jambes tendues, légèrement décollées du sol.","Ramène en même temps les genoux vers la poitrine et les bras vers l'avant en faisant un crunch.","Essaie de toucher tes tibias avec les mains en haut du mouvement.","Inverse le mouvement en douceur, en étendant à nouveau bras et jambes jusqu'à la position suspendue.","Répète pour le nombre de répétitions recommandé."],"image_main":null,"image_start":"/exercises/cocoons/start.webp","image_end":"/exercises/cocoons/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cocoons"],"attribution_required":true,"exportable":false},
{"id":"b49bc2b4-3c8e-5ca5-8850-1885ca90dadf","key":"commando-pull-up","name_fr":"Commando pull-up","name_en":"Commando Pull-Up","aliases_fr":["Tractions commando"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"pull-up","variant_of":null,"equipment":["pull_up_bar"],"primary_muscles":["biceps_brachii","latissimus_dorsi"],"secondary_muscles":["brachialis","brachioradialis","forearm_flexors","obliques","rhomboids","trapezius"],"difficulty":"advanced","metrics":["reps","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull","calisthenics"],"instructions_fr":["Prends la barre avec une main devant l'autre, paumes face à face, et suspends-toi bras tendus, corps de profil.","Gaine le buste et abaisse les omoplates pour lancer le mouvement.","Tire-toi vers le haut en tirant les coudes vers le bas, jusqu'à ce que la tête passe la barre sur un côté.","Marque une courte pause en haut, poitrine proche de la barre.","Redescends en contrôlant jusqu'à la suspension complète.","Passe la tête de l'autre côté de la barre à la répétition suivante, ou inverse la position des mains à chaque série."],"image_main":null,"image_start":"/exercises/commando-pull-up/start.webp","image_end":"/exercises/commando-pull-up/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-commando-pull-up"],"attribution_required":true,"exportable":false},
{"id":"4db7f450-f338-5ca3-a049-b53a14d26688","key":"concentration-curl","name_fr":"Curl concentré","name_en":"Concentration Curl","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["biceps_brachii"],"secondary_muscles":["brachialis"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["arms"],"instructions_fr":["Assieds-toi sur un banc, jambes écartées, un haltère dans une main.","Cale ton coude contre l'intérieur de la cuisse.","Monte l'haltère vers l'épaule.","Redescends de façon contrôlée.","Répète des deux côtés."],"image_main":null,"image_start":"/exercises/concentration-curl/start.webp","image_end":"/exercises/concentration-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-concentration-curl"],"attribution_required":true,"exportable":false},
{"id":"13974b57-8f6d-57df-9050-d28c78226cf7","key":"copenhagen-plank","name_fr":"Copenhagen plank","name_en":"Copenhagen Plank","aliases_fr":["Planche Copenhague"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"plank","variant_of":null,"equipment":["bench"],"primary_muscles":["adductors","obliques"],"secondary_muscles":["gluteus_medius","quadratus_lumborum","transverse_abdominis"],"difficulty":"advanced","metrics":["duration_s"],"unilateral":true,"bodyweight":false,"tags":["core","calisthenics"],"instructions_fr":["Allonge-toi sur le côté près d'un banc plat et pose la jambe du dessus dessus, l'intérieur du pied ou le bas de la jambe appuyé sur le banc.","Appuie-toi sur le coude du bras du dessous, juste sous l'épaule.","Soulève les hanches pour que le corps forme une ligne droite de la tête au pied du dessus, et laisse pendre la jambe du dessous ou monte-la vers le banc.","Garde les hanches hautes et le buste stable, et respire normalement.","Tiens pendant le temps prévu, puis repose les hanches au sol.","Repose-toi, puis change de côté."],"image_main":"/exercises/copenhagen-plank/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-copenhagen-plank"],"attribution_required":true,"exportable":false},
{"id":"3da612b4-8639-59ec-9a2b-bf86bd352e95","key":"copenhagen-plank-raises","name_fr":"Copenhagen plank avec relevés","name_en":"Copenhagen Plank Raises","aliases_fr":["Relevés Copenhagen"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"plank","variant_of":null,"equipment":["bench"],"primary_muscles":["adductors","obliques"],"secondary_muscles":["gluteus_medius","quadratus_lumborum","transverse_abdominis"],"difficulty":"advanced","metrics":["reps","tempo"],"unilateral":true,"bodyweight":false,"tags":["core","calisthenics"],"instructions_fr":["Allonge-toi sur le côté près d'un banc plat et pose la jambe du dessus dessus, le genou ou l'intérieur du pied appuyé sur le banc.","Appuie-toi sur le coude du bras du dessous, juste sous l'épaule.","Soulève les hanches pour que le corps forme une ligne droite de la tête au pied du dessus, la jambe du dessous pendante.","Monte la jambe du dessous vers le banc jusqu'à presque toucher la jambe du dessus, en gardant les hanches hautes.","Redescends la jambe du dessous lentement sans laisser tomber les hanches, et répète pour le nombre de répétitions prévu.","Repose-toi, puis change de côté."],"image_main":null,"image_start":"/exercises/copenhagen-plank-raises/start.webp","image_end":"/exercises/copenhagen-plank-raises/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-copenhagen-plank-raises"],"attribution_required":true,"exportable":false},
{"id":"7030b9f5-80b2-5795-a228-6885e224ae67","key":"cossack-squat","name_fr":"Squat cosaque","name_en":"Cossack Squat","aliases_fr":["Cossack squat","Mobilité squat cosaque"],"aliases_en":["Cossack squat mobility"],"category":"strength","visibility":"active","disciplines":["strength","mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["adductors","hamstrings"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":["Place-toi debout, jambes écartées, pointes de pieds légèrement tournées vers l'extérieur.","Déplace ton poids sur un côté en fléchissant ce genou et descends en squat profond.","Garde l'autre jambe tendue, talon au sol et orteils relevés.","Descends aussi bas que ta mobilité le permet, poitrine haute.","Pousse avec la jambe fléchie pour revenir au centre, puis passe de l'autre côté."],"image_main":null,"image_start":"/exercises/cossack-squat/start.webp","image_end":"/exercises/cossack-squat/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cossack-squat","coory-cossack-squat-mobility"],"attribution_required":true,"exportable":false},
{"id":"9c370a44-617b-5563-bd08-357c6d114e52","key":"cow-face-pose","name_fr":"Posture de la tête de vache","name_en":"Cow Face Pose","aliases_fr":["Gomukhasana"],"aliases_en":["Gomukhasana"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus","gluteus_medius"],"secondary_muscles":["posterior_deltoid","triceps_brachii"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":["Assieds-toi au sol et croise un genou juste par-dessus l'autre, pour que les genoux soient empilés sur la ligne médiane.","Écarte les pieds vers l'extérieur des hanches et pose les deux ischions de façon égale au sol.","Lève le bras du côté du genou du dessus et plie-le derrière la tête, puis monte l'autre bras dans le dos pour attraper la main.","Tiens la position le temps prévu, la poitrine ouverte et la colonne droite.","Relâche et recommence avec l'autre jambe et l'autre bras au-dessus."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-cow-face-pose"],"attribution_required":true,"exportable":false},
{"id":"ff08306a-b05e-5f1e-aac1-413f1ffeb780","key":"crab-dips","name_fr":"Crab dips","name_en":"Crab Dips","aliases_fr":["Dips du crabe"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"plank","variant_of":null,"equipment":[],"primary_muscles":["triceps_brachii"],"secondary_muscles":["anterior_deltoid","gluteus_maximus","pectoralis_major"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["calisthenics"],"instructions_fr":["Assieds-toi genoux fléchis, pieds à plat et mains au sol derrière toi, doigts dirigés vers les talons.","Appuie dans les mains et les pieds et soulève les hanches jusqu'à ce que le buste soit à peu près au niveau des genoux.","Fléchis les coudes droit vers l'arrière pour descendre les hanches vers le sol sans t'asseoir.","Repousse jusqu'à ce que les bras soient tendus, en gardant les hanches levées.","Répète pour le nombre de répétitions voulu et repose les hanches pour terminer."],"image_main":null,"image_start":"/exercises/crab-dips/start.webp","image_end":"/exercises/crab-dips/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-crab-dips"],"attribution_required":true,"exportable":false},
{"id":"06571b6d-4415-5b4b-bf58-2b768caffad4","key":"crescent-lunge","name_fr":"Fente croissant","name_en":"Crescent Lunge","aliases_fr":["Crescent lunge","Anjaneyasana"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["erector_spinae","hip_flexors"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":["calisthenics"],"instructions_fr":["Fais un grand pas en avant d'un pied, talon arrière levé et orteils vers l'avant.","Fléchis le genou avant à environ 90 degrés, au-dessus de la cheville.","Ramène la hanche arrière vers l'avant pour que les deux hanches regardent le devant du tapis, puis lève les bras au-dessus de la tête.","Tiens la position pendant la durée prévue, côtes rentrées et jambe arrière tendue.","Rapproche les pieds et recommence de l'autre côté."],"image_main":"/exercises/crescent-lunge/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-crescent-lunge"],"attribution_required":true,"exportable":false},
{"id":"1fb24cab-1564-5e62-b990-3d498f9d5b7a","key":"cross-body-crunch","name_fr":"Crunch croisé","name_en":"Cross-Body Crunch","aliases_fr":["Crunch oblique"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["obliques"],"secondary_muscles":["rectus_abdominis"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["core","calisthenics"],"instructions_fr":["Allonge-toi sur le dos, genoux fléchis et mains légèrement derrière les oreilles.","Monte en crunch en tournant le buste : amène le coude droit vers le genou gauche, qui remonte vers toi.","Reviens à la position de départ en contrôlant.","Recommence de l'autre côté, en alternant à chaque répétition."],"image_main":null,"image_start":"/exercises/cross-body-crunch/start.webp","image_end":"/exercises/cross-body-crunch/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cross-body-crunch"],"attribution_required":true,"exportable":false},
{"id":"b47f1488-237a-5722-8fcb-dd8fae754d0d","key":"cross-body-hammer-curl","name_fr":"Curl marteau croisé","name_en":"Cross Body Hammer Curl","aliases_fr":[],"aliases_en":["Cross body curl"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["brachialis","brachioradialis"],"secondary_muscles":["biceps_brachii","forearm_flexors"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Tiens-toi bien droit avec un haltère dans chaque main, en prise neutre.","Monte un haltère en diagonale devant toi vers l'épaule opposée.","Garde le coude immobile le long du corps.","Redescends de façon contrôlée et répète de l'autre côté.","Continue en alternant pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/cross-body-hammer-curl/start.webp","image_end":"/exercises/cross-body-hammer-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-cross-body-hammer-curl"],"attribution_required":true,"exportable":false},
{"id":"ba724116-7561-550a-9f98-3f276ce283ca","key":"cross-body-shoulder-stretch","name_fr":"Étirement épaule bras croisé","name_en":"Cross-Body Shoulder Stretch","aliases_fr":[],"aliases_en":["Cross-arm shoulder stretch"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["posterior_deltoid"],"secondary_muscles":["rhomboids"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":["Tiens-toi debout et amène un bras tendu en travers de ta poitrine.","Place l'avant-bras de l'autre bras sous celui-ci.","Tire doucement le bras pour le rapprocher de ta poitrine.","Tiens la position 20 à 30 secondes en respirant calmement.","Change de côté et recommence."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-cross-body-shoulder-stretch"],"attribution_required":true,"exportable":false},
{"id":"9725a364-de03-576b-94d4-105540cca9d2","key":"crow-pose","name_fr":"Posture du corbeau","name_en":"Crow Pose","aliases_fr":["Crow pose","Bakasana"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["anterior_deltoid","triceps_brachii"],"secondary_muscles":["rectus_abdominis","serratus_anterior"],"difficulty":"advanced","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":["calisthenics"],"instructions_fr":["Accroupis-toi pieds proches l'un de l'autre et pose les paumes au sol devant toi, à largeur d'épaules.","Fléchis les coudes vers l'arrière et pose les genoux haut sur l'arrière des bras.","Transfère le poids vers l'avant sur les mains jusqu'à ce que les pieds décollent du sol.","Tiens l'équilibre pendant la durée prévue, haut du dos arrondi et regard légèrement vers l'avant.","Repose les pieds au sol en contrôlant."],"image_main":"/exercises/crow-pose/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-crow-pose"],"attribution_required":true,"exportable":false},
{"id":"ccd3756c-1f69-52c5-b0c5-ce967559fe4a","key":"crunches","name_fr":"Crunch","name_en":"Crunches","aliases_fr":[],"aliases_en":["Ab crunch"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"crunch","variant_of":null,"equipment":[],"primary_muscles":["rectus_abdominis"],"secondary_muscles":["obliques"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["core"],"instructions_fr":["Allonge-toi sur le dos, genoux fléchis, mains derrière la tête.","Enroule le haut du corps vers les genoux en décollant les omoplates du sol.","Contracte les abdominaux en haut.","Redescends avec contrôle.","Répète."],"image_main":null,"image_start":"/exercises/crunches/start.webp","image_end":"/exercises/crunches/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-crunches"],"attribution_required":true,"exportable":false},
{"id":"35675b4d-d16f-5c7a-be06-c9291295b93c","key":"cycling","name_fr":"Vélo","name_en":"Cycling","aliases_fr":["Cyclisme"],"aliases_en":[],"category":"cardio","visibility":"active","disciplines":["cardio"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["bicycle"],"primary_muscles":["quadriceps"],"secondary_muscles":["gastrocnemius","gluteus_maximus","hamstrings","soleus"],"difficulty":"beginner","metrics":["duration_s","distance_m","calories_kcal"],"unilateral":false,"bodyweight":false,"tags":["conditioning","legs"],"instructions_fr":["Règle la selle pour que ton genou reste à peine fléchi quand la pédale est en bas.","Assieds-toi sur la selle, mains sur le guidon, coudes légèrement fléchis et épaules relâchées.","Place l'avant des pieds au-dessus des axes de pédales.","Pousse chaque pédale vers le bas et l'avant, puis laisse-la remonter en un cercle fluide.","Garde une cadence régulière et choisis un braquet qui te permet de pédaler sans rebondir sur la selle.","Roule pendant la durée ou la distance prévue, en réduisant l'allure pendant les dernières minutes pour récupérer."],"image_main":"/exercises/cycling/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-cycling"],"attribution_required":true,"exportable":false},
{"id":"6f54f9b4-39a9-5d39-92dd-ff1d510bc6c2","key":"dancer-pose","name_fr":"Posture du danseur","name_en":"Dancer Pose","aliases_fr":["Dancer pose","Natarajasana"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["erector_spinae","hip_flexors"],"difficulty":"advanced","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":["calisthenics"],"instructions_fr":["Tiens-toi bien droit et transfère le poids sur un pied, genou légèrement fléchi.","Fléchis l'autre genou et attrape l'intérieur de cette cheville derrière toi.","Pousse le pied levé vers l'arrière dans ta main et tends le bras opposé vers l'avant en ouvrant la poitrine.","Tiens la posture pendant la durée prévue, hanche d'appui à plat et regard fixe.","Relâche le pied et recommence de l'autre côté."],"image_main":"/exercises/dancer-pose/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-dancer-pose"],"attribution_required":true,"exportable":false},
{"id":"7fd4b0ad-e4bf-5807-909f-c08767752361","key":"db-bench-press","name_fr":"Développé couché haltères","name_en":"Dumbbell Bench Press","aliases_fr":["DB bench press"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bench-press","variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Allonge-toi sur un banc plat, un haltère dans chaque main à hauteur de poitrine.","Pousse les haltères vers le haut jusqu'à l'extension complète des bras.","Redescends-les lentement à la position de départ.","Répète."],"image_main":null,"image_start":"/exercises/db-bench-press/start.webp","image_end":"/exercises/db-bench-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-db-bench-press"],"attribution_required":true,"exportable":false},
{"id":"b0f982fe-c9f3-5730-b574-2b86fb8b17fe","key":"db-fly","name_fr":"Écarté couché haltères","name_en":"Dumbbell Fly","aliases_fr":[],"aliases_en":["Dumbbell chest fly"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"chest-fly","variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Allonge-toi à plat sur un banc, haltères au-dessus de la poitrine, paumes face à face.","Coudes légèrement fléchis, descends les haltères sur les côtés.","Reviens en position de départ en contractant les pectoraux.","Répète."],"image_main":null,"image_start":"/exercises/db-fly/start.webp","image_end":"/exercises/db-fly/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-db-fly"],"attribution_required":true,"exportable":false},
{"id":"b7808e45-6221-5d99-b872-8c0dcdc187bc","key":"db-goblet-squat","name_fr":"Goblet squat haltère","name_en":"Dumbbell Goblet Squat","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"squat","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["adductors","hamstrings","rectus_abdominis"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs"],"instructions_fr":["Tiens-toi debout, pieds un peu plus larges que les épaules et pointes légèrement tournées vers l'extérieur.","Tiens un haltère à la verticale contre la poitrine, les deux mains en coupe sous l'extrémité haute et les coudes dirigés vers le bas.","Gaine le tronc et pousse les hanches vers l'arrière et vers le bas, poitrine haute et haltère près du corps.","Descends jusqu'à ce que les cuisses soient au moins parallèles au sol, genoux dans l'axe des orteils et talons à plat.","Marque une brève pause en bas, puis pousse avec tout le pied pour te relever.","Répète pour le nombre de répétitions prévu sans laisser l'haltère s'éloigner de la poitrine."],"image_main":null,"image_start":"/exercises/db-goblet-squat/start.webp","image_end":"/exercises/db-goblet-squat/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-db-goblet-squat"],"attribution_required":true,"exportable":false},
{"id":"5a39a035-62e2-59af-abcc-b8f8ae0a6221","key":"db-kickstand-deadlift","name_fr":"Soulevé de terre kickstand haltère","name_en":"Dumbbell Kickstand Deadlift","aliases_fr":["Kickstand deadlift haltère"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"deadlift","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["gluteus_maximus","hamstrings"],"secondary_muscles":["adductors","erector_spinae"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["legs","pull"],"instructions_fr":["Recule un pied pour que seuls les orteils touchent légèrement le sol, et penche-toi en charnière de hanches, dos plat.","Tiens un haltère dans une main, bas à côté du pied avant.","Pousse dans le talon avant et étends les hanches pour te redresser, haltère le long du corps.","Garde l'essentiel du poids sur le pied avant tout au long du mouvement.","Redescends en charnière en amenant l'haltère vers le sol, dos plat. Fais toutes les répétitions, puis change de côté."],"image_main":null,"image_start":"/exercises/db-kickstand-deadlift/start.webp","image_end":"/exercises/db-kickstand-deadlift/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-db-kickstand-deadlift"],"attribution_required":true,"exportable":false},
{"id":"0fca76a3-03b7-59ee-9ea5-b15280f5b1ee","key":"db-lunge","name_fr":"Fentes haltères","name_en":"Dumbbell Lunge","aliases_fr":[],"aliases_en":["DB lunge"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"lunge","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["hamstrings"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["legs"],"instructions_fr":["Tiens-toi debout avec des haltères le long du corps.","Fais un pas en avant avec un pied et descends le genou arrière vers le sol.","Pousse sur le pied avant pour revenir.","Alterne les jambes.","Répète."],"image_main":null,"image_start":"/exercises/db-lunge/start.webp","image_end":"/exercises/db-lunge/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-db-lunge"],"attribution_required":true,"exportable":false},
{"id":"4318a958-9ebd-5eb1-8a1a-7fe69c091545","key":"db-overhead-carry","name_fr":"Overhead carry haltère à un bras","name_en":"Dumbbell Overhead Carry","aliases_fr":["Marche haltère au-dessus de la tête"],"aliases_en":["DB overhead carry"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["dumbbell"],"primary_muscles":["anterior_deltoid","lateral_deltoid"],"secondary_muscles":["obliques","quadratus_lumborum","serratus_anterior","transverse_abdominis","trapezius","triceps_brachii"],"difficulty":"intermediate","metrics":["distance_m","duration_s","load_kg"],"unilateral":true,"bodyweight":false,"tags":["shoulders","shoulder_stability","core","full_body"],"instructions_fr":["Épaule ou presse un haltère jusqu'au verrouillage, directement au-dessus de l'épaule.","Pousse le bras à fond vers le haut, coude tendu et biceps près de l'oreille.","Garde les côtes basses plutôt que de cambrer le bas du dos pour tenir la charge.","Avance à pas contrôlés, l'haltère aligné au-dessus de l'épaule et de la hanche.","Garde les yeux devant toi : si tu renverses la tête pour regarder la charge, ta posture suit.","Marche sur la distance voulue, redescends en contrôlant, puis recommence avec l'autre bras."],"image_main":"/exercises/db-overhead-carry/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-db-overhead-carry"],"attribution_required":true,"exportable":false},
{"id":"88f9e23a-65fa-5f50-ba5a-808d011d6029","key":"db-preacher-curl","name_fr":"Curl pupitre haltères","name_en":"Dumbbell Preacher Curl","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["biceps_brachii"],"secondary_muscles":["brachialis","brachioradialis"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms"],"instructions_fr":["Règle le siège pour que les aisselles reposent en haut du coussin et que le haut des bras soit à plat dessus.","Tiens un haltère dans chaque main en supination et laisse les bras pendre le long du coussin.","Monte les deux haltères vers les épaules sans décoller les coudes du coussin.","Serre brièvement les biceps en haut.","Redescends lentement les haltères jusqu'à avoir les bras presque tendus, puis répète."],"image_main":null,"image_start":"/exercises/db-preacher-curl/start.webp","image_end":"/exercises/db-preacher-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-db-preacher-curl"],"attribution_required":true,"exportable":false},
{"id":"6d7c4282-6afa-5315-8e55-385b13086ff0","key":"db-pullover","name_fr":"Pull-over haltère","name_en":"Dumbbell Pullover","aliases_fr":["Pull-over"],"aliases_en":["DB pullover"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"pullover","variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["latissimus_dorsi","pectoralis_major"],"secondary_muscles":["triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Allonge-toi sur un banc plat, un haltère tenu au-dessus de la poitrine, bras tendus.","Descends l'haltère derrière la tête en arc de cercle, avec une légère flexion des coudes.","Étire-toi jusqu'à sentir la tension dans les dorsaux et la poitrine.","Ramène l'haltère en position de départ.","Répète."],"image_main":null,"image_start":"/exercises/db-pullover/start.webp","image_end":"/exercises/db-pullover/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-db-pullover"],"attribution_required":true,"exportable":false},
{"id":"3ac5fc58-9f6c-5476-aff7-47c38d734ed2","key":"db-reverse-curl","name_fr":"Curl inversé haltères","name_en":"Dumbbell Reverse Curl","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["brachialis","forearm_extensors"],"secondary_muscles":["biceps_brachii"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms"],"instructions_fr":["Tiens des haltères en pronation le long du corps.","Monte-les jusqu'à hauteur d'épaules.","Redescends de façon contrôlée.","Répète."],"image_main":null,"image_start":"/exercises/db-reverse-curl/start.webp","image_end":"/exercises/db-reverse-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-db-reverse-curl"],"attribution_required":true,"exportable":false},
{"id":"24849210-63e4-5da1-a2bb-2cf7171b5764","key":"db-reverse-wrist-curl","name_fr":"Curl poignets prise pronation haltères","name_en":"Dumbbell Reverse Wrist Curl","aliases_fr":["Extension de poignets haltères"],"aliases_en":["DB reverse wrist curl"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["dumbbell"],"primary_muscles":["forearm_extensors"],"secondary_muscles":[],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms","grip"],"instructions_fr":["Assieds-toi sur un banc avec un haltère dans chaque main, avant-bras posés sur les cuisses, paumes vers le bas.","Laisse tomber les poignets en baissant les haltères vers le sol.","Remonte le dos des mains vers le plafond en étendant les poignets.","Contracte en haut, puis redescends en contrôlant.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/db-reverse-wrist-curl/start.webp","image_end":"/exercises/db-reverse-wrist-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-db-reverse-wrist-curl"],"attribution_required":true,"exportable":false},
{"id":"6c88b365-1717-5690-95c1-5dc9a4ec5237","key":"db-shrug","name_fr":"Shrugs haltères","name_en":"Dumbbell Shrug","aliases_fr":["Haussements d'épaules haltères"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"shrug","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["trapezius"],"secondary_muscles":["rhomboids"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Tiens-toi debout avec des haltères le long du corps.","Hausse les épaules à la verticale aussi haut que possible.","Marque une brève pause, puis redescends.","Répète."],"image_main":null,"image_start":"/exercises/db-shrug/start.webp","image_end":"/exercises/db-shrug/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-db-shrug"],"attribution_required":true,"exportable":false},
{"id":"66327335-c1b1-50b4-b4aa-55dacb8cff82","key":"db-skull-crusher","name_fr":"Barre au front haltères","name_en":"Dumbbell Skull Crusher","aliases_fr":["Skull crusher haltères"],"aliases_en":["DB skull crusher"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"skull-crusher","variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["triceps_brachii"],"secondary_muscles":[],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms"],"instructions_fr":["Allonge-toi sur un banc plat, haltères tenus au-dessus de la poitrine.","Descends les haltères vers les côtés de la tête.","Tends de nouveau les bras vers le haut.","Répète."],"image_main":null,"image_start":"/exercises/db-skull-crusher/start.webp","image_end":"/exercises/db-skull-crusher/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-db-skull-crusher"],"attribution_required":true,"exportable":false},
{"id":"9eba0e98-5813-5d20-967b-cb7e75593adc","key":"db-somersault-squat","name_fr":"Squat avec haltère en diagonale","name_en":"Dumbbell Somersault Squat","aliases_fr":["Somersault squat haltère"],"aliases_en":["DB somersault squat"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["dumbbell"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["hamstrings","obliques"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["legs"],"instructions_fr":["Tiens-toi debout, pieds à largeur d'épaules, avec un haltère dans une main à l'épaule.","Descends en squat en envoyant l'haltère vers l'avant et en travers du corps.","En bas du squat, l'haltère est tendu au-delà du genou opposé.","Pousse dans les talons pour te relever en ramenant l'haltère à l'épaule.","Fais toutes les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/db-somersault-squat/start.webp","image_end":"/exercises/db-somersault-squat/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-db-somersault-squat"],"attribution_required":true,"exportable":false},
{"id":"a4bfd67d-85bc-55bb-95ce-d455e826c6ec","key":"db-squat","name_fr":"Squat haltères","name_en":"Dumbbell Squat","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"squat","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["hamstrings"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs"],"instructions_fr":["Tiens-toi debout, pieds à largeur d'épaules, un haltère dans chaque main le long du corps.","Gaine les abdominaux et garde la poitrine haute.","Descends en fléchissant les hanches et les genoux.","Descends jusqu'à ce que les cuisses soient parallèles au sol ou plus bas.","Pousse dans les talons pour te relever."],"image_main":null,"image_start":"/exercises/db-squat/start.webp","image_end":"/exercises/db-squat/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-db-squat"],"attribution_required":true,"exportable":false},
{"id":"5ef962e0-a642-5f35-a701-596a6ab93c42","key":"db-step-up-to-balance","name_fr":"Step-up avec équilibre haltères","name_en":"Dumbbell Step-Up to Balance","aliases_fr":["Step-up avec montée de genou haltères"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"step-up","variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["forearm_flexors","gastrocnemius","gluteus_medius","hip_flexors"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["core"],"instructions_fr":["Place-toi face à une marche ou un banc bas et stable, un haltère dans chaque main, bras le long du corps.","Pose un pied à plat sur la marche.","Pousse dans tout le pied avant et tends cette jambe pour monter sur la marche.","En montant, remonte l'autre genou devant toi jusqu'à ce que la cuisse soit à peu près à hauteur de hanche.","Tiens-toi droit sur la jambe de travail et maintiens le genou levé un instant, sans te pencher en arrière.","Redescends le pied libre au sol en contrôlant, puis redescends aussi la jambe de travail et recommence. Change de jambe après les répétitions prévues."],"image_main":null,"image_start":"/exercises/db-step-up-to-balance/start.webp","image_end":"/exercises/db-step-up-to-balance/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-db-step-up-to-balance"],"attribution_required":true,"exportable":false},
{"id":"1a6b41cf-8226-587c-958b-1efb8f206ce0","key":"db-sumo-squat","name_fr":"Squat sumo haltère","name_en":"Dumbbell Sumo Squat","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"squat","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["adductors","gluteus_medius","hamstrings"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs","glutes"],"instructions_fr":["Tiens-toi debout, pieds plus larges que les épaules, pointes tournées vers l'extérieur d'environ 30 degrés.","Tiens un haltère à la verticale par son extrémité haute, à deux mains, et laisse-le pendre entre tes jambes.","Gaine les abdominaux et garde la poitrine haute.","Fléchis les hanches et les genoux pour descendre tout droit en squat profond.","Pousse dans les talons pour te relever.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/db-sumo-squat/start.webp","image_end":"/exercises/db-sumo-squat/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-db-sumo-squat"],"attribution_required":true,"exportable":false},
{"id":"f03f6014-100f-5269-90ba-23a9c2fedb45","key":"db-svend-press","name_fr":"Svend press haltères","name_en":"Dumbbell Svend Press","aliases_fr":["Squeeze press debout"],"aliases_en":["DB Svend press"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["dumbbell"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid","triceps_brachii"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push","chest"],"instructions_fr":["Tiens-toi debout et presse deux haltères l'un contre l'autre à l'horizontale, à hauteur de poitrine.","Garde la pression vers l'intérieur sur les haltères pendant tout le mouvement.","Pousse les haltères vers l'avant jusqu'à avoir les bras presque tendus.","Ramène-les vers la poitrine en contrôlant.","Répète pour le nombre de répétitions prévu."],"image_main":null,"image_start":"/exercises/db-svend-press/start.webp","image_end":"/exercises/db-svend-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-db-svend-press"],"attribution_required":true,"exportable":false},
{"id":"e49ec3d5-fc1f-58b9-9f8a-6d20f2081412","key":"dead-bug","name_fr":"Dead bug","name_en":"Dead Bug","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"crunch","variant_of":null,"equipment":[],"primary_muscles":["rectus_abdominis","transverse_abdominis"],"secondary_muscles":["hip_flexors"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["core"],"instructions_fr":["Allonge-toi sur le dos, bras tendus vers le plafond, genoux à 90 degrés.","Descends le bras droit et la jambe gauche vers le sol en gardant le bas du dos plaqué au sol.","Reviens à la position de départ.","Répète de l'autre côté.","Alterne."],"image_main":null,"image_start":"/exercises/dead-bug/start.webp","image_end":"/exercises/dead-bug/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dead-bug"],"attribution_required":true,"exportable":false},
{"id":"11bdd261-dcad-5063-b744-0b0e54461cd7","key":"dead-bug-hold","name_fr":"Dead bug isométrique","name_en":"Dead Bug Hold","aliases_fr":["Maintien dead bug"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"crunch","variant_of":null,"equipment":[],"primary_muscles":["rectus_abdominis","transverse_abdominis"],"secondary_muscles":["hip_flexors"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":["core"],"instructions_fr":["Allonge-toi sur le dos, bras tendus vers le plafond, hanches et genoux fléchis à 90 degrés.","Plaque le bas du dos au sol et garde-le ainsi pendant toute la série.","Tends un bras au-dessus de la tête et la jambe opposée jusqu'à ce qu'ils flottent juste au-dessus du sol.","Maintiens cette position étendue pendant le temps prévu, sans écarter les côtes ni cambrer le dos.","Reviens au départ et recommence avec l'autre bras et l'autre jambe."],"image_main":"/exercises/dead-bug-hold/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-dead-bug-hold"],"attribution_required":true,"exportable":false},
{"id":"bb4ad73b-4f53-5d70-8b9e-d6b6d9141796","key":"dead-hang","name_fr":"Suspension à la barre","name_en":"Dead Hang","aliases_fr":["Dead hang"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"static-hold","variant_of":null,"equipment":["pull_up_bar"],"primary_muscles":["forearm_flexors"],"secondary_muscles":["latissimus_dorsi","rectus_abdominis","trapezius"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Attrape une barre de traction en pronation, mains à largeur d'épaules.","Suspends-toi bras complètement tendus et pieds décollés du sol.","Relâche les épaules et laisse ton corps pendre.","Garde les abdominaux légèrement gainés.","Tiens pendant la durée voulue."],"image_main":"/exercises/dead-hang/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-dead-hang"],"attribution_required":true,"exportable":false},
{"id":"24c44764-91f1-53d1-ad99-45398754a2f7","key":"deadlift","name_fr":"Soulevé de terre barre","name_en":"Barbell Deadlift","aliases_fr":["Soulevé de terre"],"aliases_en":["Conventional deadlift"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"deadlift","variant_of":null,"equipment":["barbell"],"primary_muscles":["erector_spinae","gluteus_maximus","hamstrings"],"secondary_muscles":["quadriceps","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["powerlifting","pull"],"instructions_fr":["Tiens-toi debout, pieds à largeur de hanches, barre au-dessus du milieu des pieds.","Penche-toi en charnière de hanches et saisis la barre.","Gaine les abdominaux et soulève en étendant les hanches et les genoux.","Redresse-toi complètement en haut, puis redescends sous contrôle.","Répète."],"image_main":null,"image_start":"/exercises/deadlift/start.webp","image_end":"/exercises/deadlift/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-deadlift"],"attribution_required":true,"exportable":false},
{"id":"adb27ffe-dd98-5547-af7c-a077542de3a6","key":"decline-bench-press","name_fr":"Développé décliné haltères","name_en":"Decline Bench Press","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bench-press","variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Règle le banc en position déclinée. Allonge-toi et cale tes pieds.","Tiens un haltère dans chaque main au-dessus de la poitrine, puis descends-les sur les côtés du bas de la poitrine.","Repousse les haltères jusqu'à la position de départ.","Répète."],"image_main":null,"image_start":"/exercises/decline-bench-press/start.webp","image_end":"/exercises/decline-bench-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-decline-bench-press"],"attribution_required":true,"exportable":false},
{"id":"145fa816-8fbc-593d-ab48-0d7b2b0cb559","key":"decline-bench-press-barbell","name_fr":"Développé décliné barre","name_en":"Decline Barbell Bench Press","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bench-press","variant_of":null,"equipment":["barbell","bench"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Règle le banc en position déclinée. Allonge-toi et cale tes pieds.","Prends la barre un peu plus large que les épaules.","Descends la barre vers le bas de la poitrine, puis repousse.","Répète."],"image_main":null,"image_start":"/exercises/decline-bench-press-barbell/start.webp","image_end":"/exercises/decline-bench-press-barbell/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-decline-bench-press-barbell"],"attribution_required":true,"exportable":false},
{"id":"7eb5d5d9-6864-5a65-9f93-78895308ee44","key":"decline-bench-press-ez-bar","name_fr":"Développé décliné barre EZ","name_en":"Decline EZ-Bar Bench Press","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bench-press","variant_of":null,"equipment":["ez_bar","bench"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Règle le banc en position déclinée. Cale tes pieds et prends la barre EZ.","Descends la barre vers le bas de la poitrine.","Repousse vers le haut de façon explosive.","Répète."],"image_main":null,"image_start":"/exercises/decline-bench-press-ez-bar/start.webp","image_end":"/exercises/decline-bench-press-ez-bar/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-decline-bench-press-ez-bar"],"attribution_required":true,"exportable":false},
{"id":"3add9413-6ced-5f93-9d27-04495d0388ae","key":"decline-crunch","name_fr":"Crunch décliné","name_en":"Decline Crunch","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"crunch","variant_of":null,"equipment":["bench"],"primary_muscles":["rectus_abdominis"],"secondary_muscles":["hip_flexors","obliques"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Cale tes pieds en haut d'un banc décliné.","Allonge-toi en arrière, mains croisées sur la poitrine ou derrière la tête.","Enroule le buste vers les genoux en fléchissant la colonne.","Contracte les abdominaux en haut.","Redescends sous contrôle et répète."],"image_main":null,"image_start":"/exercises/decline-crunch/start.webp","image_end":"/exercises/decline-crunch/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-decline-crunch"],"attribution_required":true,"exportable":false},
{"id":"965b6bcc-a226-54fc-83d9-15dbb7d4c2c8","key":"decline-db-fly","name_fr":"Écarté décliné haltères","name_en":"Decline Dumbbell Fly","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"chest-fly","variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Allonge-toi sur un banc décliné, haltères tenus au-dessus de la poitrine.","Coudes légèrement fléchis, descends les haltères largement de chaque côté.","Contracte les pectoraux pour les remonter.","Répète."],"image_main":null,"image_start":"/exercises/decline-db-fly/start.webp","image_end":"/exercises/decline-db-fly/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-decline-db-fly"],"attribution_required":true,"exportable":false},
{"id":"54f5a619-5d8b-5419-883d-448cc81ecb25","key":"decline-push-up","name_fr":"Pompes déclinées","name_en":"Decline Push-Up","aliases_fr":["Pompes pieds surélevés"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"push-up","variant_of":null,"equipment":["bench"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["calisthenics"],"instructions_fr":["Place les pieds sur une surface surélevée et les mains au sol.","Descends la poitrine vers le sol en contrôlant.","Repousse jusqu'au départ.","Répète."],"image_main":null,"image_start":"/exercises/decline-push-up/start.webp","image_end":"/exercises/decline-push-up/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-decline-push-up"],"attribution_required":true,"exportable":false},
{"id":"442d0189-3a05-5d56-8567-e7ac6688229c","key":"deep-squat-hold","name_fr":"Maintien squat profond","name_en":"Deep Squat Hold","aliases_fr":["Deep squat hold"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"squat","variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["adductors","erector_spinae","hamstrings","soleus"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":["legs"],"instructions_fr":["Tiens-toi debout, pieds un peu plus larges que les épaules, pointes tournées vers l'extérieur.","Joins les mains devant la poitrine et descends les hanches entre les talons.","Descends jusqu'à ce que les hanches passent sous les genoux, talons à plat au sol.","Garde la poitrine haute et appuie les coudes contre les genoux pour les pousser vers l'extérieur.","Maintiens la position en respirant calmement, puis relève-toi."],"image_main":"/exercises/deep-squat-hold/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-deep-squat-hold"],"attribution_required":true,"exportable":false},
