{"id":"696976d1-540f-5a61-9a4e-84849e45a98b","key":"deficit-deadlift","name_fr":"Soulevé de terre en déficit","name_en":"Deficit Deadlift","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"deadlift","variant_of":null,"equipment":["barbell"],"primary_muscles":["erector_spinae","gluteus_maximus","hamstrings"],"secondary_muscles":["latissimus_dorsi","quadriceps","trapezius"],"difficulty":"advanced","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Monte sur une petite plateforme, barre chargée au-dessus du milieu des pieds.","Penche-toi en charnière et saisis la barre juste à l'extérieur des genoux.","Pousse avec les jambes pour te redresser en gardant la barre près du corps.","Verrouille les hanches et les genoux en haut.","Redescends sous contrôle et répète."],"image_main":null,"image_start":"/exercises/deficit-deadlift/start.webp","image_end":"/exercises/deficit-deadlift/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-deficit-deadlift"],"attribution_required":true,"exportable":false},
{"id":"03c76077-0023-5625-9bf4-347cda73d20a","key":"deficit-push-ups","name_fr":"Pompes en déficit","name_en":"Deficit Push Ups","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"push-up","variant_of":null,"equipment":[],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid","serratus_anterior","triceps_brachii"],"difficulty":"advanced","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Place les mains sur deux surfaces surélevées, comme des parallettes ou des blocs.","Prends la position de planche, mains sous les épaules.","Descends la poitrine sous le niveau des mains.","Repousse pour tendre les bras.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/deficit-push-ups/start.webp","image_end":"/exercises/deficit-push-ups/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-deficit-push-ups"],"attribution_required":true,"exportable":false},
{"id":"fb220643-5378-5336-ae07-d79970a8177f","key":"diamond-push-ups","name_fr":"Pompes diamant","name_en":"Diamond Push Ups","aliases_fr":["Pompes triceps"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"push-up","variant_of":null,"equipment":[],"primary_muscles":["pectoralis_major","triceps_brachii"],"secondary_muscles":["anterior_deltoid","serratus_anterior"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Mets-toi en position de pompe, mains rapprochées pour former un diamant.","Garde les coudes collés le long du corps.","Descends la poitrine vers les mains.","Repousse pour tendre les bras.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/diamond-push-ups/start.webp","image_end":"/exercises/diamond-push-ups/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-diamond-push-ups"],"attribution_required":true,"exportable":false},
{"id":"0656db4f-0eca-5a73-9eb2-5dbbd6e5fa2c","key":"dips","name_fr":"Dips pectoraux","name_en":"Chest Dips","aliases_fr":["Dips"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"dips","variant_of":null,"equipment":["dip_station"],"primary_muscles":["pectoralis_major","triceps_brachii"],"secondary_muscles":["anterior_deltoid"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":false,"tags":["push","calisthenics"],"instructions_fr":["Saisis les barres parallèles et monte en appui, bras verrouillés.","Penche légèrement le buste vers l'avant.","Descends en fléchissant les coudes jusqu'à ce que les épaules passent sous les coudes.","Remonte à la position de départ.","Répète."],"image_main":null,"image_start":"/exercises/dips/start.webp","image_end":"/exercises/dips/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dips"],"attribution_required":true,"exportable":false},
{"id":"45110abd-eb44-530a-a6e1-ff95ef45f95e","key":"dolphin-pose","name_fr":"Posture du dauphin","name_en":"Dolphin Pose","aliases_fr":["Dolphin pose"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["anterior_deltoid","trapezius"],"secondary_muscles":["hamstrings","serratus_anterior"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":["calisthenics"],"instructions_fr":["Mets-toi à genoux et pose les avant-bras au sol à largeur d'épaules, coudes sous les épaules.","Replie les orteils et monte les hanches vers le haut et l'arrière, pour que le corps forme un V inversé.","Appuie les avant-bras dans le sol et éloigne les épaules des oreilles. Garde les talons hauts.","Tiens la position pendant la durée prévue, nuque relâchée entre les bras.","Pose les genoux au sol pour sortir de la posture."],"image_main":"/exercises/dolphin-pose/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-dolphin-pose"],"attribution_required":true,"exportable":false},
{"id":"ccf17104-b778-5a95-8b96-bc7303d81311","key":"donkey-calf-raise","name_fr":"Donkey calf raise","name_en":"Donkey Calf Raise","aliases_fr":["Extension des mollets buste penché"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"calf-raise","variant_of":null,"equipment":[],"primary_muscles":["gastrocnemius"],"secondary_muscles":["soleus"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["legs","calves"],"instructions_fr":["Penche-toi à partir des hanches et pose les mains au sol devant toi, hanches hautes et jambes presque tendues.","Place les pieds à largeur de hanches, le poids sur l'avant des pieds.","Descends les talons le plus bas possible (sous le bord si tu es sur une plateforme surélevée) pour un étirement complet.","Monte sur la pointe des pieds le plus haut possible en serrant les mollets.","Redescends de façon contrôlée jusqu'à un étirement profond."],"image_main":null,"image_start":"/exercises/donkey-calf-raise/start.webp","image_end":"/exercises/donkey-calf-raise/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-donkey-calf-raise"],"attribution_required":true,"exportable":false},
{"id":"e2ec9602-222a-5da7-8e99-002fa09246e1","key":"doorway-chest-stretch","name_fr":"Étirement pectoraux dans l'encadrement","name_en":"Doorway Chest Stretch","aliases_fr":["Étirement pectoraux à la porte"],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Tiens-toi debout et lève les bras en position de poteau de but.","Plie les coudes à quatre-vingt-dix degrés, avant-bras à la verticale.","Ramène les coudes vers l'arrière et rapproche les omoplates.","Tiens la position 20 à 30 secondes en respirant calmement."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-doorway-chest-stretch"],"attribution_required":true,"exportable":false},
{"id":"74603130-8795-5065-84c9-993531aa991f","key":"double-db-kickstand-deadlift","name_fr":"Soulevé de terre kickstand deux haltères","name_en":"Double Dumbbell Kickstand Deadlift","aliases_fr":["Kickstand deadlift deux haltères"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"deadlift","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["gluteus_maximus","hamstrings"],"secondary_muscles":["adductors","erector_spinae"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["legs","pull"],"instructions_fr":["Recule un pied pour que seuls les orteils touchent le sol, et penche-toi en charnière de hanches, dos plat.","Tiens un haltère dans chaque main, bas de chaque côté de la jambe avant.","Pousse dans le talon avant et étends les hanches pour te redresser, haltères le long du corps.","Garde l'essentiel du poids sur le pied avant tout au long du mouvement.","Redescends en charnière en amenant les deux haltères vers le sol, dos plat. Change de côté après toutes les répétitions."],"image_main":null,"image_start":"/exercises/double-db-kickstand-deadlift/start.webp","image_end":"/exercises/double-db-kickstand-deadlift/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-double-db-kickstand-deadlift"],"attribution_required":true,"exportable":false},
{"id":"048b4a15-83f1-58d1-a425-1fb30f63b8f5","key":"double-db-overhead-carry","name_fr":"Overhead carry haltères","name_en":"Double Dumbbell Overhead Carry","aliases_fr":["Marche haltères au-dessus de la tête"],"aliases_en":["Double DB overhead carry"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["dumbbell"],"primary_muscles":["anterior_deltoid","lateral_deltoid"],"secondary_muscles":["erector_spinae","serratus_anterior","transverse_abdominis","trapezius","triceps_brachii"],"difficulty":"intermediate","metrics":["distance_m","duration_s","load_kg"],"unilateral":false,"bodyweight":false,"tags":["shoulders","shoulder_stability","core","full_body"],"instructions_fr":["Épaule ou presse un haltère jusqu'au verrouillage au-dessus de chaque épaule.","Tends complètement les deux coudes et continue de pousser vers le haut dans les haltères pour garder les épaules actives, sans les laisser s'affaisser sur toi.","Gaine fort et garde les côtes basses : avec les deux bras en l'air, la tentation de cambrer est bien plus forte.","Avance à petits pas bien contrôlés, les deux haltères alignés au-dessus des épaules.","Respire de façon courte et régulière au lieu de bloquer ta respiration pendant tout le trajet.","Marche sur la distance voulue, puis redescends les deux charges en contrôlant."],"image_main":"/exercises/double-db-overhead-carry/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-double-db-overhead-carry"],"attribution_required":true,"exportable":false},
{"id":"687e3e2f-8a47-529f-b0fa-8e407b11b5a6","key":"double-kettlebell-bicep-curl","name_fr":"Curl biceps deux kettlebells","name_en":"Double Kettlebell Bicep Curl","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["biceps_brachii"],"secondary_muscles":["brachialis","forearm_flexors"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms","pull"],"instructions_fr":["Tiens-toi debout avec un kettlebell dans chaque main par la poignée, paumes vers l'avant.","Garde les coudes collés au corps et les kettlebells pendants, bras tendus.","Monte les deux kettlebells vers les épaules en fléchissant les coudes.","Serre les biceps en haut, puis redescends de façon contrôlée à la position de départ.","Répète pour le nombre de répétitions recommandé."],"image_main":null,"image_start":"/exercises/double-kettlebell-bicep-curl/start.webp","image_end":"/exercises/double-kettlebell-bicep-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-double-kettlebell-bicep-curl"],"attribution_required":true,"exportable":false},
{"id":"6e8cbad4-ba98-5749-92e6-a132debb2abe","key":"double-kettlebell-clean","name_fr":"Épaulé deux kettlebells","name_en":"Double Kettlebell Clean","aliases_fr":["Double kettlebell clean"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["kettlebell"],"primary_muscles":["gluteus_maximus","hamstrings"],"secondary_muscles":["anterior_deltoid","erector_spinae","forearm_flexors","trapezius"],"difficulty":"advanced","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Tiens-toi debout avec deux kettlebells au sol entre tes pieds, poignées légèrement inclinées vers l'intérieur.","Charnière aux hanches, attrape les poignées et envoie les kettlebells vers l'arrière entre les jambes.","Étends explosivement les hanches pour amener les kettlebells le long du corps.","Quand elles arrivent à hauteur de poitrine, glisse les mains à travers les poignées pour les réceptionner en position rack sur les épaules.","Redescends en position suspendue en fléchissant aux hanches et en guidant les kettlebells entre les jambes.","Répète pour le nombre de répétitions recommandé."],"image_main":null,"image_start":"/exercises/double-kettlebell-clean/start.webp","image_end":"/exercises/double-kettlebell-clean/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-double-kettlebell-clean"],"attribution_required":true,"exportable":false},
{"id":"3966193f-093f-589f-8e8d-72610d2ba308","key":"double-kettlebell-clean-and-press","name_fr":"Épaulé-développé deux kettlebells","name_en":"Double Kettlebell Clean and Press","aliases_fr":["Clean and press deux kettlebells"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"clean","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["anterior_deltoid","lateral_deltoid"],"secondary_muscles":["gluteus_maximus","quadriceps","rectus_abdominis","trapezius","triceps_brachii"],"difficulty":"advanced","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Place deux kettlebells au sol entre tes pieds, pieds à peu près à largeur de hanches, et penche-toi en avant en charnière de hanches pour saisir une poignée dans chaque main.","Pousse avec les jambes et étends les hanches de façon explosive pour monter les deux kettlebells, puis passe les coudes dessous et réceptionne les kettlebells en position rack devant les épaules.","Gaine les abdominaux et pousse les deux kettlebells au-dessus de la tête jusqu'à verrouiller complètement les bras.","Redescends les kettlebells en position rack, puis jusqu'au sol, sous contrôle.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/double-kettlebell-clean-and-press/start.webp","image_end":"/exercises/double-kettlebell-clean-and-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-double-kettlebell-clean-and-press"],"attribution_required":true,"exportable":false},
{"id":"1a2ac4fc-d798-53ff-a828-0e1d99d048e3","key":"double-kettlebell-dead-clean","name_fr":"Dead clean deux kettlebells","name_en":"Double Kettlebell Dead Clean","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"clean","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["gluteus_maximus","hamstrings"],"secondary_muscles":["erector_spinae","forearm_flexors","quadriceps","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg"],"unilateral":false,"bodyweight":false,"tags":["olympic_lifting"],"instructions_fr":["Place deux kettlebells au sol entre tes pieds.","Penche-toi en charnière de hanches et saisis les deux poignées.","Pousse fort avec les jambes et les hanches de façon explosive.","Monte les kettlebells et fais-les pivoter en position rack.","Redescends-les au sol et répète."],"image_main":null,"image_start":"/exercises/double-kettlebell-dead-clean/start.webp","image_end":"/exercises/double-kettlebell-dead-clean/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-double-kettlebell-dead-clean"],"attribution_required":true,"exportable":false},
{"id":"0d2d76d9-c36c-560f-bd93-a42f90a9b871","key":"double-kettlebell-dead-split-snatch","name_fr":"Arraché deux kettlebells départ sol en fente","name_en":"Double Kettlebell Dead Split Snatch","aliases_fr":["Dead split snatch double kettlebell"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"snatch","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["anterior_deltoid","gluteus_maximus"],"secondary_muscles":["erector_spinae","hamstrings","quadriceps","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg"],"unilateral":false,"bodyweight":false,"tags":["olympic_lifting"],"instructions_fr":["Pose deux kettlebells au sol entre tes pieds.","Descends en te penchant à partir des hanches et saisis fermement les deux anses.","Tire les kettlebells au-dessus de la tête de façon explosive, en un seul mouvement.","Passe en position de fente pour les réceptionner bras verrouillés.","Reviens en ramenant les pieds l'un vers l'autre."],"image_main":null,"image_start":"/exercises/double-kettlebell-dead-split-snatch/start.webp","image_end":"/exercises/double-kettlebell-dead-split-snatch/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-double-kettlebell-dead-split-snatch"],"attribution_required":true,"exportable":false},
{"id":"57e341b3-c457-51dd-b0c9-e015db3310b6","key":"double-kettlebell-jerk","name_fr":"Jeté deux kettlebells","name_en":"Double Kettlebell Jerk","aliases_fr":["Double kettlebell jerk"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["kettlebell"],"primary_muscles":["anterior_deltoid","quadriceps"],"secondary_muscles":["gluteus_maximus","trapezius","triceps_brachii"],"difficulty":"advanced","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Pars avec deux kettlebells en position rack sur les épaules, coudes posés sur les hanches.","Fais une courte flexion des genoux, puis étends explosivement les jambes pour propulser les kettlebells vers le haut.","Pendant qu'elles montent, fais une seconde flexion pour te glisser dessous en fléchissant à nouveau les genoux.","Réceptionne les kettlebells au-dessus de la tête, bras verrouillés, puis redresse-toi complètement.","Redescends-les en position rack en contrôlant et recommence."],"image_main":null,"image_start":"/exercises/double-kettlebell-jerk/start.webp","image_end":"/exercises/double-kettlebell-jerk/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-double-kettlebell-jerk"],"attribution_required":true,"exportable":false},
{"id":"e3544aa8-0f5e-5d68-a4ad-a0f5a7c693b8","key":"double-kettlebell-overhead-carry","name_fr":"Overhead carry kettlebells","name_en":"Double Kettlebell Overhead Carry","aliases_fr":["Marche kettlebells au-dessus de la tête"],"aliases_en":["Double KB overhead carry"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["kettlebell"],"primary_muscles":["anterior_deltoid","lateral_deltoid"],"secondary_muscles":["erector_spinae","forearm_extensors","serratus_anterior","transverse_abdominis","trapezius","triceps_brachii"],"difficulty":"advanced","metrics":["distance_m","duration_s","load_kg"],"unilateral":false,"bodyweight":false,"tags":["shoulders","shoulder_stability","core","full_body"],"instructions_fr":["Épaule deux kettlebells en position rack, puis presse-les ou fais un push press jusqu'au verrouillage au-dessus de la tête.","Tends les deux coudes et stabilise chaque kettlebell derrière et au-dessus du poignet, poignets droits.","Descends les côtes et gaine fort avant le premier pas : avec les deux kettlebells en l'air, rien ne te sert de contrepoids.","Avance à petits pas contrôlés, les deux kettlebells alignés au-dessus des épaules.","Regarde droit devant toi et respire régulièrement pendant tout le trajet.","Parcours la distance voulue, puis ramène les deux kettlebells en rack et au sol en contrôlant."],"image_main":"/exercises/double-kettlebell-overhead-carry/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-double-kettlebell-overhead-carry"],"attribution_required":true,"exportable":false},
{"id":"9f84c9e1-bde0-5ce8-9ce9-be5de9f01144","key":"double-kettlebell-overhead-press","name_fr":"Développé militaire deux kettlebells","name_en":"Double Kettlebell Overhead Press","aliases_fr":[],"aliases_en":["Double KB press"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-press","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["anterior_deltoid","triceps_brachii"],"secondary_muscles":["rectus_abdominis","serratus_anterior","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Épaule deux kettlebells en position rack, à hauteur des épaules.","Tiens-toi droit, pieds à largeur de hanches.","Pousse les deux kettlebells à la verticale au-dessus de la tête.","Verrouille les bras en haut.","Redescends en position rack et répète."],"image_main":null,"image_start":"/exercises/double-kettlebell-overhead-press/start.webp","image_end":"/exercises/double-kettlebell-overhead-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-double-kettlebell-overhead-press"],"attribution_required":true,"exportable":false},
{"id":"03e6344d-e074-5507-bd15-6c2b1437f64a","key":"double-kettlebell-push-press","name_fr":"Push press deux kettlebells","name_en":"Double Kettlebell Push Press","aliases_fr":[],"aliases_en":["Double KB push press"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-press","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["anterior_deltoid"],"secondary_muscles":["gluteus_maximus","lateral_deltoid","quadriceps","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Tiens-toi debout avec deux kettlebells en rack sur les épaules, coudes vers le bas et rentrés.","Pieds à largeur d'épaules, abdominaux gainés.","Fléchis légèrement les genoux en gardant le torse vertical.","Étends les jambes de façon explosive et pousse les deux kettlebells au-dessus de la tête en un seul mouvement.","Verrouille les bras avec les kettlebells à l'aplomb du milieu du pied.","Redescends en rack de façon contrôlée.","Répète pour le nombre de répétitions prévu."],"image_main":null,"image_start":"/exercises/double-kettlebell-push-press/start.webp","image_end":"/exercises/double-kettlebell-push-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-double-kettlebell-push-press"],"attribution_required":true,"exportable":false},
{"id":"013bf99c-0fa4-5275-8ca8-3f56682f347d","key":"double-kettlebell-rear-delt-row","name_fr":"Rowing deltoïdes postérieurs deux kettlebells","name_en":"Double Kettlebell Rear Delt Row","aliases_fr":["Oiseau deux kettlebells"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"rear-delt-row","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["posterior_deltoid","rhomboids"],"secondary_muscles":["biceps_brachii","erector_spinae","latissimus_dorsi","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull","shoulders"],"instructions_fr":["Place une kettlebell juste à l'extérieur de chaque pied, pieds écartés à environ largeur de hanches.","Penche-toi à partir des hanches, dos plat, jusqu'à ce que le buste soit presque parallèle au sol, genoux légèrement fléchis.","Prends les deux poignées en pronation et laisse les bras pendre droit sous les épaules.","Tire les deux kettlebells vers le haut en écartant les coudes sur les côtés, loin des côtes plutôt que le long d'elles.","Arrête quand les bras sont à peu près dans l'alignement des épaules, et rapproche les omoplates.","Redescends les kettlebells en contrôlant jusqu'à ce que les bras pendent de nouveau droit, et répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/double-kettlebell-rear-delt-row/start.webp","image_end":"/exercises/double-kettlebell-rear-delt-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-double-kettlebell-rear-delt-row"],"attribution_required":true,"exportable":false},
{"id":"4610bb5c-ab38-54c4-a23c-942682771ef1","key":"double-kettlebell-row","name_fr":"Rowing deux kettlebells","name_en":"Double Kettlebell Row","aliases_fr":["Rowing double kettlebell"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"row","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["latissimus_dorsi","rhomboids"],"secondary_muscles":["biceps_brachii","erector_spinae","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Tiens un kettlebell dans chaque main et penche le buste en avant en partant des hanches.","Laisse tes bras pendre à la verticale depuis les épaules.","Tire les deux kettlebells vers tes hanches en emmenant les coudes vers l'arrière.","Serre les omoplates en haut.","Redescends de façon contrôlée et répète."],"image_main":null,"image_start":"/exercises/double-kettlebell-row/start.webp","image_end":"/exercises/double-kettlebell-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-double-kettlebell-row"],"attribution_required":true,"exportable":false},
{"id":"9959dfb2-2661-5edb-8fcb-c38dc33bef63","key":"double-kettlebell-split-jerk","name_fr":"Jeté fendu deux kettlebells","name_en":"Double Kettlebell Split Jerk","aliases_fr":["Split jerk deux kettlebells"],"aliases_en":["Double KB split jerk"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"jerk","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["anterior_deltoid","quadriceps"],"secondary_muscles":["gluteus_maximus","trapezius","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg"],"unilateral":false,"bodyweight":false,"tags":["olympic_lifting"],"instructions_fr":["Épaule deux kettlebells en position rack, à hauteur des épaules.","Fais une légère flexion en fléchissant les genoux.","Projette les kettlebells au-dessus de la tête de façon explosive.","Écarte les jambes en fente pour les réceptionner bras verrouillés.","Reviens en ramenant les pieds l'un vers l'autre."],"image_main":null,"image_start":"/exercises/double-kettlebell-split-jerk/start.webp","image_end":"/exercises/double-kettlebell-split-jerk/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-double-kettlebell-split-jerk"],"attribution_required":true,"exportable":false},
{"id":"71162f2d-4d07-5de0-8c99-c551287b25d6","key":"double-kettlebell-swing-snatch","name_fr":"Arraché deux kettlebells en swing","name_en":"Double Kettlebell Swing Snatch","aliases_fr":["Swing snatch double kettlebell"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"snatch","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["gluteus_maximus","hamstrings"],"secondary_muscles":["anterior_deltoid","erector_spinae","forearm_flexors","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg"],"unilateral":false,"bodyweight":false,"tags":["olympic_lifting"],"instructions_fr":["Tiens-toi debout, pieds à largeur d'épaules, avec deux kettlebells.","Fléchis les hanches pour balancer les kettlebells entre tes jambes.","Pousse les hanches vers l'avant de façon explosive pour propulser les kettlebells vers le haut.","Passe sous les kettlebells pour les réceptionner au-dessus de la tête, bras verrouillés.","Redescends de façon contrôlée et répète."],"image_main":null,"image_start":"/exercises/double-kettlebell-swing-snatch/start.webp","image_end":"/exercises/double-kettlebell-swing-snatch/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-double-kettlebell-swing-snatch"],"attribution_required":true,"exportable":false},
{"id":"c83eecb0-3cfa-5c46-b9ce-b2426254c195","key":"downward-dog","name_fr":"Chien tête en bas","name_en":"Downward-Facing Dog","aliases_fr":["Adho Mukha Svanasana"],"aliases_en":["Down dog"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["gastrocnemius","hamstrings"],"secondary_muscles":["erector_spinae","gluteus_maximus","latissimus_dorsi"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Mets-toi à quatre pattes, mains légèrement devant les épaules.","Replie les orteils et pousse les hanches vers le haut et l'arrière.","Tends les jambes et pousse les talons vers le sol.","Tiens la position 20 à 30 secondes en respirant calmement."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-downward-dog"],"attribution_required":true,"exportable":false},
{"id":"60e4034b-6d70-5dff-81ef-82ea9f354d6d","key":"downward-dog-knee-tuck","name_fr":"Chien tête en bas avec genou vers la poitrine","name_en":"Downward Dog Knee Tuck","aliases_fr":["Downward dog knee tuck"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["hip_flexors","rectus_abdominis"],"secondary_muscles":["anterior_deltoid","serratus_anterior","transverse_abdominis"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["core","calisthenics"],"instructions_fr":["Place-toi en chien tête en bas, mains à largeur d'épaules et hanches hautes.","Pousse le sol loin de toi et gaine le tronc pour garder le bas du dos allongé.","Ramène un genou vers la poitrine en arrondissant légèrement le haut du dos.","Étends la jambe vers l'arrière jusqu'à la position de départ en contrôlant.","Recommence avec l'autre jambe et continue d'alterner pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/downward-dog-knee-tuck/start.webp","image_end":"/exercises/downward-dog-knee-tuck/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-downward-dog-knee-tuck"],"attribution_required":true,"exportable":false},
{"id":"974171d9-51f9-5678-b11d-9c83c9227f1c","key":"downward-dog-pedal","name_fr":"Chien tête en bas, pédalage","name_en":"Downward Dog Pedal","aliases_fr":[],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["gastrocnemius","soleus"],"secondary_muscles":["hamstrings"],"difficulty":"beginner","metrics":["reps","duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Mets-toi en chien tête en bas, mains à largeur d'épaules et hanches hautes.","Plie un genou et laisse ce talon se lever pendant que le talon opposé s'appuie vers le sol.","Change de côté de façon fluide, comme si tu pédalais, en gardant les hanches hautes tout du long.","Appuie de façon égale sur les mains pour garder les épaules stables.","Continue d'alterner pour le nombre de répétitions ou la durée voulus."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-downward-dog-pedal"],"attribution_required":true,"exportable":false},
{"id":"f6ac3056-aca6-53ba-9228-03a0a2fa2389","key":"downward-dog-to-knee-drive","name_fr":"Chien tête en bas vers genou au coude","name_en":"Downward Dog to Knee Drive","aliases_fr":["Downward dog knee drive"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["hip_flexors","rectus_abdominis"],"secondary_muscles":["anterior_deltoid","gluteus_maximus","serratus_anterior"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":true,"bodyweight":true,"tags":["core","calisthenics"],"instructions_fr":["Place-toi en chien tête en bas et lève une jambe derrière toi en chien à trois jambes.","Appuie fort sur les deux mains et déplace légèrement le poids vers l'avant.","Arrondis le haut du dos et ramène ce genou vers le coude ou le nez.","Étends à nouveau la jambe vers le haut, en chien à trois jambes, en contrôlant.","Termine les répétitions de ce côté, puis recommence de l'autre."],"image_main":null,"image_start":"/exercises/downward-dog-to-knee-drive/start.webp","image_end":"/exercises/downward-dog-to-knee-drive/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-downward-dog-to-knee-drive"],"attribution_required":true,"exportable":false},
{"id":"01ccd23c-83bd-5e51-8957-8fe645506f97","key":"downward-dog-to-low-lunge","name_fr":"Chien tête en bas vers fente basse","name_en":"Downward Dog to Low Lunge","aliases_fr":[],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["hip_flexors"],"secondary_muscles":["gluteus_maximus","quadriceps"],"difficulty":"beginner","metrics":["reps","duration_s"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":["Pars en chien tête en bas, mains à largeur d'épaules.","Avance le poids du corps et amène un pied entre les mains.","Pose le genou arrière au sol et descends les hanches en fente basse.","Repousse-toi avec les mains, lève le genou arrière et ramène le pied avant en arrière pour revenir en chien tête en bas.","Recommence de l'autre côté et continue d'alterner."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-downward-dog-to-low-lunge"],"attribution_required":true,"exportable":false},
{"id":"5418acff-46ef-5db9-998c-13d5190de15e","key":"downward-dog-to-plank","name_fr":"Chien tête en bas vers planche","name_en":"Downward Dog to Plank","aliases_fr":["Downward dog to plank"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["anterior_deltoid","rectus_abdominis"],"secondary_muscles":["hamstrings","serratus_anterior","trapezius"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["calisthenics"],"instructions_fr":["Place-toi en chien tête en bas, hanches hautes et mains à largeur d'épaules.","Déplace le poids vers l'avant et descends les hanches jusqu'à former une ligne droite en planche haute.","Tiens la planche un instant, côtes rentrées et fessiers contractés.","Pousse le sol loin de toi et remonte les hanches pour revenir en chien tête en bas.","Continue d'alterner pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/downward-dog-to-plank/start.webp","image_end":"/exercises/downward-dog-to-plank/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-downward-dog-to-plank"],"attribution_required":true,"exportable":false},
{"id":"570dfac2-3641-5abf-bf70-0eeec2579590","key":"downward-dog-to-upward-dog","name_fr":"Chien tête en bas vers chien tête en haut","name_en":"Downward Dog to Upward Dog","aliases_fr":["Downward dog to upward dog"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["anterior_deltoid","erector_spinae"],"secondary_muscles":["pectoralis_major","serratus_anterior","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["calisthenics"],"instructions_fr":["Commence en chien tête en bas, hanches hautes et mains à largeur d'épaules.","Avance en passant par la planche et descends légèrement, puis pousse la poitrine vers l'avant en chien tête en haut, cuisses décollées du sol.","Ramène les épaules en arrière et vers le bas, et garde la nuque longue.","Replie les orteils, pousse le sol loin de toi et remonte les hanches pour revenir en chien tête en bas.","Continue d'enchaîner les deux positions pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/downward-dog-to-upward-dog/start.webp","image_end":"/exercises/downward-dog-to-upward-dog/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-downward-dog-to-upward-dog"],"attribution_required":true,"exportable":false},
{"id":"f208e182-354f-5e7d-9c57-26677da3fcc4","key":"drag-curl","name_fr":"Drag curl","name_en":"Drag Curl","aliases_fr":["Curl en traînée"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"barbell-curl","variant_of":null,"equipment":["barbell"],"primary_muscles":["biceps_brachii"],"secondary_muscles":["brachialis"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull","arms"],"instructions_fr":["Tiens-toi debout avec une barre en prise supination, mains à largeur d'épaules.","Pars avec la barre à hauteur des cuisses et les coudes le long du corps.","Monte la barre en la faisant glisser (la traîner) droit le long du corps.","Pendant la montée, laisse les coudes partir vers l'arrière pour que la barre reste au contact du buste.","Arrête-toi quand la barre arrive au milieu de la poitrine : les biceps sont alors complètement contractés.","Redescends de façon contrôlée par le même chemin et répète."],"image_main":null,"image_start":"/exercises/drag-curl/start.webp","image_end":"/exercises/drag-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-drag-curl"],"attribution_required":true,"exportable":false},
{"id":"ee7f97bd-35f6-5c3a-9002-a0e05d33cbd8","key":"dragon-flag","name_fr":"Dragon flag","name_en":"Dragon Flag","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"crunch","variant_of":null,"equipment":[],"primary_muscles":["rectus_abdominis"],"secondary_muscles":["erector_spinae","hip_flexors","obliques","transverse_abdominis"],"difficulty":"advanced","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Allonge-toi sur un banc et agrippe-le fermement derrière la tête.","Lève ton corps pour que seul le haut du dos reste sur le banc.","Garde le corps gainé en ligne droite.","Redescends le corps sous contrôle jusqu'à être presque à l'horizontale.","Remonte et répète."],"image_main":null,"image_start":"/exercises/dragon-flag/start.webp","image_end":"/exercises/dragon-flag/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dragon-flag"],"attribution_required":true,"exportable":false},
{"id":"28d793bc-7265-57b2-83b0-1f1e75b2b312","key":"dumbbell-bench-pull","name_fr":"Tirage haltères sur banc incliné","name_en":"Dumbbell Bench Pull","aliases_fr":["Rowing haltères allongé"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"row","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["latissimus_dorsi","rhomboids"],"secondary_muscles":["biceps_brachii","posterior_deltoid"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull"],"instructions_fr":["Allonge-toi sur le ventre sur un banc incliné, haltères en main.","Laisse tes bras pendre à la verticale.","Tire les haltères vers ta poitrine en serrant les omoplates.","Redescends de façon contrôlée.","Répète."],"image_main":null,"image_start":"/exercises/dumbbell-bench-pull/start.webp","image_end":"/exercises/dumbbell-bench-pull/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-bench-pull"],"attribution_required":true,"exportable":false},
{"id":"ec775a80-44af-5c77-913a-8d26112b021e","key":"dumbbell-calf-raise","name_fr":"Extension des mollets haltères","name_en":"Dumbbell Calf Raise","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"calf-raise","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["gastrocnemius","soleus"],"secondary_muscles":["forearm_flexors"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Tiens-toi debout avec un haltère dans chaque main, le long du corps.","Pose les pieds à plat au sol, ou place l'avant des pieds sur une surface surélevée, talons dans le vide, pour un étirement plus profond.","Pousse sur l'avant des pieds pour monter les talons le plus haut possible.","Serre les mollets en haut du mouvement.","Redescends les talons au sol (ou sous la plateforme) pour étirer les mollets.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/dumbbell-calf-raise/start.webp","image_end":"/exercises/dumbbell-calf-raise/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-calf-raise"],"attribution_required":true,"exportable":false},
{"id":"bdce43fe-943e-5e4b-ba9d-0585ec48e934","key":"dumbbell-clean-and-press","name_fr":"Épaulé-développé haltères","name_en":"Dumbbell Clean and Press","aliases_fr":["Clean and press haltères"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"clean","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["anterior_deltoid","gluteus_maximus","quadriceps"],"secondary_muscles":["erector_spinae","trapezius","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg"],"unilateral":false,"bodyweight":false,"tags":["olympic_lifting"],"instructions_fr":["Tiens-toi debout, pieds à largeur de hanches, un haltère dans chaque main, bras le long du corps.","Penche-toi en charnière de hanches et fléchis légèrement les genoux pour descendre les haltères juste sous les genoux.","Étends explosivement les hanches et les genoux et hausse les épaules pour monter les haltères jusqu'aux épaules, en les réceptionnant coudes vers l'avant.","Fléchis légèrement les genoux et envoie les haltères droit au-dessus de la tête jusqu'à verrouiller les bras.","Redescends les haltères aux épaules, puis le long du corps, sous contrôle.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/dumbbell-clean-and-press/start.webp","image_end":"/exercises/dumbbell-clean-and-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-clean-and-press"],"attribution_required":true,"exportable":false},
{"id":"6b59c743-8fbc-58d6-8256-cc09776e2b16","key":"dumbbell-curl-and-press","name_fr":"Curl et développé haltères","name_en":"Dumbbell Curl and Press","aliases_fr":[],"aliases_en":["Curl to press"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-press","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["anterior_deltoid","biceps_brachii"],"secondary_muscles":["brachialis","lateral_deltoid","trapezius","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms","shoulders"],"instructions_fr":["Tiens-toi droit, pieds à largeur de hanches, avec un haltère dans chaque main le long du corps, paumes vers l'avant.","Monte les deux haltères jusqu'aux épaules en curl, coudes près du corps.","Pousse les haltères au-dessus de la tête jusqu'à avoir les bras complètement tendus.","Redescends les haltères aux épaules de façon contrôlée.","Ramène-les le long du corps en un curl inversé contrôlé, puis répète."],"image_main":null,"image_start":"/exercises/dumbbell-curl-and-press/start.webp","image_end":"/exercises/dumbbell-curl-and-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-curl-and-press"],"attribution_required":true,"exportable":false},
{"id":"64d8df9e-e206-54c6-aad0-0dfb33ce366e","key":"dumbbell-deadlift","name_fr":"Soulevé de terre haltères","name_en":"Dumbbell Deadlift","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"deadlift","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["erector_spinae","gluteus_maximus","hamstrings"],"secondary_muscles":["latissimus_dorsi","quadriceps","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Tiens-toi debout, pieds à largeur de hanches, penche-toi en charnière de hanches, dos plat, et tiens les haltères bas, à hauteur des tibias.","Gaine les abdominaux et garde les haltères près des jambes.","Pousse dans les talons et étends les hanches pour te redresser.","Étends complètement les hanches en haut, sans cambrer excessivement le bas du dos.","Redescends en charnière en faisant glisser les haltères le long des jambes jusqu'aux tibias.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/dumbbell-deadlift/start.webp","image_end":"/exercises/dumbbell-deadlift/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-deadlift"],"attribution_required":true,"exportable":false},
{"id":"948a29c8-502c-553e-a63f-370bafce5235","key":"dumbbell-face-pull","name_fr":"Face pull haltères","name_en":"Dumbbell Face Pull","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"reverse-fly","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["posterior_deltoid","rhomboids"],"secondary_muscles":["biceps_brachii","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Tiens-toi debout ou assis, un haltère dans chaque main, bras tendus devant toi.","Fléchis les coudes et tire les haltères vers ton visage.","Écarte les coudes sur les côtés jusqu'à hauteur d'épaules.","Serre les deltoïdes postérieurs et le haut du dos en haut du mouvement.","Redescends les haltères de façon contrôlée.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/dumbbell-face-pull/start.webp","image_end":"/exercises/dumbbell-face-pull/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-face-pull"],"attribution_required":true,"exportable":false},
{"id":"599515e5-afdf-506f-9789-b4abbc036305","key":"dumbbell-farmers-walk","name_fr":"Farmers carry haltères","name_en":"Dumbbell Farmer's Walk","aliases_fr":["Marche du fermier haltères"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["dumbbell"],"primary_muscles":["forearm_flexors","trapezius"],"secondary_muscles":["gluteus_maximus","obliques","quadriceps","rectus_abdominis"],"difficulty":"beginner","metrics":["distance_m","duration_s","load_kg"],"unilateral":false,"bodyweight":false,"tags":["full_body","grip"],"instructions_fr":["Tiens-toi debout avec un haltère dans chaque main, bras tendus le long du corps.","Rapproche les omoplates et gaine les abdominaux, colonne neutre.","Marche lentement et avec contrôle sur la distance ou la durée prévue, à petits pas.","Garde la poitrine haute et évite de pencher d'un côté en marchant.","Garde une posture solide et stable pendant tout le mouvement."],"image_main":"/exercises/dumbbell-farmers-walk/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-farmers-walk"],"attribution_required":true,"exportable":false},
{"id":"9233fdb4-708e-5ec3-9924-64417f533ffe","key":"dumbbell-floor-press","name_fr":"Floor press haltères","name_en":"Dumbbell Floor Press","aliases_fr":["Développé au sol haltères"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bench-press","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Allonge-toi au sol, un haltère dans chaque main à hauteur de poitrine.","Pousse les haltères vers le haut jusqu'à ce que les bras soient tendus.","Redescends de façon contrôlée jusqu'à ce que les coudes touchent le sol.","Répète."],"image_main":null,"image_start":"/exercises/dumbbell-floor-press/start.webp","image_end":"/exercises/dumbbell-floor-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-floor-press"],"attribution_required":true,"exportable":false},
{"id":"880720ca-824f-5df7-aefa-4ee0c8809ef6","key":"dumbbell-front-raise","name_fr":"Élévations frontales haltères","name_en":"Dumbbell Front Raise","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"front-raise","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["anterior_deltoid"],"secondary_muscles":["lateral_deltoid"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Tiens-toi debout, haltères le long du corps, paumes face aux cuisses.","Lève un ou deux haltères devant toi jusqu'à hauteur d'épaules.","Redescends sous contrôle.","Répète."],"image_main":null,"image_start":"/exercises/dumbbell-front-raise/start.webp","image_end":"/exercises/dumbbell-front-raise/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-front-raise"],"attribution_required":true,"exportable":false},
{"id":"a9205b4e-0e12-5535-86c5-cd180f473339","key":"dumbbell-front-squat","name_fr":"Front squat haltères","name_en":"Dumbbell Front Squat","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"squat","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["erector_spinae","hamstrings","rectus_abdominis"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Tiens un haltère dans chaque main, posés sur le haut des épaules.","Garde les coudes hauts et le buste droit.","Descends les hanches en fléchissant les genoux jusqu'à ce que les cuisses soient parallèles au sol.","Pousse dans les talons pour te relever.","Garde la colonne neutre tout au long du mouvement.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/dumbbell-front-squat/start.webp","image_end":"/exercises/dumbbell-front-squat/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-front-squat"],"attribution_required":true,"exportable":false},
{"id":"015b0cfb-8df5-5252-abf4-09d25263f409","key":"dumbbell-hip-thrust","name_fr":"Hip thrust haltère","name_en":"Dumbbell Hip Thrust","aliases_fr":[],"aliases_en":["DB hip thrust"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"hip-thrust","variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["gluteus_maximus"],"secondary_muscles":["hamstrings","quadriceps"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs","glutes"],"instructions_fr":["Assieds-toi au sol, le haut du dos contre un banc, genoux fléchis, pieds à plat, un haltère posé sur les hanches.","Gaine les abdominaux et pousse dans les talons pour décoller les hanches du sol, jusqu'à former une ligne droite des épaules aux genoux.","Serre fort les fessiers en haut du mouvement, hanches complètement étendues.","Redescends lentement les hanches jusqu'à la position de départ, de façon contrôlée et en gardant la tension.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/dumbbell-hip-thrust/start.webp","image_end":"/exercises/dumbbell-hip-thrust/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-hip-thrust"],"attribution_required":true,"exportable":false},
{"id":"1267302c-445f-5bce-92f8-a35d5ca1907c","key":"dumbbell-pistol-squat","name_fr":"Pistol squat haltères","name_en":"Dumbbell Pistol Squat","aliases_fr":["Squat à une jambe haltères"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"squat","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["gluteus_medius","hamstrings"],"difficulty":"advanced","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["legs"],"instructions_fr":["Tiens-toi droit, un haltère dans chaque main, bras le long du corps.","Lève une jambe tendue devant toi et garde-la tendue pendant tout le mouvement.","Descends en fléchissant le genou de la jambe d'appui, poitrine haute et dos droit.","Descends jusqu'à ce que les fessiers soient proches du talon ou que la cuisse soit parallèle au sol, en gardant l'équilibre.","Pousse dans le talon pour revenir à la position de départ, en tendant complètement la jambe d'appui.","Fais toutes les répétitions d'un côté, puis change de jambe et fais de même de l'autre côté à chaque série."],"image_main":null,"image_start":"/exercises/dumbbell-pistol-squat/start.webp","image_end":"/exercises/dumbbell-pistol-squat/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-pistol-squat"],"attribution_required":true,"exportable":false},
{"id":"f9b27ecf-83e2-5dc6-80b9-e8e3d36f8874","key":"dumbbell-push-press","name_fr":"Push press haltères","name_en":"Dumbbell Push Press","aliases_fr":["Développé poussé haltères"],"aliases_en":["DB push press"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["dumbbell"],"primary_muscles":["anterior_deltoid","triceps_brachii"],"secondary_muscles":["gluteus_maximus","lateral_deltoid","quadriceps","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["shoulders","push"],"instructions_fr":["Tiens-toi debout avec les haltères à hauteur d'épaules, paumes vers l'avant.","Fléchis légèrement les genoux, en quart de squat.","Pousse avec les jambes pour créer de l'élan, puis presse les haltères au-dessus de la tête.","Verrouille les bras en haut.","Redescends les haltères à hauteur d'épaules en contrôlant."],"image_main":null,"image_start":"/exercises/dumbbell-push-press/start.webp","image_end":"/exercises/dumbbell-push-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-push-press"],"attribution_required":true,"exportable":false},
{"id":"0e3dac66-f553-55d7-bb8a-7832f116d144","key":"dumbbell-reverse-fly","name_fr":"Oiseau haltères","name_en":"Dumbbell Reverse Fly","aliases_fr":["Oiseau buste penché"],"aliases_en":["DB reverse fly","Rear Delt Fly"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"reverse-fly","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["posterior_deltoid"],"secondary_muscles":["rhomboids","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Penche le buste en avant en partant des hanches, un haltère dans chaque main, bras pendants.","Garde le dos plat et les genoux légèrement fléchis.","Monte les haltères sur les côtés jusqu'à hauteur d'épaules.","Serre les omoplates l'une vers l'autre en haut.","Redescends les haltères de façon contrôlée.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/dumbbell-reverse-fly/start.webp","image_end":"/exercises/dumbbell-reverse-fly/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-reverse-fly","rear-delt-fly"],"attribution_required":true,"exportable":false},
{"id":"d6b88ff9-d96d-568b-af6d-4cb08bfaa9d1","key":"dumbbell-romanian-deadlift","name_fr":"Soulevé de terre roumain haltères","name_en":"Dumbbell Romanian Deadlift","aliases_fr":[],"aliases_en":["DB RDL"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"deadlift","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["gluteus_maximus","hamstrings"],"secondary_muscles":["erector_spinae","forearm_flexors"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Tiens-toi debout, haltères devant les cuisses, genoux légèrement fléchis.","Penche-toi en charnière de hanches en poussant les fessiers vers l'arrière.","Descends les haltères le long des jambes jusqu'à sentir un étirement des ischio-jambiers.","Garde le dos plat et les épaules en arrière.","Pousse les hanches vers l'avant pour te redresser.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/dumbbell-romanian-deadlift/start.webp","image_end":"/exercises/dumbbell-romanian-deadlift/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-romanian-deadlift"],"attribution_required":true,"exportable":false},
{"id":"54f45553-cf09-5cf9-ae0e-a7e6ba3d84ad","key":"dumbbell-shoulder-press","name_fr":"Développé épaules haltères","name_en":"Dumbbell Shoulder Press","aliases_fr":[],"aliases_en":["DB shoulder press"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-press","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["anterior_deltoid","lateral_deltoid"],"secondary_muscles":["trapezius","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Assis ou debout, tiens des haltères à hauteur d'épaules, paumes vers l'avant.","Pousse les deux haltères au-dessus de la tête jusqu'à avoir les bras complètement tendus.","Garde les abdominaux gainés et évite de cambrer le bas du dos.","Redescends les haltères de façon contrôlée à hauteur d'épaules.","Ne laisse pas les haltères partir derrière la tête.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/dumbbell-shoulder-press/start.webp","image_end":"/exercises/dumbbell-shoulder-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-shoulder-press"],"attribution_required":true,"exportable":false},
{"id":"8aa429f4-cc62-5bf1-8365-b5d123756cc9","key":"dumbbell-side-bend","name_fr":"Inclinaisons latérales haltère","name_en":"Dumbbell Side Bend","aliases_fr":["Flexion latérale haltère"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["dumbbell"],"primary_muscles":["obliques"],"secondary_muscles":["erector_spinae","quadratus_lumborum","transverse_abdominis"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["core"],"instructions_fr":["Tiens-toi debout, bien droit, avec un haltère dans une main le long du corps.","Garde l'autre main sur la hanche ou derrière la tête.","Incline-toi sur le côté de l'haltère en le faisant glisser le long de la cuisse.","Reviens droit, puis incline-toi de l'autre côté en utilisant uniquement les obliques.","Fais toutes les répétitions de chaque côté."],"image_main":null,"image_start":"/exercises/dumbbell-side-bend/start.webp","image_end":"/exercises/dumbbell-side-bend/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-side-bend"],"attribution_required":true,"exportable":false},
{"id":"c9b61221-e0ea-57d1-8fdd-cac7eb0bdec3","key":"dumbbell-snatch","name_fr":"Arraché haltère","name_en":"Dumbbell Snatch","aliases_fr":["Dumbbell snatch"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"snatch","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["anterior_deltoid","gluteus_maximus","trapezius"],"secondary_muscles":["erector_spinae","hamstrings","quadriceps"],"difficulty":"intermediate","metrics":["reps","load_kg"],"unilateral":false,"bodyweight":false,"tags":["olympic_lifting"],"instructions_fr":["Tiens-toi debout, pieds à largeur d'épaules, l'haltère au sol entre tes pieds.","Penche-toi et saisis l'haltère d'une main.","Étends les hanches, les genoux et les chevilles de façon explosive pour tirer l'haltère vers le haut.","Envoie l'haltère au-dessus de la tête en un seul mouvement fluide.","Verrouille le bras et stabilise-toi en haut.","Fais toutes les répétitions d'un côté, puis change de côté."],"image_main":null,"image_start":"/exercises/dumbbell-snatch/start.webp","image_end":"/exercises/dumbbell-snatch/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-snatch"],"attribution_required":true,"exportable":false},
{"id":"ca226e66-23fc-5c8c-bf68-179c0c135d6f","key":"dumbbell-split-squat","name_fr":"Split squat haltères","name_en":"Dumbbell Split Squat","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"squat","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["gluteus_medius","hamstrings"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Place-toi en position fendue, haltères tenus le long du corps.","Garde le buste droit et les abdominaux gainés.","Descends le genou arrière vers le sol en fléchissant les deux genoux.","Arrête-toi quand la cuisse avant est parallèle au sol.","Pousse dans le talon avant pour te relever.","Fais toutes les répétitions d'un côté, puis change de côté."],"image_main":null,"image_start":"/exercises/dumbbell-split-squat/start.webp","image_end":"/exercises/dumbbell-split-squat/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-split-squat"],"attribution_required":true,"exportable":false},
{"id":"b56826b0-1939-5aac-ae64-f6f823a7c03e","key":"dumbbell-tricep-extension","name_fr":"Extension triceps nuque, deux haltères","name_en":"Dumbbell Tricep Extension","aliases_fr":["Extension triceps haltères au-dessus de la tête"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-tricep-extension","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["triceps_brachii"],"secondary_muscles":[],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms"],"instructions_fr":["Tiens-toi debout, un haltère dans chaque main, bras tendus au-dessus de la tête.","Descends les haltères derrière la tête en fléchissant les coudes.","Tends les bras pour revenir à la position de départ.","Garde les coudes près de la tête.","Répète pour le nombre de répétitions prévu."],"image_main":null,"image_start":"/exercises/dumbbell-tricep-extension/start.webp","image_end":"/exercises/dumbbell-tricep-extension/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-tricep-extension"],"attribution_required":true,"exportable":false},
{"id":"6f833627-9068-5f2f-88d7-b7b7d6b98e4e","key":"dumbbell-upright-row","name_fr":"Tirage menton haltères","name_en":"Dumbbell Upright Row","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"upright-row","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["lateral_deltoid","trapezius"],"secondary_muscles":["anterior_deltoid","biceps_brachii","rhomboids"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["shoulders","pull"],"instructions_fr":["Tiens-toi debout avec deux haltères devant les cuisses, paumes face à ton corps.","Tire les haltères droit vers le haut le long du corps, en menant avec les coudes.","Monte jusqu'à ce que les haltères arrivent à hauteur du menton et que les coudes soient au-dessus des poignets.","Marque une courte pause, puis redescends en contrôlant.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/dumbbell-upright-row/start.webp","image_end":"/exercises/dumbbell-upright-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-upright-row"],"attribution_required":true,"exportable":false},
{"id":"4c4a4ca5-f499-506e-955a-b46ac20021be","key":"dumbbell-windmill","name_fr":"Windmill haltère","name_en":"Dumbbell Windmill","aliases_fr":["Moulin à vent haltère"],"aliases_en":["DB windmill"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["dumbbell"],"primary_muscles":["lateral_deltoid","obliques"],"secondary_muscles":["anterior_deltoid","gluteus_medius","hamstrings"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["core","shoulder_stability"],"instructions_fr":["Tiens-toi debout, pieds à largeur d'épaules, un haltère tenu au-dessus de la tête dans une main, bras verrouillé.","Tourne légèrement les pieds à l'opposé du côté de l'haltère, bras tendu et regard sur la charge.","Charnière aux hanches en les poussant vers le côté de l'haltère et descends lentement le buste vers le sol.","Garde le dos droit et le bras de l'haltère vertical en allant chercher ton pied ou le sol avec la main libre.","Inverse le mouvement en poussant avec les hanches et les obliques pour revenir à la position de départ.","Fais toutes les répétitions d'un côté, puis change de côté."],"image_main":null,"image_start":"/exercises/dumbbell-windmill/start.webp","image_end":"/exercises/dumbbell-windmill/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-windmill"],"attribution_required":true,"exportable":false},
{"id":"af505e81-e4b8-5e46-9efb-b8207d6a56c4","key":"dumbbell-wrist-curl","name_fr":"Curl poignets haltère à un bras","name_en":"Dumbbell Wrist Curl","aliases_fr":["Flexion de poignet haltère"],"aliases_en":["DB wrist curl"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["dumbbell"],"primary_muscles":["forearm_flexors"],"secondary_muscles":["brachioradialis"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["arms","grip"],"instructions_fr":["Assieds-toi sur un banc, avant-bras posé sur la cuisse, paume vers le haut.","Tiens un haltère, poignet dépassant du genou.","Laisse l'haltère rouler jusqu'au bout des doigts.","Remonte l'haltère en fléchissant le poignet.","Redescends en contrôlant. Fais toutes les répétitions d'un côté."],"image_main":null,"image_start":"/exercises/dumbbell-wrist-curl/start.webp","image_end":"/exercises/dumbbell-wrist-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-dumbbell-wrist-curl"],"attribution_required":true,"exportable":false},
{"id":"e06b74e3-fe01-5bf7-8324-ee1d3460a62b","key":"eagle-pose","name_fr":"Posture de l'aigle","name_en":"Eagle Pose","aliases_fr":["Eagle pose","Garudasana"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["gluteus_medius","quadriceps"],"secondary_muscles":["posterior_deltoid","trapezius"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":["calisthenics"],"instructions_fr":["Tiens-toi bien droit, fléchis légèrement les deux genoux et transfère le poids sur un pied.","Croise l'autre cuisse par-dessus la cuisse d'appui et accroche le pied derrière le mollet si tu y arrives.","Croise le bras opposé en dessous, enroule les avant-bras et rapproche les paumes l'une de l'autre.","Assieds-toi un peu plus dans la jambe d'appui et tiens la posture pendant la durée prévue, coudes relevés.","Dénoue la posture et recommence de l'autre côté."],"image_main":"/exercises/eagle-pose/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-eagle-pose"],"attribution_required":true,"exportable":false},
{"id":"0eb9b34c-1728-570f-bb67-be31c894657a","key":"easy-pose","name_fr":"Posture facile","name_en":"Easy Pose","aliases_fr":["Sukhasana","Position du tailleur"],"aliases_en":["Sukhasana"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["erector_spinae"],"secondary_muscles":["adductors","gluteus_medius"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Assieds-toi au sol et croise les tibias confortablement, chaque pied sous le genou opposé.","Assieds-toi sur une couverture pliée ou un coussin jusqu'à ce que les genoux soient plus bas que les hanches.","Empile les côtes au-dessus du bassin et pose les mains sur les cuisses.","Tiens l'assise le temps prévu, en respirant lentement et régulièrement.","Change le tibia placé devant à la série suivante pour que les deux côtés travaillent autant."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-easy-pose"],"attribution_required":true,"exportable":false},
{"id":"022fc8fe-7dd5-5546-91b4-fb50fc14ea28","key":"elliptical-trainer","name_fr":"Vélo elliptique","name_en":"Elliptical Trainer","aliases_fr":["Elliptique"],"aliases_en":[],"category":"cardio","visibility":"active","disciplines":["cardio"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["elliptical"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["gastrocnemius","hamstrings","latissimus_dorsi","pectoralis_major","soleus","triceps_brachii"],"difficulty":"beginner","metrics":["duration_s","distance_m","calories_kcal"],"unilateral":false,"bodyweight":false,"tags":["full_body","conditioning"],"instructions_fr":["Monte sur les pédales un pied à la fois, en tenant la barre centrale fixe jusqu'à être stable, puis prends une poignée mobile dans chaque main.","Lance le mouvement des pédales vers l'avant, en gardant tout le pied à plat sur la pédale sans lever le talon.","Pousse une poignée vers l'avant pendant que le pied opposé avance, et tire l'autre vers toi, pour que bras et jambes travaillent en opposition.","Tiens-toi droit, hanches au-dessus des pédales et abdominaux gainés, sans te laisser pendre aux poignées.","Règle la résistance et l'inclinaison pour tenir une foulée fluide, et continue pendant la durée ou la distance voulue."],"image_main":"/exercises/elliptical-trainer/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-elliptical-trainer"],"attribution_required":true,"exportable":false},
{"id":"4135d52c-7b60-52a3-b6d9-2b45f8bbb9a1","key":"extended-side-angle","name_fr":"Angle latéral étendu","name_en":"Extended Side Angle Pose","aliases_fr":["Extended side angle","Utthita Parsvakonasana"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["obliques","quadriceps"],"secondary_muscles":["adductors","gluteus_medius"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":["calisthenics"],"instructions_fr":["Place-toi debout jambes écartées, pied avant tourné vers l'extérieur et pied arrière légèrement vers l'intérieur.","Fléchis le genou avant au-dessus de la cheville et garde la jambe arrière tendue.","Pose l'avant-bras avant sur la cuisse, ou la main au sol ou sur une brique, et tends le bras du haut par-dessus l'oreille.","Tiens la position pendant la durée prévue en tournant la poitrine vers le plafond.","Tends la jambe avant pour remonter et recommence de l'autre côté."],"image_main":"/exercises/extended-side-angle/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-extended-side-angle"],"attribution_required":true,"exportable":false},
{"id":"bfa0f755-3172-5047-b0ff-b289d6077569","key":"ez-bar-bench-press","name_fr":"Développé couché barre EZ","name_en":"EZ-Bar Bench Press","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bench-press","variant_of":null,"equipment":["ez_bar","bench"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Allonge-toi à plat sur un banc, les pieds posés au sol, et prends la barre EZ dans ses courbes au-dessus de la poitrine.","Décroche la barre et tiens-la au-dessus du bas de la poitrine, bras tendus.","Descends la barre de façon contrôlée vers le bas de la poitrine.","Repousse la barre jusqu'à l'extension complète des bras.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/ez-bar-bench-press/start.webp","image_end":"/exercises/ez-bar-bench-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-ez-bar-bench-press"],"attribution_required":true,"exportable":false},
{"id":"293de28f-6440-55b9-a272-5f25bbdc9156","key":"ez-bar-curl","name_fr":"Curl barre EZ","name_en":"EZ-Bar Curl","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["ez_bar"],"primary_muscles":["biceps_brachii"],"secondary_muscles":["brachialis","brachioradialis"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms"],"instructions_fr":["Tiens-toi debout avec une barre EZ, en supination sur les parties inclinées.","Monte la barre vers les épaules en gardant les coudes collés au corps.","Serre en haut, puis redescends de façon contrôlée.","Répète."],"image_main":null,"image_start":"/exercises/ez-bar-curl/start.webp","image_end":"/exercises/ez-bar-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-ez-bar-curl"],"attribution_required":true,"exportable":false},
{"id":"ed8da4d3-0642-5d38-bef6-78d9979fcf58","key":"ez-bar-front-raise","name_fr":"Élévations frontales barre EZ","name_en":"EZ-Bar Front Raise","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"front-raise","variant_of":null,"equipment":["ez_bar"],"primary_muscles":["anterior_deltoid"],"secondary_muscles":["serratus_anterior"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Tiens-toi debout, barre EZ en pronation sur les courbes intérieures, bras pendants devant les cuisses.","Garde les coudes légèrement fléchis et fixes tout au long du mouvement.","Lève la barre en un arc fluide jusqu'à hauteur d'épaules.","Marque une courte pause en haut, puis redescends sous contrôle.","Répète pour le nombre de répétitions conseillé."],"image_main":null,"image_start":"/exercises/ez-bar-front-raise/start.webp","image_end":"/exercises/ez-bar-front-raise/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-ez-bar-front-raise"],"attribution_required":true,"exportable":false},
{"id":"4a3d3084-2abb-5cb1-beff-cfb1c50924e5","key":"ez-bar-lying-tricep-extension","name_fr":"Extension triceps allongé barre EZ","name_en":"EZ-Bar Lying Triceps Extension","aliases_fr":["Barre au front EZ"],"aliases_en":["EZ bar skull crusher"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"skull-crusher","variant_of":null,"equipment":["ez_bar","bench"],"primary_muscles":["triceps_brachii"],"secondary_muscles":[],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms"],"instructions_fr":["Allonge-toi sur un banc plat, barre EZ tenue au-dessus de la poitrine, prise serrée.","Descends la barre vers le front en fléchissant les coudes.","Tends les bras pour revenir au départ.","Répète."],"image_main":null,"image_start":"/exercises/ez-bar-lying-tricep-extension/start.webp","image_end":"/exercises/ez-bar-lying-tricep-extension/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-ez-bar-lying-tricep-extension"],"attribution_required":true,"exportable":false},
{"id":"95e4cc6e-5add-5d68-bc66-db12b4b89903","key":"ez-bar-overhead-extension","name_fr":"Extension triceps barre EZ au-dessus de la tête","name_en":"EZ-Bar Overhead Tricep Extension","aliases_fr":["Barre au front debout barre EZ"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-tricep-extension","variant_of":null,"equipment":["ez_bar"],"primary_muscles":["triceps_brachii"],"secondary_muscles":[],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms","push"],"instructions_fr":["Tiens-toi debout ou assis, barre EZ au-dessus de la tête, en pronation sur les courbes intérieures.","Bras en extension complète, barre au-dessus de la tête.","Fléchis uniquement les coudes pour descendre la barre derrière la tête en arc de cercle.","Garde les bras verticaux et près de la tête : seuls les avant-bras bougent.","Tends les coudes pour ramener la barre au-dessus de la tête.","Répète pour le nombre de répétitions prévu."],"image_main":null,"image_start":"/exercises/ez-bar-overhead-extension/start.webp","image_end":"/exercises/ez-bar-overhead-extension/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-ez-bar-overhead-extension"],"attribution_required":true,"exportable":false},
{"id":"386e72fa-cc22-526b-bd9d-575b9a62bcf2","key":"ez-bar-pullover","name_fr":"Pull-over barre EZ","name_en":"EZ Bar Pullover","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"pullover","variant_of":null,"equipment":["ez_bar","bench"],"primary_muscles":["latissimus_dorsi","pectoralis_major"],"secondary_muscles":["serratus_anterior","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull","push"],"instructions_fr":["Allonge-toi sur le dos sur un banc plat, la tête légèrement dépassant du bout, une barre EZ en pronation.","Tends la barre au-dessus de la poitrine en gardant une légère flexion des coudes.","Descends lentement la barre en arc de cercle derrière la tête en sentant l'étirement des dorsaux et de la poitrine.","Ramène la barre en position de départ avec les dorsaux et les pectoraux.","Garde le contrôle pendant tout le mouvement, sans élan."],"image_main":null,"image_start":"/exercises/ez-bar-pullover/start.webp","image_end":"/exercises/ez-bar-pullover/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-ez-bar-pullover"],"attribution_required":true,"exportable":false},
{"id":"a0e4aa6a-af2f-5780-b95e-af7ef0b17544","key":"ez-bar-reverse-curl","name_fr":"Curl inversé barre EZ","name_en":"EZ-Bar Reverse Curl","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["ez_bar"],"primary_muscles":["brachialis","forearm_extensors"],"secondary_muscles":["biceps_brachii"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms"],"instructions_fr":["Tiens une barre EZ en pronation.","Monte la barre vers les épaules.","Redescends de façon contrôlée.","Répète."],"image_main":null,"image_start":"/exercises/ez-bar-reverse-curl/start.webp","image_end":"/exercises/ez-bar-reverse-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-ez-bar-reverse-curl"],"attribution_required":true,"exportable":false},
{"id":"63138a40-1120-5db2-b781-c98e8c9c086d","key":"ez-bar-reverse-grip-row","name_fr":"Rowing barre EZ prise supination","name_en":"EZ Bar Reverse Grip Row","aliases_fr":["Rowing barre EZ supination"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"row","variant_of":null,"equipment":["ez_bar"],"primary_muscles":["biceps_brachii","latissimus_dorsi"],"secondary_muscles":["posterior_deltoid","rhomboids","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull"],"instructions_fr":["Tiens-toi debout, pieds à largeur d'épaules, la barre EZ en supination, mains à largeur d'épaules.","Penche le buste en partant des hanches, genoux légèrement fléchis et dos droit, jusqu'à ce que le torse soit presque parallèle au sol.","Laisse la barre pendre juste sous les épaules, bras complètement tendus.","Tire la barre vers le bas des abdominaux en serrant les omoplates et en emmenant les coudes vers le haut.","Contrôle la phase excentrique, en redescendant lentement la barre jusqu'à la position de départ, bras complètement tendus."],"image_main":null,"image_start":"/exercises/ez-bar-reverse-grip-row/start.webp","image_end":"/exercises/ez-bar-reverse-grip-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-ez-bar-reverse-grip-row"],"attribution_required":true,"exportable":false},
{"id":"fe792f5c-b8e2-5a6b-8c5c-85f16472a6b6","key":"ez-bar-romanian-deadlift","name_fr":"Soulevé de terre roumain barre EZ","name_en":"EZ-Bar Romanian Deadlift","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"deadlift","variant_of":null,"equipment":["ez_bar"],"primary_muscles":["gluteus_maximus","hamstrings"],"secondary_muscles":["erector_spinae","forearm_flexors","trapezius"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs","pull"],"instructions_fr":["Tiens-toi debout, barre EZ à mi-cuisses, en pronation sur les courbes intérieures.","Pieds à largeur de hanches, genoux légèrement fléchis, poitrine haute, dorsaux engagés.","Pousse les hanches vers l'arrière en laissant la barre glisser le long de l'avant des jambes.","Descends jusqu'à sentir un fort étirement des ischio-jambiers, sans arrondir le bas du dos.","Pousse les hanches vers l'avant pour te redresser, en gardant la barre près du corps.","Répète pour le nombre de répétitions conseillé."],"image_main":null,"image_start":"/exercises/ez-bar-romanian-deadlift/start.webp","image_end":"/exercises/ez-bar-romanian-deadlift/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-ez-bar-romanian-deadlift"],"attribution_required":true,"exportable":false},
{"id":"ad5ef58f-2303-52c9-8f04-31ac364003b9","key":"ez-bar-shrug","name_fr":"Shrugs barre EZ","name_en":"EZ-Bar Shrug","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"shrug","variant_of":null,"equipment":["ez_bar"],"primary_muscles":["trapezius"],"secondary_muscles":["rhomboids"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Tiens-toi debout avec une barre EZ devant toi.","Hausse les épaules à la verticale.","Marque une pause en haut, puis redescends.","Répète."],"image_main":null,"image_start":"/exercises/ez-bar-shrug/start.webp","image_end":"/exercises/ez-bar-shrug/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-ez-bar-shrug"],"attribution_required":true,"exportable":false},
{"id":"ed8b8994-ebda-57ab-89b7-aa3446ab3f91","key":"ez-bar-spider-curl","name_fr":"Spider curl barre EZ","name_en":"EZ Bar Spider Curl","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["ez_bar","bench"],"primary_muscles":["biceps_brachii"],"secondary_muscles":["brachialis","brachioradialis"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Allonge-toi face au banc incliné, la poitrine contre le dossier, avec une barre EZ en supination.","Laisse les bras pendre droit sous les épaules.","Monte la barre vers les épaules.","Serre les biceps en haut du mouvement.","Redescends la barre de façon contrôlée.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/ez-bar-spider-curl/start.webp","image_end":"/exercises/ez-bar-spider-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-ez-bar-spider-curl"],"attribution_required":true,"exportable":false},
{"id":"8205e42a-1307-58b4-9a00-edda98b2db8f","key":"ez-bar-upright-row","name_fr":"Tirage menton barre EZ","name_en":"EZ-Bar Upright Row","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"upright-row","variant_of":null,"equipment":["ez_bar"],"primary_muscles":["lateral_deltoid","trapezius"],"secondary_muscles":["anterior_deltoid","biceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Tiens-toi debout avec une barre EZ, mains à largeur d'épaules sur les parties inclinées.","Tire la barre droit vers le haut le long du corps jusqu'au menton.","Mène le mouvement avec les coudes, en les gardant au-dessus des mains.","Redescends en contrôlant.","Répète."],"image_main":null,"image_start":"/exercises/ez-bar-upright-row/start.webp","image_end":"/exercises/ez-bar-upright-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-ez-bar-upright-row"],"attribution_required":true,"exportable":false},
{"id":"117a20f0-e8ca-51bc-92b5-c3a0ef463d0d","key":"ez-bar-wrist-curl","name_fr":"Curl poignets barre EZ","name_en":"EZ-Bar Wrist Curl","aliases_fr":["Flexion de poignets barre EZ"],"aliases_en":["EZ bar wrist curl"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["ez_bar"],"primary_muscles":["forearm_flexors"],"secondary_muscles":[],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms","grip"],"instructions_fr":["Assieds-toi sur un banc, avant-bras posés sur les cuisses, paumes vers le haut.","Prends une barre EZ dans les creux intérieurs, mains à largeur d'épaules.","Laisse la barre rouler jusqu'au bout des doigts.","Remonte la barre en fléchissant les poignets.","Redescends en contrôlant."],"image_main":null,"image_start":"/exercises/ez-bar-wrist-curl/start.webp","image_end":"/exercises/ez-bar-wrist-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-ez-bar-wrist-curl"],"attribution_required":true,"exportable":false},
{"id":"38e22fb9-0c51-59d2-9982-2f5854d96a9e","key":"face-pull","name_fr":"Face pull","name_en":"Cable Face Pull","aliases_fr":["Face pull à la poulie"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"reverse-fly","variant_of":null,"equipment":["cable"],"primary_muscles":["posterior_deltoid","rhomboids"],"secondary_muscles":["trapezius"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull"],"instructions_fr":["Fixe une corde à une poulie haute.","Tire la corde vers ton visage en écartant les extrémités.","Contracte les deltoïdes postérieurs et les rotateurs externes.","Reviens en position de départ en contrôlant.","Répète."],"image_main":null,"image_start":"/exercises/face-pull/start.webp","image_end":"/exercises/face-pull/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-face-pull"],"attribution_required":true,"exportable":false},
{"id":"5a36137f-ed48-5ec5-aaf9-f9059c0994d0","key":"fire-hydrant","name_fr":"Fire hydrant","name_en":"Fire Hydrant","aliases_fr":["Abduction de hanche à quatre pattes"],"aliases_en":["Quadruped hip abduction"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"hip-abduction","variant_of":null,"equipment":[],"primary_muscles":["abductors","gluteus_medius"],"secondary_muscles":["gluteus_maximus","transverse_abdominis"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":true,"bodyweight":true,"tags":["legs","glutes"],"instructions_fr":["Mets-toi à quatre pattes, mains sous les épaules, genoux sous les hanches, dos plat.","Gaine le tronc pour que les hanches restent à niveau et face au sol.","Genou fléchi à environ 90 degrés, lève un genou sur le côté jusqu'à ce que la cuisse soit à peu près parallèle au sol.","Marque une courte pause en haut, sans faire pivoter le bassin ni te pencher du côté opposé.","Redescends le genou à la position de départ sous contrôle.","Fais les répétitions d'un côté, puis change de jambe."],"image_main":null,"image_start":"/exercises/fire-hydrant/start.webp","image_end":"/exercises/fire-hydrant/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-fire-hydrant"],"attribution_required":true,"exportable":false},
{"id":"0a17b083-3bd7-5f04-9690-fbb6e521ad99","key":"fish-pose","name_fr":"Posture du poisson","name_en":"Fish Pose","aliases_fr":["Matsyasana"],"aliases_en":["Matsyasana"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["erector_spinae","pectoralis_major"],"secondary_muscles":["anterior_deltoid","hip_flexors"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Allonge-toi sur le dos, jambes tendues et bras le long du corps, paumes sous les hanches.","Appuie les avant-bras au sol et lève la poitrine vers le plafond.","Laisse le sommet de la tête se poser légèrement au sol sans mettre de poids sur la nuque.","Tiens la position le temps prévu, en respirant vers le haut de la poitrine.","Relève la tête, puis redescends le dos."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-fish-pose"],"attribution_required":true,"exportable":false},
{"id":"1f18cdb9-e968-5149-aefe-893dbd745acc","key":"flexed-arm-hang","name_fr":"Suspension menton au-dessus de la barre","name_en":"Flexed Arm Hang","aliases_fr":["Flexed arm hang"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"static-hold","variant_of":null,"equipment":["pull_up_bar"],"primary_muscles":["biceps_brachii","latissimus_dorsi"],"secondary_muscles":["brachialis","forearm_flexors","rhomboids","trapezius"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":false,"bodyweight":false,"tags":["pull","calisthenics","grip"],"instructions_fr":["Attrape une barre de traction en pronation, un peu plus large que les épaules, ou en supination pour une version plus facile.","Tire-toi vers le haut, ou monte sur un box, jusqu'à ce que le menton soit au-dessus de la barre.","Garde les coudes fléchis et dirigés vers le bas, les épaules éloignées des oreilles.","Maintiens la position sans balancer, jambes serrées et buste gainé.","Redescends lentement en suspension complète quand le menton commence à baisser."],"image_main":"/exercises/flexed-arm-hang/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-flexed-arm-hang"],"attribution_required":true,"exportable":false},
{"id":"9b78a221-eabf-513c-9893-ce4b562b7de1","key":"floor-ez-bar-press","name_fr":"Floor press barre EZ","name_en":"Floor EZ-Bar Press","aliases_fr":["Développé au sol barre EZ"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bench-press","variant_of":null,"equipment":["ez_bar"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Allonge-toi au sol en tenant une barre EZ au-dessus de la poitrine.","Descends la barre jusqu'à ce que les coudes touchent le sol.","Repousse jusqu'à l'extension complète.","Répète."],"image_main":null,"image_start":"/exercises/floor-ez-bar-press/start.webp","image_end":"/exercises/floor-ez-bar-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-floor-ez-bar-press"],"attribution_required":true,"exportable":false},
{"id":"98289dce-c8c8-5a7f-b6eb-42bd17fc52f0","key":"floor-kettlebell-pullover","name_fr":"Pull-over kettlebell au sol","name_en":"Floor Kettlebell Pullover","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"pullover","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["latissimus_dorsi","pectoralis_major"],"secondary_muscles":["serratus_anterior","triceps_brachii"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull"],"instructions_fr":["Allonge-toi sur le dos au sol, genoux fléchis et pieds à plat.","Tiens une kettlebell par la poignée à deux mains au-dessus de la poitrine, bras presque tendus (légère flexion des coudes).","En gardant l'angle des coudes fixe, descends la kettlebell derrière la tête en arc de cercle jusqu'à ce que les bras touchent le sol.","Ramène la kettlebell au-dessus de la poitrine sur le même arc.","Répète pour le nombre de répétitions prévu."],"image_main":null,"image_start":"/exercises/floor-kettlebell-pullover/start.webp","image_end":"/exercises/floor-kettlebell-pullover/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-floor-kettlebell-pullover"],"attribution_required":true,"exportable":false},
{"id":"dbb50f88-5871-57de-953a-148377ff9dac","key":"floor-press","name_fr":"Floor press","name_en":"Floor Press","aliases_fr":["Développé au sol"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bench-press","variant_of":null,"equipment":["barbell"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Allonge-toi au sol et place-toi sous une barre posée sur un rack.","Décroche la barre et descends-la vers la poitrine jusqu'à ce que le haut des bras touche le sol.","Repousse jusqu'au verrouillage des bras.","Répète."],"image_main":null,"image_start":"/exercises/floor-press/start.webp","image_end":"/exercises/floor-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-floor-press"],"attribution_required":true,"exportable":false},
{"id":"d024a7ba-f770-5ec0-a334-482a1e838aea","key":"flutter-kicks","name_fr":"Flutter kicks","name_en":"Flutter Kicks","aliases_fr":["Battements de jambes"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"leg-raise","variant_of":null,"equipment":[],"primary_muscles":["hip_flexors","rectus_abdominis"],"secondary_muscles":["transverse_abdominis"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Allonge-toi à plat sur le dos, jambes tendues.","Place les mains sous les fessiers pour t'appuyer.","Décolle les deux jambes du sol de quelques centimètres.","Alterne des battements de jambes de haut en bas sur une petite amplitude.","Garde les abdominaux gainés et le bas du dos plaqué au sol.","Continue pendant la durée ou le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/flutter-kicks/start.webp","image_end":"/exercises/flutter-kicks/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-flutter-kicks"],"attribution_required":true,"exportable":false},
