{"id":"865511aa-a284-5aae-b066-915fc23e5e3c","key":"frog-stretch","name_fr":"Étirement de la grenouille","name_en":"Frog Stretch","aliases_fr":["Posture de la grenouille"],"aliases_en":["Frog pose"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["adductors"],"secondary_muscles":["gluteus_maximus","hip_flexors"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Mets-toi à quatre pattes au sol, poignets sous les épaules.","Fais glisser les genoux vers l'extérieur aussi loin que c'est confortable et tourne les pieds vers l'extérieur, tibias dans l'alignement des genoux.","Descends sur les avant-bras en gardant le dos droit, sans l'arrondir.","Recule les hanches vers les talons jusqu'à sentir un fort étirement sur l'intérieur des cuisses.","Tiens la position en respirant lentement, les hanches à niveau.","Sors en rapprochant les genoux et en t'asseyant en arrière avant de te relever."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-frog-stretch"],"attribution_required":true,"exportable":false},
{"id":"2783757e-8025-5b62-ba88-33b1a029c30d","key":"front-lever","name_fr":"Front lever","name_en":"Front Lever","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"static-hold","variant_of":null,"equipment":["pull_up_bar"],"primary_muscles":["latissimus_dorsi","pectoralis_major"],"secondary_muscles":["anterior_deltoid","biceps_brachii","erector_spinae","rectus_abdominis"],"difficulty":"advanced","metrics":["duration_s"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Attrape la barre en pronation et suspends-toi.","Groupe les genoux vers la poitrine et tire les bras tendus vers les hanches, en te penchant en arrière jusqu'à ce que le buste soit horizontal et la poitrine face au plafond.","Étends le corps à l'horizontale, bras tendus et poitrine face au plafond.","Garde le corps rigide et parallèle au sol.","Tiens pendant la durée voulue, puis groupe les jambes et redescends en contrôlant."],"image_main":"/exercises/front-lever/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-front-lever"],"attribution_required":true,"exportable":false},
{"id":"93c8b777-8b64-5230-93da-db51ac8b85cf","key":"front-squat","name_fr":"Front squat","name_en":"Front Squat","aliases_fr":["Squat avant"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"squat","variant_of":null,"equipment":["barbell"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["erector_spinae","hamstrings"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs"],"instructions_fr":["Épaule la barre ou prends-la sur un rack, posée sur l'avant des épaules, coudes hauts.","Descends en gardant le buste droit jusqu'à ce que les cuisses soient parallèles.","Remonte.","Répète."],"image_main":null,"image_start":"/exercises/front-squat/start.webp","image_end":"/exercises/front-squat/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-front-squat"],"attribution_required":true,"exportable":false},
{"id":"9857308e-ead8-542f-91fe-cc947df41a7f","key":"garland-pose","name_fr":"Posture de la guirlande","name_en":"Garland Pose","aliases_fr":["Malasana"],"aliases_en":["Malasana","Yogi squat"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["adductors","gluteus_maximus"],"secondary_muscles":["quadriceps","soleus"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Tiens-toi debout, pieds un peu plus écartés que les hanches et orteils légèrement tournés vers l'extérieur.","Descends en squat aussi bas que tes chevilles le permettent, talons au sol.","Joins les paumes devant la poitrine et appuie les coudes contre l'intérieur des genoux.","Tiens la position le temps prévu, la poitrine haute et la colonne allongée.","Pousse sur les pieds pour te relever."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-garland-pose"],"attribution_required":true,"exportable":false},
{"id":"37ad2ff4-0e17-55b9-8aa0-dff64d0e3c57","key":"glute-bridge","name_fr":"Pont fessier","name_en":"Glute Bridge","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"hip-thrust","variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus"],"secondary_muscles":["hamstrings"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["legs"],"instructions_fr":["Allonge-toi sur le dos, genoux fléchis et pieds à plat au sol.","Monte les hanches en serrant les fessiers.","Marque une courte pause en haut, hanches complètement étendues.","Redescends les hanches de façon contrôlée.","Répète."],"image_main":null,"image_start":"/exercises/glute-bridge/start.webp","image_end":"/exercises/glute-bridge/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-glute-bridge"],"attribution_required":true,"exportable":false},
{"id":"b4238247-6227-587f-b7b4-d9d07b32410d","key":"glute-bridge-hold","name_fr":"Pont fessier isométrique","name_en":"Glute Bridge Hold","aliases_fr":["Maintien du pont fessier"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"hip-thrust","variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus"],"secondary_muscles":["hamstrings"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":["legs"],"instructions_fr":["Allonge-toi sur le dos, genoux fléchis et pieds à plat, à peu près à largeur de hanches, assez près pour effleurer tes talons du bout des doigts.","Pousse dans les talons et monte les hanches jusqu'à ce que le corps forme une ligne droite des genoux aux épaules.","Serre les fessiers et rentre les côtes pour que le bas du dos ne prenne pas le relais.","Tiens la position haute pendant la durée prévue, en gardant le poids dans les talons.","Redescends les hanches de façon contrôlée pour terminer la série."],"image_main":"/exercises/glute-bridge-hold/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-glute-bridge-hold"],"attribution_required":true,"exportable":false},
{"id":"826e93fb-0e00-5496-9a5c-0b51c2db49a9","key":"glute-kickback","name_fr":"Kickback fessier au sol","name_en":"Glute Kickback","aliases_fr":["Donkey kick"],"aliases_en":["Quadruped glute kickback"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus"],"secondary_muscles":["erector_spinae","gluteus_medius","hamstrings"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":true,"bodyweight":true,"tags":["legs","glutes"],"instructions_fr":["Mets-toi à quatre pattes, mains sous les épaules et genoux sous les hanches.","Genou fléchi à 90 degrés, pousse un talon vers le plafond.","Contracte le fessier en haut du mouvement.","Ramène la jambe à la position de départ en contrôlant.","Fais toutes les répétitions, puis change de côté."],"image_main":null,"image_start":"/exercises/glute-kickback/start.webp","image_end":"/exercises/glute-kickback/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-glute-kickback"],"attribution_required":true,"exportable":false},
{"id":"bfdd0f51-2c46-5790-bf6b-bd7836e24a82","key":"glute-kickback-hold","name_fr":"Kickback fessier au sol, maintien","name_en":"Glute Kickback Hold","aliases_fr":["Maintien jambe levée à quatre pattes"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus"],"secondary_muscles":["erector_spinae","gluteus_medius","hamstrings"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":["legs","glutes"],"instructions_fr":["Mets-toi à quatre pattes, mains sous les épaules et genoux sous les hanches.","Gaine le tronc et garde le bassin à plat : ne laisse pas le côté qui travaille basculer vers le haut.","Étends une jambe vers l'arrière et vers le haut jusqu'à ce que la cuisse soit dans l'alignement du buste.","Tiens cette position pendant la durée prévue, nuque longue et bas du dos à plat.","Redescends la jambe en contrôlant et recommence de l'autre côté."],"image_main":"/exercises/glute-kickback-hold/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-glute-kickback-hold"],"attribution_required":true,"exportable":false},
{"id":"90d201e1-5bf0-5e09-a057-68df0fd1d970","key":"goblet-squat","name_fr":"Goblet squat","name_en":"Goblet Squat","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"squat","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["hamstrings"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs"],"instructions_fr":["Tiens un kettlebell contre la poitrine, à deux mains.","Descends en gardant la charge près de la poitrine.","Remonte.","Répète."],"image_main":null,"image_start":"/exercises/goblet-squat/start.webp","image_end":"/exercises/goblet-squat/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-goblet-squat"],"attribution_required":true,"exportable":false},
{"id":"d82fb113-ab4e-542c-9ffd-835e930ae071","key":"good-morning","name_fr":"Good morning","name_en":"Good Morning","aliases_fr":["Good morning barre"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"deadlift","variant_of":null,"equipment":["barbell"],"primary_muscles":["erector_spinae","gluteus_maximus","hamstrings"],"secondary_muscles":[],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs"],"instructions_fr":["Tiens-toi debout, une barre posée sur le haut du dos.","Penche-toi en charnière de hanches en les poussant vers l'arrière, dos plat.","Descends le buste jusqu'à être presque parallèle au sol.","Pousse les hanches vers l'avant pour te redresser.","Répète."],"image_main":null,"image_start":"/exercises/good-morning/start.webp","image_end":"/exercises/good-morning/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-good-morning"],"attribution_required":true,"exportable":false},
{"id":"3ea97b7e-2764-5a85-94ed-02f73155b61b","key":"hack-squat","name_fr":"Hack squat","name_en":"Hack Squat","aliases_fr":["Squat à la machine hack"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"squat","variant_of":null,"equipment":["hack_squat"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["gastrocnemius","hamstrings"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Charge la machine de hack squat et monte dessus, le dos et les épaules contre les coussins.","Place les pieds à largeur d'épaules sur la plateforme, pointes légèrement tournées vers l'extérieur.","Déverrouille les poignées de sécurité et descends le chariot en fléchissant les genoux et les hanches.","Descends jusqu'à ce que les cuisses soient au moins parallèles à la plateforme.","Pousse dans les talons pour tendre les jambes et ramener le chariot au départ.","Reverrouille les poignées de sécurité après la dernière répétition."],"image_main":null,"image_start":"/exercises/hack-squat/start.webp","image_end":"/exercises/hack-squat/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-hack-squat"],"attribution_required":true,"exportable":false},
{"id":"4d8c7fae-35c4-57c2-a458-6cee5cb2ff10","key":"hack-squat-calf-raise","name_fr":"Extension des mollets au hack squat","name_en":"Hack Squat Calf Raise","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"calf-raise","variant_of":null,"equipment":["hack_squat"],"primary_muscles":["gastrocnemius","soleus"],"secondary_muscles":[],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Installe-toi dans la machine de hack squat, les épaules sous les coussins.","Place l'avant des pieds sur la plateforme, talons dans le vide.","Garde les jambes tendues avec une légère flexion des genoux.","Pousse sur l'avant des pieds pour monter les talons.","Redescends les talons sous la plateforme pour étirer.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/hack-squat-calf-raise/start.webp","image_end":"/exercises/hack-squat-calf-raise/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-hack-squat-calf-raise"],"attribution_required":true,"exportable":false},
{"id":"725db444-90c0-5b8b-a727-9289f648050d","key":"half-kneeling-hip-flexor-rock","name_fr":"Balancier fléchisseurs de hanche chevalier","name_en":"Half-Kneeling Hip Flexor Rock","aliases_fr":["Balancement fléchisseurs de hanche"],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["hip_flexors"],"secondary_muscles":["gluteus_maximus","quadriceps"],"difficulty":"beginner","metrics":["reps","duration_s"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":["Mets-toi sur un genou, l'autre pied à plat au sol devant toi.","Rentre légèrement le coccyx et gaine le tronc pour que le bas du dos reste neutre.","Balance les hanches vers l'avant jusqu'à sentir l'avant de la cuisse arrière s'allonger.","Reviens en arrière de façon contrôlée et répète de manière rythmée.","Change de côté et répète le même nombre de répétitions."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-half-kneeling-hip-flexor-rock"],"attribution_required":true,"exportable":false},
{"id":"cb61ba9f-7288-5d27-b34b-4c5a62a5b9b5","key":"half-moon-pose","name_fr":"Posture de la demi-lune","name_en":"Half Moon Pose","aliases_fr":["Half moon pose","Ardha Chandrasana"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["gluteus_medius","obliques"],"secondary_muscles":["erector_spinae","quadriceps"],"difficulty":"advanced","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":["core","calisthenics"],"instructions_fr":["Depuis une position debout jambes écartées, fléchis le genou avant et pose la main du bas au sol ou sur une brique, devant le pied avant.","Transfère le poids vers l'avant et lève la jambe arrière jusqu'à ce qu'elle soit parallèle au sol.","Tends la jambe d'appui et empile la hanche du haut sur celle du bas, en tendant le bras du haut vers le plafond.","Tiens l'équilibre pendant la durée prévue, pied levé en flexion.","Repose le pied arrière et recommence de l'autre côté."],"image_main":"/exercises/half-moon-pose/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-half-moon-pose"],"attribution_required":true,"exportable":false},
{"id":"82223a24-703c-5011-bb2f-afc38fd25149","key":"hammer-curl","name_fr":"Curl marteau haltères","name_en":"Dumbbell Hammer Curl","aliases_fr":["Curl marteau"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["biceps_brachii","brachialis"],"secondary_muscles":["forearm_flexors"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms"],"instructions_fr":["Tiens-toi debout avec des haltères le long du corps, paumes face à face.","Monte les haltères en gardant les paumes tournées vers l'intérieur.","Serre en haut, puis redescends de façon contrôlée.","Répète."],"image_main":null,"image_start":"/exercises/hammer-curl/start.webp","image_end":"/exercises/hammer-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-hammer-curl"],"attribution_required":true,"exportable":false},
