{"id":"1ef74fe5-daab-5302-acb9-a83644a20da6","key":"high-plank","name_fr":"Planche haute","name_en":"High Plank","aliases_fr":["Gainage position pompe"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"plank","variant_of":null,"equipment":[],"primary_muscles":["rectus_abdominis","transverse_abdominis"],"secondary_muscles":["erector_spinae","obliques"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":["core","calisthenics"],"instructions_fr":["Mets-toi en position de pompe, bras en extension complète.","Garde le corps aligné de la tête aux talons.","Gaine les abdominaux et tiens la position.","Respire régulièrement tout au long de l'exercice."],"image_main":"/exercises/high-plank/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-high-plank"],"attribution_required":true,"exportable":false},
{"id":"e5aa1c40-2c4c-55d2-ace3-b7e845fa4f3f","key":"hip-abduction","name_fr":"Abduction de hanche à la machine","name_en":"Machine Hip Abduction","aliases_fr":["Machine abducteurs"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"hip-abduction","variant_of":null,"equipment":["hip_abduction_machine"],"primary_muscles":["gluteus_medius"],"secondary_muscles":["abductors"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs"],"instructions_fr":["Assieds-toi sur la machine à abduction, coussins contre l'extérieur des cuisses.","Écarte les jambes contre la résistance.","Maintiens brièvement à l'écart maximal.","Reviens à la position de départ avec contrôle.","Répète."],"image_main":null,"image_start":"/exercises/hip-abduction/start.webp","image_end":"/exercises/hip-abduction/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-hip-abduction"],"attribution_required":true,"exportable":false},
{"id":"00441b99-195a-5aaf-9ec0-a66b6877da3d","key":"hip-adduction","name_fr":"Adduction de hanche à la machine","name_en":"Hip Adduction","aliases_fr":["Machine adducteurs"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"hip-adduction","variant_of":null,"equipment":["hip_adduction_machine"],"primary_muscles":["adductors"],"secondary_muscles":[],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Assieds-toi sur la machine à adduction, dos contre le dossier.","Place les jambes contre les coussins, la machine réglée sur un étirement confortable.","Serre les jambes l'une contre l'autre jusqu'à ce que les coussins se rejoignent au centre.","Maintiens brièvement la contraction en position complètement fermée.","Laisse les jambes s'ouvrir sous contrôle jusqu'au départ.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/hip-adduction/start.webp","image_end":"/exercises/hip-adduction/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-hip-adduction"],"attribution_required":true,"exportable":false},
