{"id":"354a06fb-3935-51c4-abd7-eaaeeedf053b","key":"landmine-press","name_fr":"Landmine press","name_en":"Landmine Press","aliases_fr":["Développé landmine"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["barbell","landmine"],"primary_muscles":["anterior_deltoid","pectoralis_major"],"secondary_muscles":["serratus_anterior","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["shoulders","push"],"instructions_fr":["Cale une extrémité d'une barre dans un support landmine et charge l'autre extrémité avec un disque.","Place-toi en fente décalée ou pieds parallèles et tiens l'extrémité de la barre à deux mains en coupe, à hauteur de poitrine.","Gaine les abdominaux et pousse la barre vers l'avant et vers le haut, selon son arc naturel.","Tends complètement les bras sans verrouiller les coudes, puis redescends la barre en contrôlant.","Garde les deux mains sur la barre pendant tout le mouvement et répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/landmine-press/start.webp","image_end":"/exercises/landmine-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-landmine-press"],"attribution_required":true,"exportable":false},
