{"id":"a0435b79-0ff9-5e70-9c60-9e6109893c3d","key":"lateral-raise","name_fr":"Élévations latérales haltères","name_en":"Dumbbell Lateral Raise","aliases_fr":["Élévations latérales"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"lateral-raise","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["lateral_deltoid"],"secondary_muscles":["anterior_deltoid"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Tiens-toi debout avec un haltère dans chaque main, le long du corps.","Monte les haltères sur les côtés jusqu'à ce que tes bras soient parallèles au sol.","Redescends de façon contrôlée.","Répète."],"image_main":null,"image_start":"/exercises/lateral-raise/start.webp","image_end":"/exercises/lateral-raise/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-lateral-raise"],"attribution_required":true,"exportable":false},
{"id":"9d197551-1ad9-52d1-a1bd-fa91b34e460a","key":"lean-back-90-90-hold","name_fr":"Maintien 90/90 penché en arrière","name_en":"Lean-Back 90/90 Hold","aliases_fr":["90/90 penché en arrière"],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["hip_flexors"],"secondary_muscles":["gluteus_maximus","gluteus_medius"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":["Assieds-toi au sol, la jambe avant pliée devant toi à environ 90 degrés et la jambe arrière sur le côté, également pliée à environ 90 degrés.","Pose les mains au sol derrière les hanches, doigts vers l'arrière ou sur le côté.","Penche le buste en arrière sur les mains, bras tendus et poitrine ouverte.","Laisse les deux genoux descendre vers le sol sans les forcer.","Tiens la position en respirant lentement, avec un étirement léger sur l'extérieur de la hanche de la jambe avant et l'avant de la hanche de la jambe arrière.","Tiens le temps prévu, puis inverse les jambes et tiens de l'autre côté."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-lean-back-90-90-hold"],"attribution_required":true,"exportable":false},
{"id":"8eb07f14-d0b3-5e88-9f86-ff829ec282b6","key":"leg-curl","name_fr":"Leg curl allongé","name_en":"Lying Leg Curl","aliases_fr":["Curl ischio allongé"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"leg-curl","variant_of":null,"equipment":["leg_curl"],"primary_muscles":["hamstrings"],"secondary_muscles":["gastrocnemius"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs"],"instructions_fr":["Allonge-toi face au sol sur la machine de leg curl, chevilles sous le pad.","Ramène les talons vers les fessiers en fléchissant les jambes.","Serre les ischio-jambiers en haut.","Redescends de façon contrôlée.","Répète."],"image_main":null,"image_start":"/exercises/leg-curl/start.webp","image_end":"/exercises/leg-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-leg-curl"],"attribution_required":true,"exportable":false},
{"id":"7d6d981a-51d6-53af-8db2-6fdb8d646e11","key":"leg-extension","name_fr":"Leg extension","name_en":"Leg Extension","aliases_fr":["Extension des jambes"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"leg-extension","variant_of":null,"equipment":["leg_extension"],"primary_muscles":["quadriceps"],"secondary_muscles":[],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs"],"instructions_fr":["Assieds-toi dans la machine de leg extension, chevilles derrière le pad.","Tends les jambes jusqu'à ce qu'elles soient droites.","Serre les quadriceps en haut.","Redescends de façon contrôlée.","Répète."],"image_main":null,"image_start":"/exercises/leg-extension/start.webp","image_end":"/exercises/leg-extension/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-leg-extension"],"attribution_required":true,"exportable":false},
{"id":"e9844c81-7922-5862-b902-f3daa687154f","key":"leg-press","name_fr":"Presse à cuisses","name_en":"Leg Press","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"leg-press","variant_of":null,"equipment":["leg_press"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["hamstrings"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs"],"instructions_fr":["Assieds-toi dans la presse à cuisses, pieds à largeur d'épaules sur la plateforme.","Déverrouille les sécurités et descends la plateforme en fléchissant les genoux.","Repousse la plateforme jusqu'à ce que les jambes soient presque tendues.","Ne verrouille pas les genoux en haut.","Répète."],"image_main":null,"image_start":"/exercises/leg-press/start.webp","image_end":"/exercises/leg-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-leg-press"],"attribution_required":true,"exportable":false},
{"id":"a8af3a39-14a4-5dd0-a062-28890983eb98","key":"leg-swing-front-to-back","name_fr":"Balancés de jambe avant-arrière","name_en":"Front-to-Back Leg Swing","aliases_fr":["Leg swings","Balancements de jambe avant-arrière"],"aliases_en":["Front leg swing","Dynamic leg swings front back"],"category":"mobility","visibility":"hidden","disciplines":["mobility","warmup","running"],"hyrox_station":null,"family":"leg-swing","variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus","hip_flexors"],"secondary_muscles":["hamstrings","rectus_abdominis"],"difficulty":"beginner","metrics":["reps","duration_s"],"unilateral":true,"bodyweight":true,"tags":["legs"],"instructions_fr":["Tiens-toi droit à côté d'un support stable et transfère le poids sur la jambe intérieure.","Gaine le tronc et décolle légèrement du sol le pied extérieur.","Balance la jambe libre vers l'avant sur une amplitude confortable.","Laisse-la partir vers l'arrière derrière le corps sans cambrer le bas du dos.","Continue de façon fluide, puis répète avec l'autre jambe."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-leg-swing-front-to-back","coory-dynamic-leg-swings-front-back"],"attribution_required":true,"exportable":false},
{"id":"08e3f9a6-81e7-5c63-8df7-f18772bc1804","key":"legs-up-the-wall","name_fr":"Jambes au mur","name_en":"Legs-Up-the-Wall Pose","aliases_fr":["Viparita Karani"],"aliases_en":["Viparita Karani"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["hamstrings"],"secondary_muscles":["erector_spinae"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Assieds-toi de côté contre un mur, une hanche qui le touche.","Fais monter les jambes le long du mur en t'allongeant, pour que les hanches finissent près du bas du mur.","Laisse les jambes reposer contre le mur, pieds relâchés et bras ouverts sur les côtés.","Reste ainsi le temps prévu, en respirant lentement.","Plie les genoux et roule sur un côté pour sortir de la posture."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-legs-up-the-wall"],"attribution_required":true,"exportable":false},
{"id":"8af3a92d-a7bd-5dbd-b225-6cb4012bc34a","key":"lizard-stretch","name_fr":"Posture du lézard","name_en":"Lizard Stretch","aliases_fr":["Utthan Pristhasana"],"aliases_en":["Utthan Pristhasana"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["adductors","hip_flexors"],"secondary_muscles":["gluteus_maximus","hamstrings"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":["Avance un pied dans une fente profonde, pied placé bien à l'extérieur.","Descends les deux avant-bras vers le sol, à l'intérieur du pied avant.","Tends la jambe arrière et laisse les hanches descendre.","Tiens la position 20 à 30 secondes en respirant calmement.","Change de côté et recommence."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-lizard-stretch"],"attribution_required":true,"exportable":false},
{"id":"e82c1280-430d-5a7d-93a9-c13f53c234d6","key":"locust-pose","name_fr":"Posture de la sauterelle","name_en":"Locust Pose","aliases_fr":["Locust pose","Salabhasana"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["erector_spinae","gluteus_maximus"],"secondary_muscles":["hamstrings","posterior_deltoid"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":["calisthenics"],"instructions_fr":["Allonge-toi sur le ventre, bras le long du corps et front posé sur le tapis.","Allonge l'arrière de la nuque et étire le bout des doigts vers les pieds.","Décolle en même temps la poitrine, les bras et les deux jambes du sol.","Tiens la position levée pendant la durée prévue, regard vers le bas.","Redescends tout ensemble et récupère."],"image_main":"/exercises/locust-pose/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-locust-pose"],"attribution_required":true,"exportable":false},
{"id":"a274738a-8e64-5943-8c39-646f17de4de0","key":"low-lunge","name_fr":"Fente basse","name_en":"Low Lunge","aliases_fr":["Anjaneyasana"],"aliases_en":["Anjaneyasana"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["hip_flexors","quadriceps"],"secondary_muscles":["erector_spinae","gluteus_maximus"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":["Depuis la position à genoux, avance un pied pour que le genou soit à l'aplomb de la cheville.","Pose le genou arrière au sol et déplie le pied arrière.","Rentre légèrement le coccyx et pousse les hanches vers l'avant jusqu'à sentir l'avant de la cuisse arrière s'allonger.","Sors la poitrine, lève les bras si c'est confortable, et tiens le temps prévu.","Recule le pied et recommence de l'autre côté."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-low-lunge"],"attribution_required":true,"exportable":false},
{"id":"b8b1e78f-6a2f-5765-aef0-f0f4cde8e6b6","key":"low-lunge-to-half-split","name_fr":"Fente basse vers demi-grand écart","name_en":"Low Lunge to Half Split","aliases_fr":[],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["hamstrings"],"secondary_muscles":["gastrocnemius","hip_flexors"],"difficulty":"beginner","metrics":["reps","duration_s"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":["Pars en fente basse, genou arrière au sol et genou avant au-dessus de la cheville.","Appuie les mains au sol ou sur des blocs de chaque côté du pied avant.","Recule les hanches au-dessus du genou arrière et tends la jambe avant, pied fléchi.","Tiens brièvement le demi-grand écart, puis ramène les hanches vers l'avant en fente basse.","Répète le nombre de répétitions voulu, puis change de côté."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-low-lunge-to-half-split"],"attribution_required":true,"exportable":false},
{"id":"68890f03-0a61-54c0-8d1f-234e3b9cf6cb","key":"lunge","name_fr":"Fentes","name_en":"Lunge","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"lunge","variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["erector_spinae","gluteus_medius","hamstrings"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":["Tiens-toi droit, pieds à largeur de hanches.","Fais un grand pas en avant avec une jambe.","Descends le genou arrière vers le sol jusqu'à ce que les deux genoux forment un angle de 90 degrés.","Pousse dans le talon avant pour revenir debout.","Fais toutes les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/lunge/start.webp","image_end":"/exercises/lunge/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-lunge"],"attribution_required":true,"exportable":false},
{"id":"5fa3e288-37d4-5cab-94af-c121232a2d7f","key":"lying-leg-raise","name_fr":"Relevé de jambes allongé","name_en":"Lying Leg Raise","aliases_fr":["Lying leg raise"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["hip_flexors","rectus_abdominis"],"secondary_muscles":["obliques","transverse_abdominis"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["core"],"instructions_fr":["Allonge-toi à plat sur le dos, jambes tendues, mains sous le bas du dos ou accrochées à un support stable derrière la tête.","Jambes serrées et abdominaux gainés, monte-les jusqu'à la verticale (ou aussi haut que ta souplesse le permet).","Marque une courte pause en haut.","Redescends lentement les jambes vers le sol sans les poser.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/lying-leg-raise/start.webp","image_end":"/exercises/lying-leg-raise/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-lying-leg-raise"],"attribution_required":true,"exportable":false},
{"id":"43e5985b-d783-5d6b-a041-ff10314b964b","key":"lying-quad-stretch","name_fr":"Étirement quadriceps allongé sur le côté","name_en":"Lying Quad Stretch","aliases_fr":["Étirement quadriceps couché"],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["quadriceps"],"secondary_muscles":["hip_flexors"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":["Allonge-toi sur le côté, jambes tendues et tête posée sur le bras du dessous.","Plie le genou du dessus et attrape ce pied ou cette cheville avec la main du dessus.","Tire doucement le talon vers ton fessier, genoux proches l'un de l'autre.","Rentre légèrement le bassin pour que le bas du dos ne se cambre pas.","Tiens l'étirement le temps prévu en respirant lentement.","Relâche le pied, roule de l'autre côté et recommence."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-lying-quad-stretch"],"attribution_required":true,"exportable":false},
{"id":"a76f3d7a-295a-5740-988d-4ed66edf53b0","key":"lying-tricep-extension","name_fr":"Extension triceps allongé haltère","name_en":"Lying Tricep Extension","aliases_fr":["Barre au front haltère"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"skull-crusher","variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["triceps_brachii"],"secondary_muscles":["anterior_deltoid"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Allonge-toi à plat sur un banc, un haltère tenu à deux mains à la verticale au-dessus de la poitrine.","Garde les bras presque à la verticale, coudes pointés vers le plafond.","Descends l'haltère derrière la tête en fléchissant les coudes.","Tends les bras pour revenir à la position de départ.","Serre les triceps en haut.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/lying-tricep-extension/start.webp","image_end":"/exercises/lying-tricep-extension/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-lying-tricep-extension"],"attribution_required":true,"exportable":false},
{"id":"7a562976-1a3d-5bc7-889d-16079e6a90ce","key":"machine-back-extension","name_fr":"Extension lombaire à la machine","name_en":"Machine Back Extension","aliases_fr":["Lombaires à la machine"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"back-extension","variant_of":null,"equipment":["back_extension_machine"],"primary_muscles":["erector_spinae"],"secondary_muscles":["gluteus_maximus","hamstrings"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Assieds-toi dans la machine à lombaires, les pieds à plat sur le repose-pieds et le coussin placé derrière le haut du dos, juste sous les omoplates.","Attrape les poignées sur les côtés et laisse le buste s'incliner légèrement vers l'avant : c'est la position de départ.","Pousse contre le coussin en étendant la colonne jusqu'à ce que le buste soit incliné vers l'arrière et que les lombaires soient bien contractées.","Marque une courte pause en extension complète, puis reviens à la position de départ de façon contrôlée, en résistant à la charge.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/machine-back-extension/start.webp","image_end":"/exercises/machine-back-extension/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-machine-back-extension"],"attribution_required":true,"exportable":false},
{"id":"908e5bc5-939b-50ef-b102-7301b759d467","key":"machine-bicep-curl","name_fr":"Curl biceps à la machine","name_en":"Machine Bicep Curl","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["bicep_curl_machine"],"primary_muscles":["biceps_brachii"],"secondary_muscles":["brachialis"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms"],"instructions_fr":["Assieds-toi dans la machine et règle le coussin selon la longueur de tes bras.","Prends les poignées en supination.","Monte les poignées vers les épaules.","Redescends de façon contrôlée.","Répète."],"image_main":null,"image_start":"/exercises/machine-bicep-curl/start.webp","image_end":"/exercises/machine-bicep-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-machine-bicep-curl"],"attribution_required":true,"exportable":false},
{"id":"8788e204-1b91-5dc1-b276-4ccbb3d9bfed","key":"machine-calf-raise","name_fr":"Extension des mollets debout à la machine","name_en":"Machine Calf Raise","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"calf-raise","variant_of":null,"equipment":["standing_calf_raise_machine"],"primary_muscles":["gastrocnemius","soleus"],"secondary_muscles":[],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Place-toi dans la machine à mollets, l'avant des pieds sur la plateforme.","Cale bien les épaulières.","Descends les talons sous la plateforme pour un étirement complet.","Pousse sur l'avant des pieds pour monter sur la pointe des pieds.","Serre les mollets en haut.","Redescends de façon contrôlée et répète."],"image_main":null,"image_start":"/exercises/machine-calf-raise/start.webp","image_end":"/exercises/machine-calf-raise/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-machine-calf-raise"],"attribution_required":true,"exportable":false},
{"id":"c2b14421-814f-590d-923f-fb30adc78b76","key":"machine-chest-fly","name_fr":"Écarté à la machine","name_en":"Machine Chest Fly","aliases_fr":["Butterfly"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"chest-fly","variant_of":null,"equipment":["chest_fly_machine"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid","serratus_anterior"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Assieds-toi sur la machine à écarté et règle le siège pour que les poignées soient à hauteur de poitrine.","Saisis les poignées, coudes légèrement fléchis.","Rapproche les poignées devant ta poitrine en un arc fluide.","Contracte fortement les pectoraux en fin de mouvement.","Reviens à la position de départ sous contrôle, sans laisser retomber la charge.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/machine-chest-fly/start.webp","image_end":"/exercises/machine-chest-fly/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-machine-chest-fly"],"attribution_required":true,"exportable":false},
{"id":"f11a1083-c529-5943-b8e2-084800ef35ca","key":"machine-preacher-curl","name_fr":"Curl pupitre à la machine","name_en":"Machine Preacher Curl","aliases_fr":["Preacher curl machine"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["preacher_curl_machine"],"primary_muscles":["biceps_brachii"],"secondary_muscles":["brachialis"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms"],"instructions_fr":["Assieds-toi à la machine à curl pupitre et règle le siège pour que tes aisselles soient en haut du coussin.","Pose les bras à plat sur le coussin et attrape les poignées.","Pars bras tendus, mais sans les verrouiller, en bas du mouvement.","Monte les poignées en fléchissant les coudes et contracte fort en haut.","Redescends lentement à la position de départ et répète."],"image_main":null,"image_start":"/exercises/machine-preacher-curl/start.webp","image_end":"/exercises/machine-preacher-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-machine-preacher-curl"],"attribution_required":true,"exportable":false},
{"id":"d199df63-1712-5009-ac0d-5112ef7dd0e0","key":"machine-reverse-fly","name_fr":"Oiseau à la machine","name_en":"Machine Reverse Fly","aliases_fr":["Reverse pec deck"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"reverse-fly","variant_of":null,"equipment":["reverse_fly_machine"],"primary_muscles":["posterior_deltoid"],"secondary_muscles":["rhomboids","trapezius"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Règle le siège pour que les poignées soient à hauteur d'épaules, puis assieds-toi face à la machine, la poitrine contre le coussin.","Saisis les poignées, bras tendus devant toi avec une légère flexion des coudes.","Garde les épaules basses, loin des oreilles, et gaine le tronc.","Ouvre les poignées vers l'extérieur et l'arrière en un large arc, en menant avec les coudes, jusqu'à ce que les bras soient à peu près alignés avec les épaules.","Serre brièvement les omoplates sans te décoller du coussin en arrière.","Ramène lentement les poignées vers l'avant et répète pour le nombre de répétitions prévu."],"image_main":null,"image_start":"/exercises/machine-reverse-fly/start.webp","image_end":"/exercises/machine-reverse-fly/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-machine-reverse-fly"],"attribution_required":true,"exportable":false},
{"id":"be66ca44-2afc-5409-a9fb-3282e86c1cb0","key":"machine-seated-crunch","name_fr":"Crunch assis à la machine","name_en":"Machine Seated Crunch","aliases_fr":["Crunch à la machine"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"crunch","variant_of":null,"equipment":["ab_crunch_machine"],"primary_muscles":["rectus_abdominis"],"secondary_muscles":["obliques","transverse_abdominis"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Assieds-toi sur la machine à abdominaux et saisis les poignées.","Place le coussin contre le haut du buste.","Contracte les abdominaux pour enrouler le buste vers l'avant et le bas.","Marque une contraction en bas du mouvement.","Reviens à la position de départ avec contrôle.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/machine-seated-crunch/start.webp","image_end":"/exercises/machine-seated-crunch/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-machine-seated-crunch"],"attribution_required":true,"exportable":false},
{"id":"e9c419aa-2261-5863-95cc-1efe51a1eab5","key":"machine-shoulder-press","name_fr":"Développé épaules à la machine","name_en":"Machine Shoulder Press","aliases_fr":[],"aliases_en":["Shoulder press machine"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-press","variant_of":null,"equipment":["shoulder_press_machine"],"primary_muscles":["anterior_deltoid","lateral_deltoid"],"secondary_muscles":["trapezius","triceps_brachii"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Assieds-toi dans la machine, le dos contre le pad.","Attrape les poignées à hauteur d'épaules.","Pousse les poignées au-dessus de la tête jusqu'à avoir les bras complètement tendus.","Redescends de façon contrôlée à la position de départ.","Répète."],"image_main":null,"image_start":"/exercises/machine-shoulder-press/start.webp","image_end":"/exercises/machine-shoulder-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-machine-shoulder-press"],"attribution_required":true,"exportable":false},
{"id":"ed1a8a6b-57d5-5731-aa01-74b64a158312","key":"machine-triceps-extension","name_fr":"Extension triceps à la machine","name_en":"Machine Triceps Extension","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"tricep-pushdown","variant_of":null,"equipment":["tricep_extension_machine"],"primary_muscles":["triceps_brachii"],"secondary_muscles":[],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms"],"instructions_fr":["Assieds-toi dans la machine à extension triceps, dos contre le dossier et haut des bras posés à plat sur le coussin devant ta poitrine.","Prends une poignée dans chaque main, coudes fléchis et mains près de la hauteur des épaules.","Haut des bras plaqués contre le coussin, étends les coudes pour pousser les poignées vers le bas et l'avant jusqu'à avoir les bras tendus.","Serre les triceps en extension complète, puis fléchis les coudes pour revenir en contrôlant.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/machine-triceps-extension/start.webp","image_end":"/exercises/machine-triceps-extension/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-machine-triceps-extension"],"attribution_required":true,"exportable":false},
{"id":"0c9d5c4a-41f7-50c5-8c61-6c97c341a778","key":"medicine-ball-side-throw","name_fr":"Lancer latéral de médecine ball","name_en":"Medicine Ball Side Throw","aliases_fr":["Rotational throw"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"ball-slam","variant_of":null,"equipment":["medicine_ball"],"primary_muscles":["obliques"],"secondary_muscles":["anterior_deltoid","gluteus_maximus","pectoralis_major","rectus_abdominis"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["core","ballistic"],"instructions_fr":["Tiens-toi debout, pieds un peu plus larges que les épaules, un médecine ball à deux mains devant le buste.","Tourne le buste et le ballon vers la hanche arrière, genoux légèrement fléchis et poitrine haute.","Lance le mouvement en ramenant la hanche arrière vers l'avant et en pivotant sur l'avant du pied arrière.","Laisse le buste et les bras suivre, et lance le ballon sur le côté à deux mains.","Termine face à la direction du lancer, bras tendus.","Va chercher le ballon, replace-toi et répète pour le nombre de répétitions prévu, puis change de côté."],"image_main":null,"image_start":"/exercises/medicine-ball-side-throw/start.webp","image_end":"/exercises/medicine-ball-side-throw/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-medicine-ball-side-throw"],"attribution_required":true,"exportable":false},
{"id":"8cf08b0b-adc1-5908-98fb-9364b574f20e","key":"medicine-ball-slam","name_fr":"Slam ball","name_en":"Medicine Ball Slam","aliases_fr":["Medicine ball slam"],"aliases_en":["Ball slam"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"ball-slam","variant_of":null,"equipment":["slam_ball"],"primary_muscles":["rectus_abdominis"],"secondary_muscles":["gluteus_maximus","latissimus_dorsi","obliques"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["core"],"instructions_fr":["Tiens-toi debout, pieds à largeur d'épaules, un slam ball devant les hanches.","Monte le ballon au-dessus de la tête en étendant les hanches et en t'étirant vers le haut.","Écrase le ballon au sol entre tes pieds avec force, en contractant les abdominaux.","Rattrape le ballon au rebond ou ramasse-le au sol.","Répète pour le nombre de répétitions recommandé."],"image_main":null,"image_start":"/exercises/medicine-ball-slam/start.webp","image_end":"/exercises/medicine-ball-slam/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-medicine-ball-slam"],"attribution_required":true,"exportable":false},
{"id":"f11866c5-47d9-55df-82d6-81f836594ab4","key":"mountain-climbers","name_fr":"Mountain climbers","name_en":"Mountain Climbers","aliases_fr":["Grimpeurs"],"aliases_en":[],"category":"cardio","visibility":"active","disciplines":["cardio"],"hyrox_station":null,"family":"leg-raise","variant_of":null,"equipment":[],"primary_muscles":["hip_flexors","rectus_abdominis"],"secondary_muscles":["obliques","quadriceps"],"difficulty":"beginner","metrics":["duration_s","reps"],"unilateral":false,"bodyweight":true,"tags":["core"],"instructions_fr":["Mets-toi en planche haute.","Ramène un genou vers la poitrine.","Change de jambe rapidement en ramenant l'autre genou vers l'avant.","Continue en alternant à un rythme soutenu.","Répète."],"image_main":null,"image_start":"/exercises/mountain-climbers/start.webp","image_end":"/exercises/mountain-climbers/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-mountain-climbers"],"attribution_required":true,"exportable":false},
{"id":"22cc0115-cfe6-58d1-a3ef-2c4f10d80068","key":"mountain-pose","name_fr":"Posture de la montagne","name_en":"Mountain Pose","aliases_fr":["Tadasana"],"aliases_en":["Tadasana"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["erector_spinae"],"secondary_muscles":["gastrocnemius","quadriceps"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Tiens-toi debout, pieds à largeur de hanches, le poids réparti également sur les deux pieds.","Contracte légèrement les cuisses et laisse le coccyx descendre pour que le bassin soit neutre.","Empile les côtes au-dessus du bassin et la tête au-dessus des côtes, bras relâchés le long du corps.","Tiens la posture le temps prévu, en respirant régulièrement.","Repère où se place le poids et rééquilibre-le vers le milieu de chaque pied."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-mountain-pose"],"attribution_required":true,"exportable":false},
{"id":"555db013-3d26-55ec-947a-e46e865eed99","key":"muscle-snatch","name_fr":"Muscle snatch","name_en":"Muscle Snatch","aliases_fr":["Arraché en force sans réception"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"snatch","variant_of":null,"equipment":["barbell"],"primary_muscles":["lateral_deltoid","trapezius"],"secondary_muscles":["erector_spinae","gluteus_maximus","hamstrings"],"difficulty":"intermediate","metrics":["reps","load_kg"],"unilateral":false,"bodyweight":false,"tags":["olympic_lifting"],"instructions_fr":["Tiens-toi debout, pieds à largeur de hanches, et saisis la barre en prise large avec un hook grip.","Tire la barre du sol de façon explosive en la gardant près du corps.","Hausse fortement les épaules et tire la barre au-dessus de la tête sans passer dessous.","Verrouille la barre au-dessus de la tête, bras tendus.","Redescends la barre de façon contrôlée jusqu'à la position de départ.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/muscle-snatch/start.webp","image_end":"/exercises/muscle-snatch/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-muscle-snatch"],"attribution_required":true,"exportable":false},
{"id":"1e00e114-961d-50ed-9871-7b9db8345ab7","key":"muscle-ups","name_fr":"Muscle-ups","name_en":"Muscle Ups","aliases_fr":["Muscle up"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["pull_up_bar"],"primary_muscles":["latissimus_dorsi","triceps_brachii"],"secondary_muscles":["anterior_deltoid","biceps_brachii","pectoralis_major"],"difficulty":"advanced","metrics":["reps","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Suspends-toi à une barre de traction en prise false grip.","Tire-toi explosivement vers la barre.","Quand la poitrine arrive à la barre, fais passer les coudes par-dessus et enchaîne sur un dip.","Pousse le corps vers le haut jusqu'à avoir les bras complètement tendus au-dessus de la barre.","Redescends en contrôlant par le même trajet.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/muscle-ups/start.webp","image_end":"/exercises/muscle-ups/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-muscle-ups"],"attribution_required":true,"exportable":false},
