{"id":"7bb00770-a7c7-5cb3-8d34-963825e52e62","key":"neck-side-stretch","name_fr":"Étirement latéral de la nuque","name_en":"Neck Side Stretch","aliases_fr":[],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["trapezius"],"secondary_muscles":[],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":["Assieds-toi ou tiens-toi debout, bien droit, les épaules relâchées.","Incline la tête pour amener une oreille vers l'épaule du même côté.","Pose la main de ce côté légèrement sur ta tête pour ajouter un peu de poids.","Tiens la position 20 à 30 secondes en respirant calmement.","Change de côté et recommence."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-neck-side-stretch"],"attribution_required":true,"exportable":false},
{"id":"2124573f-2fdc-5f8b-844e-01e1316e0f22","key":"negative-pull-ups","name_fr":"Tractions négatives","name_en":"Negative Pull Ups","aliases_fr":["Négatives tractions"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"pull-up","variant_of":null,"equipment":["pull_up_bar"],"primary_muscles":["latissimus_dorsi"],"secondary_muscles":["biceps_brachii","forearm_flexors","posterior_deltoid","rhomboids"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Utilise un box ou saute pour te placer en haut d'une traction.","Prends la barre, mains à largeur d'épaules.","Maintiens le menton au-dessus de la barre un court instant.","Descends lentement en 3 à 5 secondes en contrôlant.","Étends complètement les bras en bas.","Reviens en position de départ et répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/negative-pull-ups/start.webp","image_end":"/exercises/negative-pull-ups/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-negative-pull-ups"],"attribution_required":true,"exportable":false},
{"id":"932ff0c9-6f6c-585c-8790-18f1ae92ba83","key":"neutral-grip-pull-ups","name_fr":"Tractions prise neutre","name_en":"Neutral Grip Pull Ups","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"pull-up","variant_of":null,"equipment":["pull_up_bar"],"primary_muscles":["latissimus_dorsi"],"secondary_muscles":["biceps_brachii","brachialis","forearm_flexors","rhomboids"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Prends des barres parallèles, paumes face à face.","Suspends-toi bras en extension complète.","Tire-toi jusqu'à ce que le menton passe au-dessus de la barre.","Contracte les dorsaux en haut du mouvement.","Redescends en contrôlant jusqu'à la position de départ.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/neutral-grip-pull-ups/start.webp","image_end":"/exercises/neutral-grip-pull-ups/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-neutral-grip-pull-ups"],"attribution_required":true,"exportable":false},
{"id":"b463405d-e6a4-5cae-8c82-260582f87201","key":"nordic-hamstring-curl","name_fr":"Nordic curl","name_en":"Nordic Hamstring Curl","aliases_fr":["Nordic hamstring"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"leg-curl","variant_of":null,"equipment":["glute_ham_developer"],"primary_muscles":["hamstrings"],"secondary_muscles":["gastrocnemius","gluteus_maximus"],"difficulty":"advanced","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Mets-toi à genoux sur un pad, chevilles bloquées sous un support fixe.","Garde le torse droit et les hanches étendues.","Descends lentement le corps vers l'avant en freinant avec les ischio-jambiers.","Rattrape-toi avec les mains juste avant de toucher le sol.","Repousse-toi pour revenir à la position de départ.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/nordic-hamstring-curl/start.webp","image_end":"/exercises/nordic-hamstring-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-nordic-hamstring-curl"],"attribution_required":true,"exportable":false},
