{"id":"82832fb6-48a3-56a2-ae74-fe6dc99165e8","key":"ohp","name_fr":"Développé militaire","name_en":"Barbell Overhead Press","aliases_fr":["Développé épaules barre"],"aliases_en":["OHP","Overhead press"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-press","variant_of":null,"equipment":["barbell"],"primary_muscles":["anterior_deltoid","lateral_deltoid"],"secondary_muscles":["trapezius","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Tiens-toi debout, pieds à largeur d'épaules, la barre à hauteur des clavicules.","Gaine les abdominaux et pousse la barre au-dessus de la tête.","Verrouille les bras en haut, la barre à l'aplomb du milieu du pied.","Redescends la barre à hauteur des clavicules.","Répète."],"image_main":null,"image_start":"/exercises/ohp/start.webp","image_end":"/exercises/ohp/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-ohp"],"attribution_required":true,"exportable":false},
{"id":"323801aa-1260-5b51-8c0d-6675729d57c7","key":"one-arm-dumbbell-preacher-curl","name_fr":"Curl pupitre haltère à un bras","name_en":"One Arm Dumbbell Preacher Curl","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["biceps_brachii"],"secondary_muscles":["brachialis","brachioradialis"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["arms"],"instructions_fr":["Assieds-toi au pupitre et pose l'arrière du haut d'un bras à plat sur le coussin.","Tiens un haltère de cette main, paume vers le haut, le bras presque tendu.","Monte l'haltère vers l'épaule sans décoller le coude du coussin.","Serre les biceps en haut du mouvement.","Redescends l'haltère lentement jusqu'à ce que le bras soit presque tendu.","Fais toutes les répétitions, puis change de bras."],"image_main":null,"image_start":"/exercises/one-arm-dumbbell-preacher-curl/start.webp","image_end":"/exercises/one-arm-dumbbell-preacher-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-one-arm-dumbbell-preacher-curl"],"attribution_required":true,"exportable":false},
{"id":"19035729-114a-5f31-81ce-c277bfb55613","key":"one-arm-dumbbell-push-press","name_fr":"Push press haltère à un bras","name_en":"One-Arm Dumbbell Push Press","aliases_fr":[],"aliases_en":["One-arm DB push press"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-press","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["anterior_deltoid"],"secondary_muscles":["gluteus_maximus","lateral_deltoid","obliques","quadriceps","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["push"],"instructions_fr":["Tiens-toi debout avec un haltère à une épaule, paume vers l'intérieur (prise neutre).","Pieds à largeur d'épaules, abdominaux gainés, bras libre écarté sur le côté pour l'équilibre.","Fléchis légèrement les genoux en gardant le torse vertical.","Étends les jambes de façon explosive et pousse l'haltère au-dessus de la tête en un seul mouvement.","Verrouille le bras en haut, puis redescends à l'épaule de façon contrôlée.","Fais toutes les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/one-arm-dumbbell-push-press/start.webp","image_end":"/exercises/one-arm-dumbbell-push-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-one-arm-dumbbell-push-press"],"attribution_required":true,"exportable":false},
{"id":"827ea1e1-4c48-52d2-a4ce-3e10daecd402","key":"one-arm-dumbbell-shoulder-press","name_fr":"Développé épaules haltère à un bras","name_en":"One Arm Dumbbell Shoulder Press","aliases_fr":[],"aliases_en":["Single-arm DB press"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-press","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["anterior_deltoid","triceps_brachii"],"secondary_muscles":["lateral_deltoid","obliques","serratus_anterior","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Tiens-toi debout, pieds à largeur de hanches, avec un haltère à une épaule, paume vers l'avant.","Gaine les abdominaux et garde le bras libre relâché le long du corps.","Pousse l'haltère à la verticale jusqu'à avoir le bras complètement tendu.","Marque une courte pause en haut, le haut du bras à côté de l'oreille.","Redescends l'haltère à l'épaule de façon contrôlée.","Fais toutes les répétitions avec un bras, puis change de côté."],"image_main":null,"image_start":"/exercises/one-arm-dumbbell-shoulder-press/start.webp","image_end":"/exercises/one-arm-dumbbell-shoulder-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-one-arm-dumbbell-shoulder-press"],"attribution_required":true,"exportable":false},
{"id":"9a556fe5-9132-52fb-86f8-25172d07d760","key":"one-arm-dumbbell-swing","name_fr":"Swing haltère à un bras","name_en":"One-Arm Dumbbell Swing","aliases_fr":[],"aliases_en":["One-arm DB swing"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"kettlebell-swing","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["gluteus_maximus","hamstrings"],"secondary_muscles":["erector_spinae","forearm_flexors","lateral_deltoid"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["full_body","ballistic"],"instructions_fr":["Tiens-toi debout, pieds à largeur d'épaules, un haltère au sol légèrement devant toi.","Pars des hanches en gardant le dos plat et attrape l'haltère d'une main.","Fais passer l'haltère vers l'arrière entre tes jambes, puis projette les hanches vers l'avant de façon explosive.","Envoie l'haltère à hauteur de poitrine, bras relâché et tendu.","Laisse l'haltère redescendre en repartant des hanches pendant la descente.","Répète pour le nombre de répétitions voulu de chaque côté, en gardant le contrôle."],"image_main":null,"image_start":"/exercises/one-arm-dumbbell-swing/start.webp","image_end":"/exercises/one-arm-dumbbell-swing/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-one-arm-dumbbell-swing"],"attribution_required":true,"exportable":false},
{"id":"bd463d54-1d2a-5165-83d9-cfdd4f1509f9","key":"one-arm-kettlebell-bicep-curl","name_fr":"Curl biceps kettlebell à un bras","name_en":"One Arm Kettlebell Bicep Curl","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["biceps_brachii"],"secondary_muscles":["brachialis","forearm_flexors"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Tiens-toi bien droit avec un kettlebell dans une main.","Garde le coude collé au corps.","Monte le kettlebell vers l'épaule en fléchissant le biceps.","Serre en haut du mouvement.","Redescends le kettlebell de façon contrôlée.","Fais toutes les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/one-arm-kettlebell-bicep-curl/start.webp","image_end":"/exercises/one-arm-kettlebell-bicep-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-one-arm-kettlebell-bicep-curl"],"attribution_required":true,"exportable":false},
{"id":"9a26aa61-9446-59f4-a2f6-2e5d490fd4b2","key":"one-arm-kettlebell-bottoms-up-press","name_fr":"Développé kettlebell bottoms-up à un bras","name_en":"One-Arm Kettlebell Bottoms-Up Press","aliases_fr":["Bottoms-up press"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-press","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["anterior_deltoid"],"secondary_muscles":["forearm_flexors","lateral_deltoid","serratus_anterior","triceps_brachii"],"difficulty":"advanced","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["push"],"instructions_fr":["Épaule un kettlebell léger en position rack, puis incline-le pour que la cloche pointe vers le haut et que la poignée soit dans la paume.","Serre fort la poignée, poignet parfaitement droit et vertical.","Gaine les abdominaux et pousse la cloche à la verticale sans la laisser basculer.","Verrouille le bras au-dessus de la tête, la cloche toujours bien droite.","Redescends lentement en position rack en gardant la cloche verticale pendant toute la descente.","Fais toutes les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/one-arm-kettlebell-bottoms-up-press/start.webp","image_end":"/exercises/one-arm-kettlebell-bottoms-up-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-one-arm-kettlebell-bottoms-up-press"],"attribution_required":true,"exportable":false},
{"id":"94ba195b-8a21-55de-96cc-d012162ac0b9","key":"one-arm-kettlebell-floor-glute-bridge-press","name_fr":"Pont fessier développé kettlebell à un bras","name_en":"One Arm Kettlebell Floor Glute Bridge Press","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"hip-thrust","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["gluteus_maximus","pectoralis_major"],"secondary_muscles":["anterior_deltoid","hamstrings","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Allonge-toi sur le dos, genoux fléchis et pieds à plat au sol.","Tiens un kettlebell d'une main, à hauteur de l'épaule.","Monte les hanches en pont fessier.","Pousse le kettlebell à la verticale vers le plafond.","Redescends le kettlebell et les hanches de façon contrôlée.","Fais toutes les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/one-arm-kettlebell-floor-glute-bridge-press/start.webp","image_end":"/exercises/one-arm-kettlebell-floor-glute-bridge-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-one-arm-kettlebell-floor-glute-bridge-press"],"attribution_required":true,"exportable":false},
{"id":"6b9d055b-b157-5939-a0c6-f112638a8691","key":"one-arm-kettlebell-floor-press","name_fr":"Floor press kettlebell à un bras","name_en":"One Arm Kettlebell Floor Press","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bench-press","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Allonge-toi à plat au sol, genoux fléchis.","Tiens un kettlebell à l'épaule avec une main.","Pousse le kettlebell à la verticale jusqu'à l'extension complète du bras.","Redescends le kettlebell jusqu'à ce que le haut du bras touche le sol.","Garde les abdominaux gainés tout au long de l'exercice.","Fais toutes les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/one-arm-kettlebell-floor-press/start.webp","image_end":"/exercises/one-arm-kettlebell-floor-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-one-arm-kettlebell-floor-press"],"attribution_required":true,"exportable":false},
{"id":"7a05a9f8-eeef-53c3-81dd-93f9b6889229","key":"one-arm-kettlebell-front-squat","name_fr":"Front squat kettlebell à un bras","name_en":"One Arm Kettlebell Front Squat","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"squat","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["erector_spinae","hamstrings","obliques"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Tiens un kettlebell en position rack sur une épaule.","Tiens-toi debout, pieds à largeur d'épaules.","Descends en fléchissant les genoux et les hanches.","Garde la poitrine haute et le buste droit tout au long du mouvement.","Pousse dans les talons pour te relever.","Fais toutes les répétitions d'un côté, puis change de côté."],"image_main":null,"image_start":"/exercises/one-arm-kettlebell-front-squat/start.webp","image_end":"/exercises/one-arm-kettlebell-front-squat/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-one-arm-kettlebell-front-squat"],"attribution_required":true,"exportable":false},
{"id":"20d22a11-65be-519f-8f7e-46848d4d2e75","key":"one-arm-kettlebell-push-press","name_fr":"Push press kettlebell à un bras","name_en":"One Arm Kettlebell Push Press","aliases_fr":[],"aliases_en":["One-arm KB push press"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-press","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["anterior_deltoid"],"secondary_muscles":["gluteus_maximus","quadriceps","trapezius","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Tiens un kettlebell en position rack à une épaule.","Tiens-toi debout, pieds à largeur d'épaules.","Fléchis légèrement les genoux.","Pousse de façon explosive avec les jambes et envoie le kettlebell au-dessus de la tête.","Verrouille le bras en haut.","Redescends le kettlebell à l'épaule de façon contrôlée.","Fais toutes les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/one-arm-kettlebell-push-press/start.webp","image_end":"/exercises/one-arm-kettlebell-push-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-one-arm-kettlebell-push-press"],"attribution_required":true,"exportable":false},
{"id":"02b7f8e2-aad4-5496-938b-39729724e9a6","key":"one-arm-kettlebell-row","name_fr":"Rowing kettlebell à un bras","name_en":"One Arm Kettlebell Row","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"row","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["latissimus_dorsi","rhomboids"],"secondary_muscles":["biceps_brachii","posterior_deltoid","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Pose une main et un genou sur un banc pour t'appuyer.","Tiens un kettlebell de l'autre main, bras tendu.","Tire le kettlebell vers ta hanche en emmenant le coude vers l'arrière.","Serre le dos en haut du mouvement.","Redescends le kettlebell de façon contrôlée.","Fais toutes les répétitions d'un côté, puis change de côté."],"image_main":null,"image_start":"/exercises/one-arm-kettlebell-row/start.webp","image_end":"/exercises/one-arm-kettlebell-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-one-arm-kettlebell-row"],"attribution_required":true,"exportable":false},
{"id":"1963ae33-56a5-524c-8525-ba30462426a5","key":"one-arm-kettlebell-shoulder-press","name_fr":"Développé épaules kettlebell à un bras","name_en":"One Arm Kettlebell Shoulder Press","aliases_fr":[],"aliases_en":["One-arm KB press"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-press","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["anterior_deltoid","lateral_deltoid"],"secondary_muscles":["obliques","trapezius","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Tiens un kettlebell en position rack à une épaule.","Tiens-toi droit, pieds à largeur de hanches.","Pousse le kettlebell à la verticale jusqu'à verrouiller le bras.","Garde les abdominaux contractés pendant tout le mouvement.","Redescends le kettlebell en position rack de façon contrôlée.","Fais toutes les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/one-arm-kettlebell-shoulder-press/start.webp","image_end":"/exercises/one-arm-kettlebell-shoulder-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-one-arm-kettlebell-shoulder-press"],"attribution_required":true,"exportable":false},
{"id":"5ea0b00d-460d-5ff2-97c9-3ee3f32577d1","key":"one-arm-kettlebell-swing","name_fr":"Kettlebell swing à un bras","name_en":"One Arm Kettlebell Swing","aliases_fr":["Swing à un bras"],"aliases_en":["One-arm KB swing"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"kettlebell-swing","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["gluteus_maximus","hamstrings"],"secondary_muscles":["anterior_deltoid","erector_spinae","obliques"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Tiens-toi debout, pieds à largeur d'épaules, un kettlebell au sol devant toi.","Pars des hanches et attrape le kettlebell d'une main.","Fais passer le kettlebell vers l'arrière entre tes jambes.","Projette les hanches vers l'avant pour envoyer le kettlebell à hauteur de poitrine.","Laisse la gravité ramener le kettlebell entre tes jambes.","Fais toutes les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/one-arm-kettlebell-swing/start.webp","image_end":"/exercises/one-arm-kettlebell-swing/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-one-arm-kettlebell-swing"],"attribution_required":true,"exportable":false},
{"id":"6263f842-61fb-5726-ae0c-681f507bd566","key":"one-arm-kettlebell-tricep-kickback","name_fr":"Kickback triceps kettlebell à un bras","name_en":"One-Arm Kettlebell Tricep Kickback","aliases_fr":["Extension triceps buste penché kettlebell"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"tricep-kickback","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["triceps_brachii"],"secondary_muscles":["posterior_deltoid"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["arms","push"],"instructions_fr":["Penche le buste vers l'avant en charnière de hanches, dos plat et genoux légèrement fléchis.","Tiens une kettlebell par la poignée dans une main, paume tournée vers le corps.","Colle le haut du bras contre ton flanc, parallèle au sol, l'avant-bras pend à la verticale.","Étends le coude vers l'arrière jusqu'à ce que le bras soit complètement tendu derrière toi, sans bouger le haut du bras.","Serre le triceps en fin de course, puis reviens en contrôlant à la position de départ.","Fais toutes les répétitions d'un côté, puis change de main."],"image_main":null,"image_start":"/exercises/one-arm-kettlebell-tricep-kickback/start.webp","image_end":"/exercises/one-arm-kettlebell-tricep-kickback/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-one-arm-kettlebell-tricep-kickback"],"attribution_required":true,"exportable":false},
{"id":"684f7ca3-a487-5eb3-be66-79d31af5bf24","key":"one-arm-landmine-press","name_fr":"Landmine press à un bras","name_en":"One-Arm Landmine Press","aliases_fr":["Développé landmine à un bras"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["barbell","landmine"],"primary_muscles":["anterior_deltoid","pectoralis_major"],"secondary_muscles":["obliques","serratus_anterior","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["shoulders","push"],"instructions_fr":["Cale une extrémité d'une barre dans un support landmine et charge l'extrémité libre.","Mets-toi à genoux sur un genou ou debout, et attrape l'extrémité de la barre à hauteur d'épaule d'une main.","Pousse la barre vers le haut et l'avant selon son arc jusqu'à avoir le bras complètement tendu.","Redescends la barre à hauteur d'épaule en contrôlant.","Fais toutes les répétitions avant de changer de côté."],"image_main":null,"image_start":"/exercises/one-arm-landmine-press/start.webp","image_end":"/exercises/one-arm-landmine-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-one-arm-landmine-press"],"attribution_required":true,"exportable":false},
{"id":"d39de4c0-6f61-573e-8ff6-1631c3fd0273","key":"one-arm-lat-pulldown","name_fr":"Tirage vertical à un bras","name_en":"One-Arm Lat Pulldown","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"lat-pulldown","variant_of":null,"equipment":["cable"],"primary_muscles":["latissimus_dorsi"],"secondary_muscles":["biceps_brachii","posterior_deltoid","rhomboids"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["pull","back"],"instructions_fr":["Fixe une poignée simple à la poulie haute et assieds-toi, cuisses bloquées sous le pad.","Lève le bras et attrape la poignée d'une main, bras complètement tendu.","Tire la poignée vers l'épaule en emmenant le coude vers la hanche.","Marque une courte pause à la contraction maximale, puis reviens à la position de départ de façon contrôlée.","Fais toutes les répétitions d'un côté avant de changer."],"image_main":null,"image_start":"/exercises/one-arm-lat-pulldown/start.webp","image_end":"/exercises/one-arm-lat-pulldown/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-one-arm-lat-pulldown"],"attribution_required":true,"exportable":false},
{"id":"ed5985d1-7ec1-50dd-a8e0-147981e93d86","key":"one-arm-seated-cable-row","name_fr":"Tirage horizontal à la poulie à un bras","name_en":"One-Arm Seated Cable Row","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"row","variant_of":null,"equipment":["cable"],"primary_muscles":["latissimus_dorsi","rhomboids"],"secondary_muscles":["biceps_brachii","posterior_deltoid","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["pull","back"],"instructions_fr":["Assieds-toi à la station de tirage horizontal et saisis une poignée, bras de travail tendu.","Cale les pieds, tiens-toi droit et gaine le tronc sans te pencher en arrière.","Tire la poignée vers le bas des côtes en ramenant l'omoplate vers l'arrière.","Marque une brève pause sans faire pivoter le buste ni hausser l'épaule.","Tends le bras de façon contrôlée, termine la série, puis répète de l'autre côté."],"image_main":null,"image_start":"/exercises/one-arm-seated-cable-row/start.webp","image_end":"/exercises/one-arm-seated-cable-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-one-arm-seated-cable-row"],"attribution_required":true,"exportable":false},
{"id":"e2ad36be-ceaf-5325-bbf9-878fa8edb617","key":"one-arm-single-leg-dumbbell-romanian-deadlift","name_fr":"Soulevé de terre roumain une jambe, un haltère","name_en":"One-Arm Single-Leg Dumbbell Romanian Deadlift","aliases_fr":["Soulevé de terre roumain unilatéral haltère"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"deadlift","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["gluteus_maximus","hamstrings"],"secondary_muscles":["erector_spinae","forearm_flexors","gluteus_medius","obliques"],"difficulty":"advanced","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["legs","core"],"instructions_fr":["Tiens-toi sur une jambe, un haltère dans la main opposée.","Bras libre écarté sur le côté pour l'équilibre, jambe libre juste au-dessus du sol.","Penche-toi en charnière sur la hanche d'appui en la poussant vers l'arrière, pendant que la jambe libre s'étend derrière toi pour contrebalancer.","Garde les hanches face au sol, sans les ouvrir sur le côté.","Descends l'haltère vers le pied de la jambe d'appui en sentant un fort étirement des ischio-jambiers.","Pousse la hanche vers l'avant pour te redresser sous contrôle.","Fais toutes les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/one-arm-single-leg-dumbbell-romanian-deadlift/start.webp","image_end":"/exercises/one-arm-single-leg-dumbbell-romanian-deadlift/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-one-arm-single-leg-dumbbell-romanian-deadlift"],"attribution_required":true,"exportable":false},
{"id":"a0424071-0d68-5a1b-ac04-fd7232834611","key":"one-arm-single-leg-kettlebell-romanian-deadlift","name_fr":"Soulevé de terre roumain une jambe, kettlebell","name_en":"One-Arm Single-Leg Kettlebell Romanian Deadlift","aliases_fr":["Soulevé de terre roumain unilatéral kettlebell"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"deadlift","variant_of":null,"equipment":["kettlebell"],"primary_muscles":["gluteus_maximus","hamstrings"],"secondary_muscles":["erector_spinae","forearm_flexors","gluteus_medius","obliques"],"difficulty":"advanced","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["legs","core"],"instructions_fr":["Tiens-toi sur une jambe, une kettlebell tenue par la poignée dans la main opposée.","Bras libre écarté sur le côté pour l'équilibre, jambe libre en suspension derrière toi.","Penche-toi en charnière sur la hanche d'appui en la poussant vers l'arrière, pendant que la jambe libre s'étend pour contrebalancer.","Garde les hanches face au sol ; la kettlebell descend droit le long du tibia.","Sens un fort étirement des ischio-jambiers de la jambe d'appui en bas.","Pousse la hanche vers l'avant pour te redresser.","Fais toutes les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/one-arm-single-leg-kettlebell-romanian-deadlift/start.webp","image_end":"/exercises/one-arm-single-leg-kettlebell-romanian-deadlift/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-one-arm-single-leg-kettlebell-romanian-deadlift"],"attribution_required":true,"exportable":false},
{"id":"d275d94e-df0a-5583-bab7-7043caa7421f","key":"overhead-squat","name_fr":"Overhead squat","name_en":"Overhead Squat","aliases_fr":["Squat bras tendus au-dessus de la tête"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"squat","variant_of":null,"equipment":["barbell"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["erector_spinae","lateral_deltoid","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Tiens une barre au-dessus de la tête en prise large d'arraché, bras verrouillés.","Tiens-toi debout, pieds un peu plus larges que les épaules.","Descends en poussant les hanches vers l'arrière et en fléchissant les genoux.","Garde la barre directement au-dessus du milieu des pieds.","Pousse dans les talons pour te relever.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/overhead-squat/start.webp","image_end":"/exercises/overhead-squat/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-overhead-squat"],"attribution_required":true,"exportable":false},
{"id":"8906d2b3-e4dd-500a-9674-099de9c9d9f1","key":"overhead-tricep-extension","name_fr":"Extension triceps nuque, un haltère","name_en":"Overhead Tricep Extension","aliases_fr":["Extension triceps haltère au-dessus de la tête"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-tricep-extension","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["triceps_brachii"],"secondary_muscles":[],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms"],"instructions_fr":["Tiens-toi debout ou assis, un haltère tenu à deux mains au-dessus de la tête.","Descends l'haltère derrière la tête en fléchissant les coudes.","Tends les bras pour revenir à la position de départ.","Garde les coudes près de la tête tout au long du mouvement.","Répète."],"image_main":null,"image_start":"/exercises/overhead-tricep-extension/start.webp","image_end":"/exercises/overhead-tricep-extension/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-overhead-tricep-extension"],"attribution_required":true,"exportable":false},
{"id":"b34fa2b2-2390-5047-8dad-707609c01351","key":"overhead-triceps-stretch","name_fr":"Étirement triceps au-dessus de la tête","name_en":"Overhead Triceps Stretch","aliases_fr":[],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["triceps_brachii"],"secondary_muscles":["latissimus_dorsi"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":["Lève un bras au-dessus de la tête et plie le coude.","Laisse ta main descendre derrière la tête.","Avec l'autre main, pousse le coude plié vers l'arrière.","Tiens la position 20 à 30 secondes en respirant calmement.","Change de côté et recommence."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-overhead-triceps-stretch"],"attribution_required":true,"exportable":false},
