{"id":"d1f45306-dca1-5019-8854-019784f36e4d","key":"pec-deck","name_fr":"Pec deck (butterfly)","name_en":"Pec Deck","aliases_fr":["Butterfly"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"chest-fly","variant_of":null,"equipment":["pec_deck"],"primary_muscles":["pectoralis_major"],"secondary_muscles":["anterior_deltoid","serratus_anterior"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Assieds-toi sur le pec deck et saisis les poignées, bras écartés sur les côtés, coudes légèrement fléchis.","Règle le siège pour que les poignées soient à hauteur du milieu de la poitrine.","Rapproche les poignées devant ta poitrine.","Marque une courte pause en contraction au centre.","Reviens à la position de départ sous contrôle.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/pec-deck/start.webp","image_end":"/exercises/pec-deck/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-pec-deck"],"attribution_required":true,"exportable":false},
{"id":"48d9e1e1-1b59-57f8-b0b5-032bd6d07c61","key":"pendlay-row","name_fr":"Rowing Pendlay","name_en":"Pendlay Row","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"row","variant_of":null,"equipment":["barbell"],"primary_muscles":["latissimus_dorsi","rhomboids","trapezius"],"secondary_muscles":["biceps_brachii","erector_spinae","posterior_deltoid"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Charge une barre et pose-la au sol.","Penche le buste en partant des hanches jusqu'à ce qu'il soit parallèle au sol, genoux légèrement fléchis.","Saisis la barre en pronation, un peu plus large que les épaules.","Tire la barre vers le bas de la poitrine de façon explosive.","Repose la barre au sol de façon contrôlée et marque une pause avant la répétition suivante.","Répète."],"image_main":null,"image_start":"/exercises/pendlay-row/start.webp","image_end":"/exercises/pendlay-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-pendlay-row"],"attribution_required":true,"exportable":false},
{"id":"7eb2e107-e5fd-559d-ad8a-d500c50f387b","key":"pigeon-hip-flow","name_fr":"Enchaînement pigeon","name_en":"Pigeon hip flow","aliases_fr":["Enchaînement pigeon de hanche"],"aliases_en":[],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":"148753c5-a543-523f-9184-7eefb11a492a","equipment":["mat"],"primary_muscles":[],"secondary_muscles":[],"difficulty":null,"metrics":["reps","duration_s"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":[],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"coory","source_ids":["coory-pigeon-hip-flow"],"attribution_required":false,"exportable":true},
{"id":"148753c5-a543-523f-9184-7eefb11a492a","key":"pigeon-stretch","name_fr":"Posture du pigeon","name_en":"Pigeon Stretch","aliases_fr":["Étirement du pigeon"],"aliases_en":["Pigeon pose"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus"],"secondary_muscles":["gluteus_medius","hip_flexors"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":["Depuis la position à quatre pattes, amène un genou vers l'avant et pose le tibia en travers devant toi.","Tends l'autre jambe droit derrière toi, dessus du pied au sol.","Descends les hanches vers le sol en les gardant bien face à l'avant.","Tiens la position 20 à 30 secondes en respirant calmement.","Change de côté et recommence."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-pigeon-stretch"],"attribution_required":true,"exportable":false},
{"id":"d2c56c0d-dc2a-52d3-b343-e2ad8bd39db3","key":"pike-push-ups","name_fr":"Pompes pike","name_en":"Pike Push Ups","aliases_fr":["Pike push-ups"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"push-up","variant_of":null,"equipment":[],"primary_muscles":["anterior_deltoid","lateral_deltoid"],"secondary_muscles":["trapezius","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Pars en chien tête en bas, hanches hautes et mains à largeur d'épaules.","Rapproche les pieds des mains.","Fléchis les coudes et descends la tête vers le sol.","Garde les hanches hautes pendant tout le mouvement.","Repousse jusqu'à l'extension complète des bras.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/pike-push-ups/start.webp","image_end":"/exercises/pike-push-ups/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-pike-push-ups"],"attribution_required":true,"exportable":false},
{"id":"343cf97f-5cdd-5474-b032-ca709e85afd0","key":"pilates-kneeling-side-kick","name_fr":"Pilates side kick à genoux","name_en":"Pilates Kneeling Side Kick","aliases_fr":["Coup de pied latéral à genoux"],"aliases_en":["Kneeling side kick"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["gluteus_medius","obliques"],"secondary_muscles":["abductors","gluteus_maximus"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":true,"bodyweight":true,"tags":["calisthenics"],"instructions_fr":["Mets-toi à genoux sur un genou et pose la main du même côté au sol sous l'épaule, l'autre main sur la hanche.","Étends la jambe du haut sur le côté, le pied un peu sous la hauteur de la hanche.","Tronc parfaitement immobile, monte la jambe à hauteur de la hanche.","Redescends-la en contrôlant, sans faire basculer le bassin ni cambrer le bas du dos.","Répète pour le nombre de répétitions voulu, puis change de côté."],"image_main":null,"image_start":"/exercises/pilates-kneeling-side-kick/start.webp","image_end":"/exercises/pilates-kneeling-side-kick/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-pilates-kneeling-side-kick"],"attribution_required":true,"exportable":false},
{"id":"a015d97f-1d1e-546f-ad13-077315dd98e2","key":"pilates-leg-pull-back","name_fr":"Pilates leg pull back","name_en":"Pilates Leg Pull Back","aliases_fr":["Leg pull back"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["erector_spinae","gluteus_maximus"],"secondary_muscles":["hamstrings","posterior_deltoid","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["core","calisthenics"],"instructions_fr":["Assieds-toi jambes tendues, mains au sol derrière les hanches, doigts vers l'avant.","Appuie dans les mains et les talons et monte les hanches en planche inversée.","Hanches droites et hautes, lève une jambe tendue aussi loin que le bassin reste immobile.","Redescends la jambe en contrôlant et recommence avec l'autre.","Termine la série et repose les hanches au sol."],"image_main":null,"image_start":"/exercises/pilates-leg-pull-back/start.webp","image_end":"/exercises/pilates-leg-pull-back/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-pilates-leg-pull-back"],"attribution_required":true,"exportable":false},
{"id":"6a5a8f64-1f76-53b1-a3c7-25e245954a22","key":"pilates-leg-pull-front","name_fr":"Pilates leg pull front","name_en":"Pilates Leg Pull Front","aliases_fr":["Leg pull front"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus","rectus_abdominis"],"secondary_muscles":["anterior_deltoid","erector_spinae","transverse_abdominis"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["core","calisthenics"],"instructions_fr":["Place-toi en planche haute, mains sous les épaules et corps bien aligné.","Gaine le tronc et contracte les fessiers pour que les hanches ne tournent pas.","Lève une jambe tendue de quelques centimètres au-dessus de la hauteur des hanches sans laisser le bassin basculer.","Redescends-la en contrôlant et recommence avec l'autre jambe.","Continue d'alterner pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/pilates-leg-pull-front/start.webp","image_end":"/exercises/pilates-leg-pull-front/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-pilates-leg-pull-front"],"attribution_required":true,"exportable":false},
{"id":"64b86495-8164-59df-a105-6a2ee60c6cdb","key":"pilates-roll-down","name_fr":"Roll down Pilates","name_en":"Pilates Roll Down","aliases_fr":[],"aliases_en":["Roll down"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["erector_spinae"],"secondary_muscles":["hamstrings","rectus_abdominis"],"difficulty":"beginner","metrics":["reps","duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Tiens-toi debout, pieds à largeur de hanches et bras le long du corps.","Rentre le menton sur la poitrine et commence à descendre vertèbre par vertèbre.","Laisse les bras et la tête pendre lourdement une fois la colonne complètement enroulée.","Remonte de la même façon, en empilant les vertèbres une à une, la tête en dernier.","Répète le nombre de répétitions voulu."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-pilates-roll-down"],"attribution_required":true,"exportable":false},
{"id":"b473284b-0a5d-5cb9-8316-713eaf307a08","key":"pilates-roll-over","name_fr":"Pilates roll over","name_en":"Pilates Roll Over","aliases_fr":["Roll over"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["rectus_abdominis","transverse_abdominis"],"secondary_muscles":["erector_spinae","hip_flexors"],"difficulty":"advanced","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["core","calisthenics"],"instructions_fr":["Allonge-toi sur le dos, jambes tendues et bras plaqués dans le tapis le long du corps.","Monte les deux jambes à la verticale sans cambrer le bas du dos.","Appuie les bras dans le sol et passe les jambes au-dessus de la tête jusqu'à ce qu'elles soient parallèles au sol derrière toi.","Écarte légèrement les jambes, mets les pieds en flexion et déroule la colonne vertèbre par vertèbre.","Ramène les jambes à la verticale et répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/pilates-roll-over/start.webp","image_end":"/exercises/pilates-roll-over/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-pilates-roll-over"],"attribution_required":true,"exportable":false},
{"id":"ba9e16d4-7458-584a-a755-6b374d52fa7f","key":"pilates-saw","name_fr":"Scie Pilates","name_en":"Pilates Saw","aliases_fr":["La scie"],"aliases_en":["Saw"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["erector_spinae","obliques"],"secondary_muscles":["adductors","hamstrings"],"difficulty":"intermediate","metrics":["reps","duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Assieds-toi bien droit, jambes tendues et un peu plus écartées que les hanches, bras écartés sur les côtés.","Fais pivoter le buste d'un côté en gardant les deux ischions au sol.","Penche-toi en avant au-dessus de cette jambe et tends la main opposée au-delà du petit orteil.","Remonte en déroulant la colonne et reviens au centre.","Répète de l'autre côté et continue d'alterner."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-pilates-saw"],"attribution_required":true,"exportable":false},
{"id":"81070385-f259-5aa6-9af7-0373ce82aa21","key":"pilates-side-bend","name_fr":"Pilates side bend","name_en":"Pilates Side Bend","aliases_fr":["Inclinaison latérale Pilates"],"aliases_en":["Pilates mermaid"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["gluteus_medius","obliques"],"secondary_muscles":["anterior_deltoid","transverse_abdominis"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":true,"bodyweight":true,"tags":["core","calisthenics"],"instructions_fr":["Assieds-toi sur une hanche, jambes fléchies sur le côté et main d'appui au sol sous l'épaule.","Appuie dans la main et la jambe du bas pour décoller les hanches du sol.","Tends le bras du haut au-dessus de la tête pour que le corps forme un long arc de la main aux pieds.","Redescends les hanches vers le tapis en contrôlant.","Termine les répétitions et change de côté."],"image_main":null,"image_start":"/exercises/pilates-side-bend/start.webp","image_end":"/exercises/pilates-side-bend/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-pilates-side-bend"],"attribution_required":true,"exportable":false},
{"id":"7ddcf5f5-da1d-5fc3-9c5f-553697e87d41","key":"pilates-spine-stretch-forward","name_fr":"Étirement colonne vers l'avant Pilates","name_en":"Pilates Spine Stretch Forward","aliases_fr":[],"aliases_en":["Spine stretch"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["erector_spinae","rectus_abdominis"],"secondary_muscles":["hamstrings","transverse_abdominis"],"difficulty":"intermediate","metrics":["reps","duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Assieds-toi bien droit, jambes tendues et un peu plus écartées que les hanches, pieds fléchis.","Tends les bras vers l'avant à hauteur d'épaules.","Rentre le menton et enroule la colonne vers l'avant vertèbre par vertèbre, en allant au-delà des orteils.","Reconstruis la colonne de la base vers le haut jusqu'à être de nouveau assis bien droit.","Répète le nombre de répétitions voulu."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-pilates-spine-stretch-forward"],"attribution_required":true,"exportable":false},
{"id":"01ac98c1-681b-52f3-ac44-afd993c7e006","key":"pilates-spine-twist","name_fr":"Rotation de colonne Pilates","name_en":"Pilates Spine Twist","aliases_fr":[],"aliases_en":["Spine twist"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["obliques"],"secondary_muscles":["erector_spinae","transverse_abdominis"],"difficulty":"intermediate","metrics":["reps","duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Assieds-toi bien droit, jambes tendues et jointes, pieds fléchis, bras écartés sur les côtés à hauteur d'épaules.","Grandis-toi dans la colonne et appuie les deux ischions dans le sol.","Tourne le buste d'un côté aussi loin que les hanches restent face à l'avant, puis reviens au centre.","Tourne de l'autre côté de la même façon.","Continue d'alterner pour le nombre de répétitions voulu."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-pilates-spine-twist"],"attribution_required":true,"exportable":false},
{"id":"1924da46-9657-59af-9bcd-58694b2875f1","key":"pistol-squat","name_fr":"Pistol squat","name_en":"Pistol Squat","aliases_fr":["Squat sur une jambe"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"squat","variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["gluteus_medius","hamstrings","hip_flexors"],"difficulty":"advanced","metrics":["reps","tempo"],"unilateral":true,"bodyweight":true,"tags":["legs","calisthenics"],"instructions_fr":["Tiens-toi sur une jambe, l'autre tendue devant toi, bras écartés pour l'équilibre.","Fléchis les hanches et le genou d'appui en gardant la poitrine haute.","Descends lentement jusqu'à ce que l'arrière de la cuisse touche le mollet.","Pousse dans le talon d'appui pour te relever.","Fais les répétitions d'un côté, puis change de jambe."],"image_main":null,"image_start":"/exercises/pistol-squat/start.webp","image_end":"/exercises/pistol-squat/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-pistol-squat"],"attribution_required":true,"exportable":false},
{"id":"66b29f9e-0e8c-5883-87fe-572a941423b0","key":"planche","name_fr":"Planche (gymnastique)","name_en":"Planche","aliases_fr":["Planche"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"static-hold","variant_of":null,"equipment":[],"primary_muscles":["anterior_deltoid","pectoralis_major"],"secondary_muscles":["serratus_anterior","triceps_brachii"],"difficulty":"advanced","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":["calisthenics"],"instructions_fr":["Commence en position de pompe, mains tournées vers l'extérieur au sol, ou sur des parallettes.","Penche-toi vers l'avant jusqu'à ce que ton centre de gravité soit au-dessus des mains.","Décolle les pieds du sol en gardant le corps horizontal.","Maintiens la position.","Reviens au sol en contrôlant."],"image_main":"/exercises/planche/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-planche"],"attribution_required":true,"exportable":false},
{"id":"b9c66726-3b9b-5311-8088-12bd60eb935c","key":"planche-lean-floor","name_fr":"Planche lean au sol","name_en":"Planche Lean","aliases_fr":["Planche lean"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"static-hold","variant_of":null,"equipment":[],"primary_muscles":["anterior_deltoid","pectoralis_major"],"secondary_muscles":["rectus_abdominis","serratus_anterior","triceps_brachii"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":["calisthenics","shoulder_stability"],"instructions_fr":["Place-toi en planche haute, mains au sol un peu en dessous des hanches et légèrement tournées vers l'extérieur.","Verrouille les coudes et écarte les omoplates pour que le haut du dos soit légèrement arrondi et solide.","Penche le corps vers l'avant jusqu'à ce que les épaules soient bien devant les mains.","Garde tout le corps aligné, fessiers serrés et abdominaux gainés.","Maintiens la position penchée pendant la durée prévue en respirant régulièrement.","Reviens en planche neutre pour terminer."],"image_main":"/exercises/planche-lean-floor/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-planche-lean-floor"],"attribution_required":true,"exportable":false},
{"id":"e1a8499d-6da3-5324-82e4-03562dbec1f8","key":"plank","name_fr":"Planche","name_en":"Plank","aliases_fr":["Gainage ventral"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"plank","variant_of":null,"equipment":[],"primary_muscles":["rectus_abdominis","transverse_abdominis"],"secondary_muscles":["erector_spinae"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":["core","calisthenics"],"instructions_fr":["Pose les avant-bras au sol, coudes sous les épaules.","Tends les jambes vers l'arrière et monte sur la pointe des pieds.","Garde le corps aligné de la tête aux talons.","Gaine les abdominaux et serre les fessiers.","Tiens la position pendant la durée voulue.","Pose les genoux au sol pour terminer."],"image_main":"/exercises/plank/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-plank"],"attribution_required":true,"exportable":false},
{"id":"5f3d1c7f-8ec9-5732-ac00-8f58829fc6ca","key":"plank-knee-tuck","name_fr":"Planche avec montée de genou","name_en":"Plank Knee Tuck","aliases_fr":["Plank knee tuck"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"plank","variant_of":null,"equipment":[],"primary_muscles":["hip_flexors","rectus_abdominis"],"secondary_muscles":["anterior_deltoid","obliques","serratus_anterior","transverse_abdominis"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["core","calisthenics"],"instructions_fr":["Mets-toi en planche haute, mains sous les épaules et corps aligné de la tête aux talons.","Repousse le sol et gaine le buste pour que les hanches ne s'affaissent ni ne montent.","Ramène un genou vers la poitrine sans laisser monter les hanches.","Tends la jambe en arrière pour revenir au départ en contrôlant.","Répète avec l'autre jambe et alterne pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/plank-knee-tuck/start.webp","image_end":"/exercises/plank-knee-tuck/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-plank-knee-tuck"],"attribution_required":true,"exportable":false},
{"id":"0e706769-487e-55ed-8d25-417e1e42bea0","key":"plate-loaded-donkey-calf-raise","name_fr":"Donkey calf raise à la machine","name_en":"Plate-Loaded Donkey Calf Raise","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"calf-raise","variant_of":null,"equipment":["donkey_calf_raise_machine"],"primary_muscles":["gastrocnemius"],"secondary_muscles":["soleus"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs","calves"],"instructions_fr":["Charge les disques sur les embouts et monte sur la plateforme, l'avant des pieds au bord et les talons dans le vide.","Penche-toi vers l'avant à partir des hanches, installe le coussin sur tes hanches, puis pose les avant-bras sur le support devant toi.","Garde les genoux tendus et le dos plat, le buste presque parallèle au sol.","Pousse sur l'avant des pieds et monte les talons le plus haut possible, avec une courte pause en haut.","Descends les talons sous la plateforme jusqu'à sentir un fort étirement des mollets, et répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/plate-loaded-donkey-calf-raise/start.webp","image_end":"/exercises/plate-loaded-donkey-calf-raise/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-plate-loaded-donkey-calf-raise"],"attribution_required":true,"exportable":false},
{"id":"c8dd6df8-95e6-5537-8fc4-fe1fb5d7109d","key":"plate-loaded-glute-drive","name_fr":"Hip thrust à la machine à disques","name_en":"Plate-Loaded Glute Drive","aliases_fr":["Glute drive"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"hip-thrust","variant_of":null,"equipment":["hip_thrust_machine"],"primary_muscles":["gluteus_maximus"],"secondary_muscles":["gluteus_medius","hamstrings","quadriceps"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs","glutes"],"instructions_fr":["Charge les disques de façon égale sur les manchons et installe-toi dans la machine, le haut du dos contre le pad et les pieds à plat sur la plateforme.","Amène le pad de hanches ou la barre sur tes hanches et règle-le pour qu'il repose sur le pli des hanches, pas sur le ventre.","Place tes pieds pour que tes tibias soient à peu près verticaux quand les hanches sont en haut, et attrape les poignées.","Monte les hanches en serrant les fessiers jusqu'à ce que tes cuisses soient dans l'alignement du torse, et marque une courte pause en haut.","Redescends de façon contrôlée jusqu'à juste avant le bas de l'amplitude, et répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/plate-loaded-glute-drive/start.webp","image_end":"/exercises/plate-loaded-glute-drive/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-plate-loaded-glute-drive"],"attribution_required":true,"exportable":false},
{"id":"cb75cccf-1edf-56f2-a31b-960eb71d60f2","key":"plate-loaded-lateral-raise","name_fr":"Élévations latérales à la machine à disques","name_en":"Plate-Loaded Lateral Raise","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"lateral-raise","variant_of":null,"equipment":["plate_loaded_lateral_raise_machine"],"primary_muscles":["lateral_deltoid"],"secondary_muscles":["anterior_deltoid","trapezius"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Règle la hauteur du siège pour que le pivot des pads de bras soit aligné avec le haut de tes épaules une fois assis.","Charge les disques de façon égale des deux côtés et assieds-toi, le dos à plat contre le pad.","Place l'extérieur de tes bras contre les pads, coudes fléchis et bras pendants.","Pousse vers l'extérieur et vers le haut contre les pads jusqu'à ce que tes bras soient à peu près à hauteur d'épaules.","Redescends de façon contrôlée jusqu'à ce que tes bras soient revenus le long du corps, et répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/plate-loaded-lateral-raise/start.webp","image_end":"/exercises/plate-loaded-lateral-raise/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-plate-loaded-lateral-raise"],"attribution_required":true,"exportable":false},
{"id":"63c5cc52-1c1f-5bde-9e1b-2efea76d75d9","key":"plate-loaded-seated-dip-machine","name_fr":"Dips assis à la machine à disques","name_en":"Plate-Loaded Seated Dip Machine","aliases_fr":["Machine à dips assis chargée"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"dips","variant_of":null,"equipment":["plate_loaded_dip_machine"],"primary_muscles":["triceps_brachii"],"secondary_muscles":["anterior_deltoid","pectoralis_major"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Charge les disques de façon égale sur les manchons et règle le siège pour que les poignées soient à peu près à hauteur d'épaules une fois assis.","Assieds-toi bien droit, dos contre le dossier, et saisis les poignées sur les côtés, coudes fléchis.","Garde les épaules basses et la poitrine haute, puis pousse les poignées vers le bas en tendant les coudes.","Contracte les triceps en bas, bras tendus mais sans verrouiller fort.","Laisse les poignées remonter sous contrôle jusqu'à ce que les coudes soient fléchis à environ 90 degrés.","Répète pour le nombre de répétitions prévu, puis ramène le levier sur sa butée de sécurité avant de te lever."],"image_main":null,"image_start":"/exercises/plate-loaded-seated-dip-machine/start.webp","image_end":"/exercises/plate-loaded-seated-dip-machine/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-plate-loaded-seated-dip-machine"],"attribution_required":true,"exportable":false},
{"id":"07ef78a7-0154-5862-9587-e077e34dab05","key":"plate-loaded-shrug","name_fr":"Shrugs à la machine chargée","name_en":"Plate-Loaded Shrug","aliases_fr":["Shrugs machine à disques"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"shrug","variant_of":null,"equipment":["shrug_machine"],"primary_muscles":["trapezius"],"secondary_muscles":["forearm_flexors"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Charge les disques de façon équilibrée sur les manchons et monte sur la plateforme de la machine, dos au cadre.","Saisis une poignée dans chaque main, bras pendant à la verticale le long du corps, épaules relâchées.","Tiens-toi droit, poitrine haute, menton à l'horizontale et genoux légèrement souples.","Hausse les épaules à la verticale vers les oreilles aussi haut que possible et marque une pause en haut.","Redescends de façon contrôlée jusqu'à avoir les épaules complètement basses, et répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/plate-loaded-shrug/start.webp","image_end":"/exercises/plate-loaded-shrug/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-plate-loaded-shrug"],"attribution_required":true,"exportable":false},
{"id":"f9fbe1f5-4fe4-58f7-8f7c-198c1f8a6cdc","key":"plate-pinch","name_fr":"Pince de disque","name_en":"Plate Pinch","aliases_fr":["Plate pinch"],"aliases_en":["Plate pinch hold"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["plates"],"primary_muscles":["forearm_flexors"],"secondary_muscles":["trapezius"],"difficulty":"intermediate","metrics":["duration_s","load_kg"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Pose un disque sur la tranche au sol.","Descends en squat et pince le disque par la tranche entre les doigts et le pouce d'une main : pas de poignées, juste la pince.","Redresse-toi et tiens le disque le long du corps pendant la durée prévue, bras tendu.","Repose-le au sol en contrôlant.","Recommence avec l'autre main."],"image_main":null,"image_start":"/exercises/plate-pinch/start.webp","image_end":"/exercises/plate-pinch/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-plate-pinch"],"attribution_required":true,"exportable":false},
{"id":"02451104-fa9b-51a8-9bdb-e11e6e343738","key":"plate-pullover","name_fr":"Pull-over disque","name_en":"Plate Pullover","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"pullover","variant_of":null,"equipment":["plates","bench"],"primary_muscles":["latissimus_dorsi","pectoralis_major"],"secondary_muscles":["serratus_anterior","triceps_brachii"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull","push"],"instructions_fr":["Allonge-toi sur un banc, un disque tenu à deux mains.","Pousse le disque au-dessus de la poitrine, bras presque tendus.","Redescends le disque en arc de cercle derrière la tête jusqu'à sentir un étirement.","Ramène le disque au-dessus de la poitrine sur le même arc.","Répète pour le nombre de répétitions prescrit."],"image_main":null,"image_start":"/exercises/plate-pullover/start.webp","image_end":"/exercises/plate-pullover/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-plate-pullover"],"attribution_required":true,"exportable":false},
{"id":"50b47032-6c81-5c2c-a003-e9216c200710","key":"plow-pose","name_fr":"Posture de la charrue","name_en":"Plow Pose","aliases_fr":["Halasana"],"aliases_en":["Halasana"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["erector_spinae","hamstrings"],"secondary_muscles":["gluteus_maximus","trapezius"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Allonge-toi sur le dos, bras le long du corps, paumes vers le bas.","Lève les deux jambes au-dessus de la tête et soutiens le bas du dos avec les mains.","Descends les orteils vers le sol derrière la tête, jambes aussi droites que le confort le permet.","Tiens la position le temps prévu, en respirant calmement et sans bouger la tête.","Redescends vertèbre par vertèbre, les mains soutenant le dos."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-plow-pose"],"attribution_required":true,"exportable":false},
{"id":"be52c5b5-9b9e-555b-a4ba-6c889300b331","key":"plyo-lunge","name_fr":"Fentes sautées","name_en":"Plyo Lunge","aliases_fr":["Fentes pliométriques"],"aliases_en":["Jump lunge"],"category":"cardio","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"lunge","variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["gluteus_medius","hamstrings"],"difficulty":"intermediate","metrics":["reps"],"unilateral":true,"bodyweight":true,"tags":["legs","conditioning","plyometrics"],"instructions_fr":["Pars en fente avant, un pied devant l'autre.","Descends en fente profonde, le genou arrière presque au sol.","Décolle les deux pieds du sol et change de jambe en l'air.","Réceptionne-toi en douceur en fente, avec la jambe opposée devant.","Continue d'alterner sans pause."],"image_main":null,"image_start":"/exercises/plyo-lunge/start.webp","image_end":"/exercises/plyo-lunge/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-plyo-lunge"],"attribution_required":true,"exportable":false},
{"id":"e833eed9-50a5-5a8d-ac12-fa9d4e78c31f","key":"plyo-push-up","name_fr":"Pompes pliométriques","name_en":"Plyo Push-Up","aliases_fr":["Plyo push-ups"],"aliases_en":[],"category":"cardio","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"push-up","variant_of":null,"equipment":[],"primary_muscles":["pectoralis_major","triceps_brachii"],"secondary_muscles":["anterior_deltoid"],"difficulty":"intermediate","metrics":["reps"],"unilateral":false,"bodyweight":true,"tags":["push","calisthenics","plyometrics"],"instructions_fr":["Mets-toi en position de pompe classique, mains à largeur d'épaules.","Descends en contrôlant jusqu'à ce que la poitrine frôle le sol.","Pousse de façon explosive pour décoller les mains du sol.","Réceptionne-toi en douceur, coudes légèrement fléchis.","Enchaîne sans pause pour le nombre de répétitions prescrit."],"image_main":null,"image_start":"/exercises/plyo-push-up/start.webp","image_end":"/exercises/plyo-push-up/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-plyo-push-up"],"attribution_required":true,"exportable":false},
