{"id":"cf8e9e82-cf93-5ea5-9487-87ef79efca27","key":"preacher-curl","name_fr":"Curl pupitre barre EZ","name_en":"Preacher Curl","aliases_fr":["Curl pupitre"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["ez_bar","bench"],"primary_muscles":["biceps_brachii"],"secondary_muscles":["brachialis"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms"],"instructions_fr":["Assieds-toi au pupitre, le haut des bras posé sur le coussin.","Tiens une barre EZ en supination.","Monte la barre vers les épaules.","Redescends de façon contrôlée jusqu'à avoir les bras presque tendus.","Répète."],"image_main":null,"image_start":"/exercises/preacher-curl/start.webp","image_end":"/exercises/preacher-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-preacher-curl"],"attribution_required":true,"exportable":false},
