{"id":"2cfcee3d-099b-5f99-af1c-6902495b464d","key":"pseudo-planche-push-ups","name_fr":"Pompes pseudo planche","name_en":"Pseudo Planche Push Ups","aliases_fr":["Pseudo planche push-ups"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"push-up","variant_of":null,"equipment":[],"primary_muscles":["anterior_deltoid","pectoralis_major"],"secondary_muscles":["serratus_anterior","triceps_brachii"],"difficulty":"advanced","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Mets-toi en position de pompe, mains tournées pour que les doigts pointent vers l'arrière.","Penche les épaules vers l'avant, au-delà des poignets.","Descends la poitrine vers le sol en fléchissant les coudes.","Garde le corps aligné.","Repousse en conservant l'inclinaison vers l'avant.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/pseudo-planche-push-ups/start.webp","image_end":"/exercises/pseudo-planche-push-ups/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-pseudo-planche-push-ups"],"attribution_required":true,"exportable":false},
{"id":"697cc21a-fced-58b5-bc1b-aff830ac525c","key":"pull-up","name_fr":"Tractions pronation","name_en":"Pull-Up","aliases_fr":["Pull-ups"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"pull-up","variant_of":null,"equipment":["pull_up_bar"],"primary_muscles":["latissimus_dorsi"],"secondary_muscles":["biceps_brachii","posterior_deltoid","rhomboids"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull","calisthenics"],"instructions_fr":["Suspends-toi à une barre en pronation, un peu plus large que les épaules.","Tire-toi jusqu'à ce que le menton passe au-dessus de la barre.","Redescends en contrôlant jusqu'à la suspension complète.","Répète."],"image_main":null,"image_start":"/exercises/pull-up/start.webp","image_end":"/exercises/pull-up/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-pull-up"],"attribution_required":true,"exportable":false},
{"id":"122159e0-6929-563f-9b2f-045b57d87817","key":"puppy-pose","name_fr":"Posture du chiot","name_en":"Puppy Pose","aliases_fr":["Uttana Shishosana"],"aliases_en":["Uttana Shishosana"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["latissimus_dorsi","posterior_deltoid"],"secondary_muscles":["erector_spinae","trapezius"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Mets-toi à quatre pattes, hanches au-dessus des genoux et mains sous les épaules.","Avance les mains et descends la poitrine vers le sol, en gardant les hanches hautes.","Pose le front ou le menton sur le tapis et laisse les aisselles s'abaisser.","Tiens la position le temps prévu, en respirant vers le haut du dos.","Recule les mains et assieds-toi sur les talons pour sortir de la posture."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-puppy-pose"],"attribution_required":true,"exportable":false},
{"id":"7bb7f006-4d6f-5528-83eb-6803d1695d7f","key":"push-jerk","name_fr":"Push jerk","name_en":"Push Jerk","aliases_fr":["Jeté en poussée"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"jerk","variant_of":null,"equipment":["barbell"],"primary_muscles":["anterior_deltoid","triceps_brachii"],"secondary_muscles":["gluteus_maximus","quadriceps","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg"],"unilateral":false,"bodyweight":false,"tags":["olympic_lifting"],"instructions_fr":["Tiens une barre en position rack avant, sur les épaules.","Mets-toi debout, pieds à largeur de hanches.","Fais une légère flexion en fléchissant un peu les genoux.","Pousse de façon explosive avec les jambes et envoie la barre au-dessus de la tête.","Descends en quart de squat sous la barre et verrouille les bras.","Remonte complètement et redescends la barre pour répéter."],"image_main":null,"image_start":"/exercises/push-jerk/start.webp","image_end":"/exercises/push-jerk/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-push-jerk"],"attribution_required":true,"exportable":false},
{"id":"509d5660-a592-5ecc-a3f9-335fc25983a0","key":"push-press","name_fr":"Push press","name_en":"Push Press","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-press","variant_of":null,"equipment":["barbell"],"primary_muscles":["anterior_deltoid","lateral_deltoid"],"secondary_muscles":["quadriceps","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Tiens-toi debout, la barre posée sur l'avant des épaules.","Fléchis légèrement les genoux.","Pousse fort avec les jambes et envoie la barre au-dessus de la tête.","Verrouille les bras en extension complète.","Redescends la barre en position de départ.","Répète."],"image_main":null,"image_start":"/exercises/push-press/start.webp","image_end":"/exercises/push-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-push-press"],"attribution_required":true,"exportable":false},
{"id":"ac8fdf09-9f76-5a8b-8bb8-3b04ce0ab9e9","key":"push-up","name_fr":"Pompes","name_en":"Push-Up","aliases_fr":["Push-ups"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"push-up","variant_of":null,"equipment":[],"primary_muscles":["pectoralis_major","triceps_brachii"],"secondary_muscles":["anterior_deltoid"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["push","calisthenics"],"instructions_fr":["Mets-toi en planche haute, mains à largeur d'épaules.","Descends le corps jusqu'à ce que la poitrine frôle le sol.","Repousse jusqu'à la position de départ.","Garde le corps aligné tout au long du mouvement.","Répète."],"image_main":null,"image_start":"/exercises/push-up/start.webp","image_end":"/exercises/push-up/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-push-up"],"attribution_required":true,"exportable":false},
{"id":"11c726a5-22e2-50a9-aedf-d777f2ad4e19","key":"pyramid-pose","name_fr":"Posture de la pyramide","name_en":"Pyramid Pose","aliases_fr":["Parsvottanasana"],"aliases_en":["Parsvottanasana"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["hamstrings"],"secondary_muscles":["erector_spinae","gastrocnemius"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":["Recule un pied d'environ une longueur de jambe et tourne légèrement le pied arrière vers l'extérieur.","Amène les deux pointes de hanches face à l'avant du tapis et garde les deux jambes tendues.","Penche-toi en pliant aux hanches au-dessus de la jambe avant, et amène les mains au sol, sur des blocs ou sur le tibia.","Tiens la flexion le temps prévu, la colonne longue plutôt qu'arrondie.","Pousse sur les pieds pour remonter et recommence de l'autre côté."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-pyramid-pose"],"attribution_required":true,"exportable":false},
