{"id":"fdcbfa40-1318-513d-8222-c184d27fe511","key":"rack-pull","name_fr":"Rack pull","name_en":"Rack Pull","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"deadlift","variant_of":null,"equipment":["barbell"],"primary_muscles":["erector_spinae","gluteus_maximus","hamstrings","trapezius"],"secondary_muscles":["forearm_flexors","forearms","latissimus_dorsi"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull","back"],"instructions_fr":["Règle les butées de sécurité d'un rack à hauteur de genoux et pose une barre chargée dessus.","Tiens-toi debout, pieds à largeur de hanches, et saisis la barre juste à l'extérieur des jambes.","Gaine les abdominaux, rapproche les omoplates et pousse avec les jambes pour soulever la barre.","Verrouille complètement hanches et genoux en haut.","Repose la barre sur les butées sous contrôle et replace-toi avant la répétition suivante."],"image_main":null,"image_start":"/exercises/rack-pull/start.webp","image_end":"/exercises/rack-pull/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-rack-pull"],"attribution_required":true,"exportable":false},
{"id":"2517eddf-1a5c-5c63-b5cb-af046278f1ce","key":"reclined-butterfly","name_fr":"Papillon allongé","name_en":"Reclined Butterfly","aliases_fr":["Supta Baddha Konasana"],"aliases_en":["Supta Baddha Konasana"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["adductors"],"secondary_muscles":["gluteus_maximus","hip_flexors"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Allonge-toi sur le dos, genoux pliés et plantes de pieds à plat au sol.","Joins les plantes des pieds et laisse les deux genoux s'ouvrir sur les côtés.","Pose les bras au sol, paumes vers le haut, ou place les mains sur le ventre.","Garde le bas du dos posé au sol et les épaules relâchées.","Respire lentement et laisse les genoux descendre vers le sol pendant le temps prévu.","Rapproche les genoux avec les mains pour terminer."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-reclined-butterfly"],"attribution_required":true,"exportable":false},
{"id":"26add281-ddd5-5752-b972-e2cecbebdce4","key":"renegade-row","name_fr":"Renegade row","name_en":"Renegade Row","aliases_fr":["Rowing en planche"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"row","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["latissimus_dorsi","rhomboids"],"secondary_muscles":["biceps_brachii","obliques","rectus_abdominis"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Place-toi en planche haute, une main sur chacun de deux haltères écartés à largeur d'épaules, les pieds écartés pour la stabilité.","Gaine le tronc pour que ton corps forme une ligne droite de la tête aux talons.","Tire un haltère vers la hanche en emmenant le coude le long des côtes.","Garde les hanches face au sol et ne laisse pas ton corps pivoter.","Repose l'haltère au sol de façon contrôlée.","Répète de l'autre côté et continue en alternant."],"image_main":null,"image_start":"/exercises/renegade-row/start.webp","image_end":"/exercises/renegade-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-renegade-row"],"attribution_required":true,"exportable":false},
{"id":"d13c470d-03a2-593d-9d59-7ada937a7dd8","key":"reverse-crunches","name_fr":"Reverse crunch","name_en":"Reverse Crunches","aliases_fr":["Crunch inversé"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"crunch","variant_of":null,"equipment":[],"primary_muscles":["rectus_abdominis"],"secondary_muscles":["hip_flexors","obliques","transverse_abdominis"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Allonge-toi sur le dos, bras le long du corps.","Lève les jambes, genoux fléchis à 90 degrés.","Décolle les hanches du sol en contractant le bas des abdominaux.","Amène les genoux vers la poitrine.","Redescends les hanches avec contrôle.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/reverse-crunches/start.webp","image_end":"/exercises/reverse-crunches/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-reverse-crunches"],"attribution_required":true,"exportable":false},
{"id":"27076dd3-44d8-54cb-9509-f1eb3e6df394","key":"reverse-curl","name_fr":"Curl inversé barre","name_en":"Reverse Curl","aliases_fr":["Curl prise pronation"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["barbell"],"primary_muscles":["brachialis","forearm_extensors"],"secondary_muscles":["biceps_brachii"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["arms"],"instructions_fr":["Tiens-toi debout avec une barre en pronation.","Monte la barre vers les épaules.","Redescends de façon contrôlée.","Répète."],"image_main":null,"image_start":"/exercises/reverse-curl/start.webp","image_end":"/exercises/reverse-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-reverse-curl"],"attribution_required":true,"exportable":false},
{"id":"bdaef8b3-9970-5e80-9fe4-56ddfcbf8100","key":"reverse-grip-bent-over-row","name_fr":"Rowing barre supination buste penché","name_en":"Reverse Grip Bent Over Row","aliases_fr":["Rowing barre prise supination"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"row","variant_of":null,"equipment":["barbell"],"primary_muscles":["latissimus_dorsi","rhomboids"],"secondary_muscles":["biceps_brachii","erector_spinae","trapezius"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Tiens-toi debout, pieds à largeur d'épaules, et saisis une barre en supination.","Penche le buste en avant en partant des hanches, genoux légèrement fléchis.","Laisse la barre pendre, bras tendus.","Tire la barre vers le bas des abdominaux en emmenant les coudes vers l'arrière.","Serre le dos en haut.","Redescends la barre de façon contrôlée.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/reverse-grip-bent-over-row/start.webp","image_end":"/exercises/reverse-grip-bent-over-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-reverse-grip-bent-over-row"],"attribution_required":true,"exportable":false},
{"id":"24212304-f60b-5ab1-a03a-e56bc029b62f","key":"reverse-grip-lat-pulldown","name_fr":"Tirage vertical supination","name_en":"Reverse Grip Lat Pulldown","aliases_fr":["Tirage vertical prise inversée"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"pull-up","variant_of":null,"equipment":["cable"],"primary_muscles":["biceps_brachii","latissimus_dorsi"],"secondary_muscles":["posterior_deltoid","rhomboids"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Fixe une barre droite à la machine de tirage vertical.","Prends la barre en supination, à largeur d'épaules.","Assieds-toi et cale tes cuisses sous le coussin.","Tire la barre vers le haut de la poitrine.","Contracte les dorsaux et les biceps en bas.","Remonte la barre en position de départ en contrôlant.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/reverse-grip-lat-pulldown/start.webp","image_end":"/exercises/reverse-grip-lat-pulldown/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-reverse-grip-lat-pulldown"],"attribution_required":true,"exportable":false},
{"id":"7278482e-423a-5dfe-8b23-597412cf829a","key":"reverse-lunge","name_fr":"Fentes arrière haltères","name_en":"Reverse Lunge","aliases_fr":[],"aliases_en":["DB reverse lunge"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"lunge","variant_of":null,"equipment":["dumbbell"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["hamstrings"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["legs"],"instructions_fr":["Tiens-toi debout avec des haltères le long du corps.","Recule une jambe et descends le genou vers le sol.","Descends jusqu'à ce que la cuisse avant soit parallèle au sol.","Pousse dans le talon avant pour revenir debout.","Répète des deux côtés."],"image_main":null,"image_start":"/exercises/reverse-lunge/start.webp","image_end":"/exercises/reverse-lunge/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-reverse-lunge"],"attribution_required":true,"exportable":false},
{"id":"de1898a6-f91e-56ef-b048-69d1b8584de1","key":"reverse-nordic-curl","name_fr":"Reverse nordic","name_en":"Reverse Nordic Curl","aliases_fr":["Nordic inversé"],"aliases_en":["Reverse nordic"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"leg-extension","variant_of":null,"equipment":[],"primary_muscles":["quadriceps"],"secondary_muscles":["hip_flexors","rectus_abdominis"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Mets-toi à genoux sur un pad, genoux à largeur de hanches, tibias et dessus des pieds au sol, torse droit.","Garde les hanches étendues et les abdominaux gainés.","Penche lentement le torse vers l'arrière en gardant le corps en ligne droite.","Descends aussi loin que tu peux contrôler avec les quadriceps.","Remonte pour revenir à la position de départ.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/reverse-nordic-curl/start.webp","image_end":"/exercises/reverse-nordic-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-reverse-nordic-curl"],"attribution_required":true,"exportable":false},
{"id":"f0adacd4-ab51-5e68-a863-d78c038ad1ed","key":"reverse-plank","name_fr":"Planche inversée","name_en":"Reverse Plank","aliases_fr":["Reverse plank"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"plank","variant_of":null,"equipment":[],"primary_muscles":["erector_spinae","gluteus_maximus"],"secondary_muscles":["hamstrings","posterior_deltoid","triceps_brachii"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Assieds-toi au sol, jambes tendues devant toi.","Place les mains derrière toi, doigts dirigés vers les pieds.","Soulève les hanches du sol pour former une ligne droite de la tête aux talons.","Serre les fessiers et gaine les abdominaux.","Tiens la position pendant la durée voulue.","Redescends les hanches en contrôlant pour terminer."],"image_main":"/exercises/reverse-plank/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-reverse-plank"],"attribution_required":true,"exportable":false},
{"id":"2444f9e5-f2ba-5669-9af6-615290cd4a3f","key":"reverse-plank-dips","name_fr":"Dips en planche inversée","name_en":"Reverse Plank Dips","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"plank","variant_of":null,"equipment":[],"primary_muscles":["triceps_brachii"],"secondary_muscles":["erector_spinae","gluteus_maximus","posterior_deltoid"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["calisthenics"],"instructions_fr":["Assieds-toi jambes tendues, mains au sol derrière les hanches, doigts dirigés vers l'avant.","Appuie dans les mains et les talons et soulève les hanches en planche inversée jambes tendues.","Fléchis les coudes droit vers l'arrière et descends les hanches un peu vers le sol.","Repousse jusqu'à verrouiller les bras, en gardant les hanches hautes.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/reverse-plank-dips/start.webp","image_end":"/exercises/reverse-plank-dips/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-reverse-plank-dips"],"attribution_required":true,"exportable":false},
{"id":"829d38a5-6ce5-5a1d-a54b-61b88b73f1c5","key":"reverse-tabletop-hip-pulses","name_fr":"Pulses de hanches en table inversée","name_en":"Reverse Tabletop Hip Pulses","aliases_fr":["Pont inversé pulses"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"plank","variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus"],"secondary_muscles":["erector_spinae","hamstrings"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["calisthenics"],"instructions_fr":["Assieds-toi genoux fléchis, pieds à plat et mains au sol derrière toi.","Appuie dans les mains et les pieds et soulève les hanches jusqu'à ce que le buste soit au niveau des genoux.","Bras tendus, descends les hanches de quelques centimètres.","Serre les fessiers pour les remonter au niveau.","Enchaîne les pulses pour le nombre de répétitions voulu, puis redescends."],"image_main":null,"image_start":"/exercises/reverse-tabletop-hip-pulses/start.webp","image_end":"/exercises/reverse-tabletop-hip-pulses/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-reverse-tabletop-hip-pulses"],"attribution_required":true,"exportable":false},
{"id":"4bff354e-b775-59b0-8447-7fda5f989364","key":"reverse-tabletop-hold","name_fr":"Table inversée (maintien)","name_en":"Reverse Tabletop Hold","aliases_fr":["Reverse tabletop"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"plank","variant_of":null,"equipment":[],"primary_muscles":["erector_spinae","gluteus_maximus"],"secondary_muscles":["hamstrings","posterior_deltoid","triceps_brachii"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":["core","calisthenics"],"instructions_fr":["Assieds-toi genoux fléchis, pieds à plat et mains au sol derrière toi, doigts dirigés vers les talons.","Appuie dans les mains et les pieds et soulève les hanches jusqu'à ce que le buste soit au niveau des genoux.","Ouvre la poitrine, éloigne les épaules des oreilles et regarde droit devant toi.","Tiens la position pendant le temps prescrit, hanches hautes.","Redescends les hanches en contrôlant pour terminer."],"image_main":"/exercises/reverse-tabletop-hold/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-reverse-tabletop-hold"],"attribution_required":true,"exportable":false},
{"id":"0b0e228c-bb4a-5a21-8dcf-6dd016864005","key":"revolved-chair-pose","name_fr":"Posture de la chaise tournée","name_en":"Revolved Chair Pose","aliases_fr":["Revolved chair pose","Parivrtta Utkatasana"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["obliques","quadriceps"],"secondary_muscles":["erector_spinae","gluteus_maximus"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":["core","calisthenics"],"instructions_fr":["Place-toi en posture de la chaise, genoux fléchis, hanches en arrière et paumes jointes devant la poitrine.","Garde les genoux à la même hauteur pour que les hanches ne s'ouvrent pas dans la torsion.","Tourne la poitrine d'un côté et accroche le coude opposé à l'extérieur de cette cuisse.","Presse les paumes l'une contre l'autre et tiens la posture pendant la durée prévue, en allongeant la colonne à chaque inspiration.","Reviens au centre et recommence de l'autre côté."],"image_main":"/exercises/revolved-chair-pose/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-revolved-chair-pose"],"attribution_required":true,"exportable":false},
{"id":"e5e773ef-694b-5403-afe9-f821513e53fb","key":"revolved-crescent-lunge","name_fr":"Fente croissant tournée","name_en":"Revolved Crescent Lunge","aliases_fr":["Revolved crescent lunge","Parivrtta Anjaneyasana"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["obliques","quadriceps"],"secondary_muscles":["erector_spinae","hip_flexors"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":["core","calisthenics"],"instructions_fr":["Place-toi en fente haute, genou avant au-dessus de la cheville et talon arrière levé.","Joins les paumes devant la poitrine et ramène les deux hanches vers l'avant du tapis.","Tourne la poitrine vers la jambe avant et accroche le coude opposé à l'extérieur de la cuisse.","Tiens la torsion pendant la durée prévue, en poussant le talon arrière vers le mur derrière toi.","Défais la torsion et recommence de l'autre côté."],"image_main":"/exercises/revolved-crescent-lunge/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-revolved-crescent-lunge"],"attribution_required":true,"exportable":false},
{"id":"19a6dd45-3e33-5d49-aa1a-967d4d30e62b","key":"ring-dead-hang","name_fr":"Suspension aux anneaux","name_en":"Ring Dead Hang","aliases_fr":["Dead hang aux anneaux"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"static-hold","variant_of":null,"equipment":["rings"],"primary_muscles":["forearm_flexors"],"secondary_muscles":["latissimus_dorsi","rectus_abdominis","trapezius"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Attrape deux anneaux de gymnastique en prise neutre, paumes face à face.","Suspends-toi bras complètement tendus et pieds décollés du sol.","Laisse les anneaux tourner naturellement, sans lutter contre la prise.","Garde les épaules actives (sans les hausser vers les oreilles) et les abdominaux légèrement gainés.","Tiens pendant la durée voulue."],"image_main":"/exercises/ring-dead-hang/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-ring-dead-hang"],"attribution_required":true,"exportable":false},
{"id":"bc8106bd-0f48-5501-bb31-e7ec13b99c33","key":"ring-dips","name_fr":"Dips aux anneaux","name_en":"Ring Dips","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"dips","variant_of":null,"equipment":["rings"],"primary_muscles":["pectoralis_major","triceps_brachii"],"secondary_muscles":["anterior_deltoid"],"difficulty":"advanced","metrics":["reps","tempo"],"unilateral":false,"bodyweight":false,"tags":["calisthenics"],"instructions_fr":["Place-toi en appui sur les anneaux, bras verrouillés.","Descends en fléchissant les coudes jusqu'à ce que les bras soient parallèles au sol.","Remonte à la position de départ.","Répète."],"image_main":null,"image_start":"/exercises/ring-dips/start.webp","image_end":"/exercises/ring-dips/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-ring-dips"],"attribution_required":true,"exportable":false},
{"id":"0c8c3c22-da20-5688-9063-c551d5ee52c0","key":"ring-face-pull","name_fr":"Face pull aux anneaux","name_en":"Ring Face Pull","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"reverse-fly","variant_of":null,"equipment":["rings"],"primary_muscles":["posterior_deltoid","rhomboids"],"secondary_muscles":["trapezius"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull"],"instructions_fr":["Saisis les anneaux et penche-toi en arrière pour que ton corps soit incliné.","Tire les anneaux vers ton visage en écartant les coudes sur les côtés.","Marque une brève pause, puis reviens.","Répète."],"image_main":null,"image_start":"/exercises/ring-face-pull/start.webp","image_end":"/exercises/ring-face-pull/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-ring-face-pull"],"attribution_required":true,"exportable":false},
{"id":"6c7a41f0-9830-5c10-8439-e645761bc066","key":"ring-l-sit","name_fr":"L-sit aux anneaux","name_en":"Ring L-Sit","aliases_fr":["Ring L-sit"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"static-hold","variant_of":null,"equipment":["rings"],"primary_muscles":["hip_flexors","rectus_abdominis"],"secondary_muscles":["anterior_deltoid","latissimus_dorsi","quadriceps","triceps_brachii"],"difficulty":"advanced","metrics":["duration_s"],"unilateral":false,"bodyweight":false,"tags":["core","calisthenics"],"instructions_fr":["Règle les anneaux à peu près à hauteur de hanches et attrape-les, bras tendus le long du corps.","Pousse sur les anneaux et soulève le corps en position d'appui, épaules abaissées et éloignées des oreilles.","Tourne légèrement les anneaux vers l'extérieur, gaine les abdominaux et lève les jambes tendues jusqu'à ce qu'elles soient parallèles au sol.","Maintiens la position, anneaux stables et genoux verrouillés.","Redescends les jambes, puis le corps, en contrôlant."],"image_main":"/exercises/ring-l-sit/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-ring-l-sit"],"attribution_required":true,"exportable":false},
{"id":"526d6211-62e9-5e26-b3c5-c00391c4d9d4","key":"ring-muscle-up","name_fr":"Muscle-up aux anneaux","name_en":"Ring Muscle-Up","aliases_fr":["Ring muscle-up"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"pull-up","variant_of":null,"equipment":["rings"],"primary_muscles":["latissimus_dorsi","pectoralis_major","triceps_brachii"],"secondary_muscles":["anterior_deltoid","biceps_brachii","rhomboids"],"difficulty":"advanced","metrics":["reps","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull","calisthenics"],"instructions_fr":["Suspends-toi aux anneaux en false grip, paumes face à face.","Tire de façon explosive en amenant la poitrine vers les anneaux.","Passe les coudes au-dessus des anneaux pendant que la poitrine monte.","Pousse jusqu'à l'extension complète des bras en haut.","Redescends en contrôlant à travers la transition jusqu'à la suspension."],"image_main":null,"image_start":"/exercises/ring-muscle-up/start.webp","image_end":"/exercises/ring-muscle-up/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-ring-muscle-up"],"attribution_required":true,"exportable":false},
{"id":"59062be0-f13e-5dcf-9ac2-9dba5c1d43bc","key":"ring-plank","name_fr":"Planche aux anneaux","name_en":"Ring Plank","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"plank","variant_of":null,"equipment":["rings"],"primary_muscles":["rectus_abdominis","transverse_abdominis"],"secondary_muscles":["anterior_deltoid","obliques","pectoralis_major","serratus_anterior"],"difficulty":"advanced","metrics":["duration_s"],"unilateral":false,"bodyweight":false,"tags":["core","calisthenics"],"instructions_fr":["Règle les anneaux à hauteur de genoux et saisis-les, bras tendus sous les épaules.","Recule les pieds en planche, corps aligné de la tête aux talons.","Gaine les abdominaux et les fessiers et repousse les anneaux vers le bas et légèrement vers l'extérieur pour les garder stables.","Tiens la position sans laisser les hanches s'affaisser ni les anneaux s'écarter.","Rapproche les pieds et relève-toi pour terminer."],"image_main":"/exercises/ring-plank/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-ring-plank"],"attribution_required":true,"exportable":false},
{"id":"0ce7b914-f667-50d5-a55f-eebffbf78194","key":"ring-push-up","name_fr":"Pompes aux anneaux","name_en":"Ring Push-Up","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"push-up","variant_of":null,"equipment":["rings"],"primary_muscles":["pectoralis_major","triceps_brachii"],"secondary_muscles":["anterior_deltoid","serratus_anterior"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":false,"tags":["push","calisthenics"],"instructions_fr":["Règle les anneaux juste au-dessus du sol.","Saisis les anneaux et prends la position de planche, bras tendus.","Descends la poitrine vers les anneaux en gardant les coudes près du corps.","Repousse jusqu'à l'extension complète des bras.","Répète pour le nombre de répétitions prescrit."],"image_main":null,"image_start":"/exercises/ring-push-up/start.webp","image_end":"/exercises/ring-push-up/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-ring-push-up"],"attribution_required":true,"exportable":false},
{"id":"4ae4ce92-170b-5b7b-adb1-485691e19c0a","key":"ring-row","name_fr":"Rowing aux anneaux","name_en":"Ring Row","aliases_fr":["Tractions australiennes aux anneaux"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"row","variant_of":null,"equipment":["rings"],"primary_muscles":["latissimus_dorsi","rhomboids"],"secondary_muscles":["biceps_brachii","posterior_deltoid","trapezius"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull","calisthenics"],"instructions_fr":["Règle les anneaux entre la hauteur des hanches et celle de la poitrine.","Saisis les anneaux, paumes face à face, et penche-toi en arrière en biais, bras tendus.","Gaine les abdominaux et tire la poitrine vers les anneaux.","Serre les omoplates l'une vers l'autre en haut.","Redescends de façon contrôlée jusqu'à avoir les bras complètement tendus."],"image_main":null,"image_start":"/exercises/ring-row/start.webp","image_end":"/exercises/ring-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-ring-row"],"attribution_required":true,"exportable":false},
{"id":"724c45e1-3cbe-5933-affc-4353c3a8a96d","key":"ring-support-hold","name_fr":"Appui aux anneaux","name_en":"Ring Support Hold","aliases_fr":["Ring support hold"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"static-hold","variant_of":null,"equipment":["rings"],"primary_muscles":["pectoralis_major","triceps_brachii"],"secondary_muscles":["anterior_deltoid","latissimus_dorsi","serratus_anterior"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":false,"bodyweight":false,"tags":["calisthenics","shoulder_stability"],"instructions_fr":["Place les anneaux à peu près à hauteur de hanches et prends un anneau dans chaque main, pouces autour de l'anneau.","Pousse vers le haut jusqu'à avoir les bras tendus et le corps soulevé du sol au-dessus des anneaux.","Tourne légèrement les paumes vers l'extérieur pour que les anneaux soient à côté des hanches, coudes verrouillés.","Pousse sur les anneaux et garde les épaules loin des oreilles, poitrine haute.","Serre les fessiers et garde les jambes serrées, pieds pointés.","Maintiens la position pendant la durée prévue, puis redescends en contrôlant."],"image_main":"/exercises/ring-support-hold/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-ring-support-hold"],"attribution_required":true,"exportable":false},
{"id":"51255716-e233-53aa-801e-91ca92960b63","key":"rings-inverted-row","name_fr":"Rowing inversé aux anneaux","name_en":"Rings Inverted Row","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"row","variant_of":null,"equipment":["rings"],"primary_muscles":["latissimus_dorsi","rhomboids","trapezius"],"secondary_muscles":["biceps_brachii","forearm_flexors","posterior_deltoid","rectus_abdominis"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":false,"tags":["pull","calisthenics"],"instructions_fr":["Règle les anneaux juste au-dessus de la hauteur des hanches.","Allonge-toi sous les anneaux et saisis-les, paumes face à face.","Avance les pieds pour que ton corps forme une ligne droite.","Tire la poitrine vers les anneaux en serrant les omoplates.","Redescends de façon contrôlée jusqu'à avoir les bras complètement tendus."],"image_main":null,"image_start":"/exercises/rings-inverted-row/start.webp","image_end":"/exercises/rings-inverted-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-rings-inverted-row"],"attribution_required":true,"exportable":false},
{"id":"346bba7e-0695-5ced-8786-bebce6b5c95a","key":"romanian-deadlift","name_fr":"Soulevé de terre roumain","name_en":"Romanian Deadlift","aliases_fr":["SDT roumain"],"aliases_en":["RDL"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"deadlift","variant_of":null,"equipment":["barbell"],"primary_muscles":["gluteus_maximus","hamstrings"],"secondary_muscles":["erector_spinae"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs"],"instructions_fr":["Tiens-toi debout, barre tenue à hauteur des hanches, en pronation.","Penche-toi en charnière de hanches en les poussant vers l'arrière, jambes presque tendues.","Descends la barre le long des jambes jusqu'à sentir un étirement des ischio-jambiers.","Pousse les hanches vers l'avant pour te redresser.","Répète."],"image_main":null,"image_start":"/exercises/romanian-deadlift/start.webp","image_end":"/exercises/romanian-deadlift/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-romanian-deadlift"],"attribution_required":true,"exportable":false},
{"id":"b07e574a-1164-5f6f-9202-f888870fe5e8","key":"rope-climb","name_fr":"Grimper de corde","name_en":"Rope Climb","aliases_fr":["Montée à la corde"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["climbing_rope"],"primary_muscles":["latissimus_dorsi"],"secondary_muscles":["biceps_brachii","forearm_flexors","rectus_abdominis"],"difficulty":"advanced","metrics":["reps","tempo"],"unilateral":false,"bodyweight":false,"tags":["calisthenics"],"instructions_fr":["Attrape la corde le plus haut possible à deux mains.","Enroule la corde autour d'un pied (S-hook ou J-hook) ou pince-la entre les deux pieds.","Tire avec les bras et monte les genoux, puis serre la corde avec les pieds et redresse-toi sur le verrou des pieds.","Attrape plus haut avec une main, puis l'autre, relâche les pieds et serre à nouveau la corde plus haut.","Répète jusqu'à atteindre le haut de la corde.","Redescends main sous main en contrôlant la vitesse avec les pieds : ne te laisse jamais glisser."],"image_main":"/exercises/rope-climb/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-rope-climb"],"attribution_required":true,"exportable":false},
{"id":"54ea1af0-9baa-5df6-8edb-f486a9861605","key":"rowing-machine","name_fr":"Rameur","name_en":"Rowing Machine","aliases_fr":["RowErg","Aviron en salle","Rowing machine"],"aliases_en":[],"category":"hyrox","visibility":"active","disciplines":["cardio","hyrox"],"hyrox_station":5,"family":null,"variant_of":null,"equipment":["rower"],"primary_muscles":["latissimus_dorsi","quadriceps"],"secondary_muscles":["biceps_brachii","erector_spinae","gluteus_maximus","hamstrings","rhomboids","trapezius"],"difficulty":"beginner","metrics":["distance_m","duration_s","calories_kcal","pace_s_per_500m"],"unilateral":false,"bodyweight":false,"tags":["full_body","conditioning"],"instructions_fr":["Assieds-toi sur le rameur, sangle les pieds dans les cale-pieds et prends la poignée en pronation.","Glisse vers l'avant jusqu'à la position d'attaque : tibias verticaux, buste légèrement penché devant les hanches, bras tendus vers le volant.","Pousse d'abord avec les jambes, en repoussant le siège vers l'arrière jusqu'à ce que les genoux soient presque tendus.","Bascule le buste en arrière au-delà de la verticale, puis tire la poignée vers le bas des côtes, coudes passant le long du corps.","Inverse l'ordre au retour : bras d'abord, buste vers l'avant, puis fléchis les genoux, et glisse jusqu'à l'attaque pour le coup suivant.","Continue pendant la durée, la distance ou le nombre de coups voulu."],"image_main":"/exercises/rowing-machine/main.webp","image_start":null,"image_end":null,"image_source":"coory","source":"repdb","source_ids":["repdb-rowing-machine"],"attribution_required":true,"exportable":false},
{"id":"6b29ea26-9521-560e-bc49-a9845abf1e14","key":"running","name_fr":"Course à pied","name_en":"Running","aliases_fr":["Running"],"aliases_en":[],"category":"cardio","visibility":"hidden","disciplines":["cardio","running","hyrox"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["gastrocnemius","quadriceps"],"secondary_muscles":["gluteus_maximus","hamstrings","hip_flexors","soleus"],"difficulty":"beginner","metrics":["distance_m","duration_s","pace_s_per_km"],"unilateral":false,"bodyweight":true,"tags":["full_body","conditioning"],"instructions_fr":["Commence par un petit footing et monte progressivement vers ton allure pendant les premières minutes, au lieu de partir à la vitesse visée.","Pose le pied sous les hanches, pas devant toi, et garde un contact au sol court et silencieux.","Cours grand par les hanches avec une légère inclinaison vers l'avant depuis les chevilles, sans te plier à la taille.","Fléchis les coudes à environ 90 degrés et balance les bras d'avant en arrière, sans les croiser sur la poitrine.","Respire de façon rythmée et garde les épaules, la mâchoire et les mains relâchées.","Tiens l'allure pendant la durée ou la distance voulue, puis trottine et marche quelques minutes pour terminer."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-running"],"attribution_required":true,"exportable":false},
{"id":"72d6a9ab-dae0-549f-9a1a-85b134137f89","key":"russian-twist","name_fr":"Russian twist","name_en":"Russian Twist","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"crunch","variant_of":null,"equipment":[],"primary_muscles":["obliques","rectus_abdominis"],"secondary_muscles":["hip_flexors"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":["core"],"instructions_fr":["Assieds-toi au sol, genoux fléchis, penche-toi légèrement en arrière.","Joins les mains ou tiens une charge à hauteur de poitrine.","Pivote le buste d'un côté, puis de l'autre.","Garde les abdominaux gainés tout au long du mouvement.","Répète."],"image_main":null,"image_start":"/exercises/russian-twist/start.webp","image_end":"/exercises/russian-twist/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-russian-twist"],"attribution_required":true,"exportable":false},
{"id":"5d020515-e33a-518a-ac37-8c4ba751d9d9","key":"sandbag-carry","name_fr":"Sandbag carry","name_en":"Sandbag Carry","aliases_fr":["Marche avec sac de sable","Portage de sac en étreinte"],"aliases_en":["Sandbag bear hug carry"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["sandbag"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["biceps_brachii","erector_spinae","rectus_abdominis"],"difficulty":"intermediate","metrics":["distance_m","duration_s","load_kg"],"unilateral":false,"bodyweight":false,"tags":["full_body","core"],"instructions_fr":["Place-toi au-dessus d'un sandbag, descends en squat et entoure-le des deux bras, mains ou avant-bras verrouillés en dessous.","Soulève le sandbag en te relevant et serre-le fort contre la poitrine.","Gaine le tronc et garde la poitrine haute, avec le sac assez haut pour qu'il ne tire pas tes épaules vers l'avant.","Avance à petits pas contrôlés sur la distance ou la durée prévue.","Continue de serrer le sac pendant toute la marche.","Repose le sac au sol en descendant en squat, dos droit."],"image_main":"/exercises/sandbag-carry/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-sandbag-carry","coory-sandbag-bear-hug-carry"],"attribution_required":true,"exportable":false},
