{"id":"a16923fd-dc4c-5929-bfba-41667b95e211","key":"savasana","name_fr":"Posture du cadavre","name_en":"Corpse Pose","aliases_fr":["Savasana","Relaxation finale"],"aliases_en":["Savasana"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":[],"secondary_muscles":[],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Allonge-toi sur le dos, jambes écartées d'une distance confortable et pieds qui tombent vers l'extérieur.","Pose les bras légèrement écartés du corps, paumes vers le haut.","Laisse tout le corps se relâcher dans le sol, y compris la mâchoire, les yeux et les mains.","Reste ainsi le temps prévu, en respirant naturellement sans contrôler ton souffle.","Plie les genoux et roule sur un côté avant de te redresser lentement."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-savasana"],"attribution_required":true,"exportable":false},
{"id":"2250f0ee-ce8d-5fca-b973-11f83296f2e7","key":"scapular-pull-ups","name_fr":"Tractions scapulaires","name_en":"Scapular Pull Ups","aliases_fr":["Scapular pull-ups"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"pull-up","variant_of":null,"equipment":["pull_up_bar"],"primary_muscles":["latissimus_dorsi","trapezius"],"secondary_muscles":["forearm_flexors","rhomboids"],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Suspends-toi à une barre de traction, bras en extension complète.","Garde les bras tendus pendant tout le mouvement.","Abaisse et rapproche les omoplates pour faire monter la poitrine.","Marque une courte pause en haut du mouvement.","Reviens en suspension complète.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/scapular-pull-ups/start.webp","image_end":"/exercises/scapular-pull-ups/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-scapular-pull-ups"],"attribution_required":true,"exportable":false},
