{"id":"a43bbcd1-9624-56e5-a3be-42f3b04231ae","key":"scissor-kicks","name_fr":"Ciseaux","name_en":"Scissor Kicks","aliases_fr":["Ciseaux jambes"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"leg-raise","variant_of":null,"equipment":[],"primary_muscles":["hip_flexors","rectus_abdominis"],"secondary_muscles":["obliques","transverse_abdominis"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Allonge-toi à plat sur le dos, les mains sous les fessiers.","Décolle les deux jambes du sol de quelques centimètres.","Croise une jambe au-dessus de l'autre en alternance, en mouvement de ciseaux.","Garde le bas du dos plaqué au sol.","Garde un rythme régulier du début à la fin.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/scissor-kicks/start.webp","image_end":"/exercises/scissor-kicks/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-scissor-kicks"],"attribution_required":true,"exportable":false},
