{"id":"82396314-3cf1-5411-89fe-121ab09d02df","key":"seated-barbell-overhead-press","name_fr":"Développé militaire assis barre","name_en":"Seated Barbell Overhead Press","aliases_fr":["Développé épaules barre assis"],"aliases_en":["Seated OHP"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-press","variant_of":null,"equipment":["barbell","bench"],"primary_muscles":["anterior_deltoid"],"secondary_muscles":["lateral_deltoid","trapezius","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Règle un banc à dossier droit dans un rack, avec les butées à hauteur d'épaules quand tu es assis.","Assieds-toi le dos bien à plat contre le dossier et décroche la barre devant les épaules.","Pousse la barre au-dessus de la tête jusqu'à l'extension complète des bras, en passant la tête sous la barre en haut.","Redescends la barre vers les clavicules en contrôlant.","Répète pour le nombre de répétitions prévu."],"image_main":null,"image_start":"/exercises/seated-barbell-overhead-press/start.webp","image_end":"/exercises/seated-barbell-overhead-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-seated-barbell-overhead-press"],"attribution_required":true,"exportable":false},
{"id":"93fe68d7-ddec-5dea-ab59-51f946062028","key":"seated-cable-row","name_fr":"Tirage horizontal à la poulie","name_en":"Seated Cable Row","aliases_fr":["Rowing assis à la poulie"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"row","variant_of":null,"equipment":["cable"],"primary_muscles":["latissimus_dorsi","rhomboids"],"secondary_muscles":["biceps_brachii","erector_spinae","posterior_deltoid"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Assieds-toi à la station de tirage horizontal et pose les pieds sur les repose-pieds.","Saisis la poignée et tiens-toi droit, légèrement penché en avant.","Emmène les coudes vers l'arrière et tire la poignée vers le bas des abdominaux.","Serre les omoplates l'une vers l'autre en fin de tirage.","Tends les bras de façon contrôlée pour revenir à la position de départ.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/seated-cable-row/start.webp","image_end":"/exercises/seated-cable-row/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-seated-cable-row"],"attribution_required":true,"exportable":false},
{"id":"8554533b-129c-58fe-a903-e031857fd705","key":"seated-calf-raise","name_fr":"Extension des mollets assis","name_en":"Seated Calf Raise","aliases_fr":["Mollets assis"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"calf-raise","variant_of":null,"equipment":["seated_calf_raise_machine"],"primary_muscles":["soleus"],"secondary_muscles":["gastrocnemius"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs"],"instructions_fr":["Assieds-toi à la machine à mollets, les coussins posés sur les cuisses.","Descends les talons le plus bas possible.","Monte sur la pointe des pieds.","Redescends de façon contrôlée.","Répète."],"image_main":null,"image_start":"/exercises/seated-calf-raise/start.webp","image_end":"/exercises/seated-calf-raise/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-seated-calf-raise"],"attribution_required":true,"exportable":false},
{"id":"c3ea1fff-82a3-5a62-b866-91ccffd53bd1","key":"seated-db-press","name_fr":"Développé épaules haltères assis","name_en":"Seated Dumbbell Shoulder Press","aliases_fr":["Développé militaire haltères assis"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-press","variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["anterior_deltoid","lateral_deltoid"],"secondary_muscles":["trapezius","triceps_brachii"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["push"],"instructions_fr":["Assieds-toi sur un banc avec dossier, haltères tenus à hauteur d'épaules.","Pousse les haltères au-dessus de la tête jusqu'à l'extension complète des bras.","Redescends les haltères à hauteur d'épaules.","Répète."],"image_main":null,"image_start":"/exercises/seated-db-press/start.webp","image_end":"/exercises/seated-db-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-seated-db-press"],"attribution_required":true,"exportable":false},
{"id":"b044aebe-29b2-565b-84c5-bea3df458e7a","key":"seated-dip-machine","name_fr":"Dips assis à la machine","name_en":"Seated Dip Machine","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"dips","variant_of":null,"equipment":["dip_machine"],"primary_muscles":["triceps_brachii"],"secondary_muscles":["anterior_deltoid","pectoralis_major"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Sélectionne la charge sur le bloc et règle le siège pour que les poignées soient à peu près à hauteur d'épaules une fois assis.","Assieds-toi bien droit, dos contre le dossier, et saisis les poignées sur les côtés, coudes fléchis.","Garde les épaules basses et la poitrine haute, puis pousse les poignées vers le bas en tendant les coudes.","Contracte les triceps en bas, bras tendus mais sans verrouiller fort.","Laisse les poignées remonter sous contrôle jusqu'à ce que les coudes soient fléchis à environ 90 degrés.","Répète pour le nombre de répétitions prévu, dos toujours contre le dossier."],"image_main":null,"image_start":"/exercises/seated-dip-machine/start.webp","image_end":"/exercises/seated-dip-machine/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-seated-dip-machine"],"attribution_required":true,"exportable":false},
{"id":"bbe05698-0f10-54e4-b22f-8e4a4e4e959c","key":"seated-dumbbell-curl","name_fr":"Curl haltères assis","name_en":"Seated Dumbbell Curl","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"bicep-curl","variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["biceps_brachii"],"secondary_muscles":["brachialis","brachioradialis"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Assieds-toi sur un banc avec un haltère dans chaque main.","Laisse les bras pendre le long du corps, paumes vers l'avant.","Monte les deux haltères vers les épaules en contractant les biceps.","Serre en haut du mouvement.","Redescends les haltères de façon contrôlée.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/seated-dumbbell-curl/start.webp","image_end":"/exercises/seated-dumbbell-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-seated-dumbbell-curl"],"attribution_required":true,"exportable":false},
{"id":"39c44338-a279-53bd-b774-7459d046f6ad","key":"seated-dumbbell-lateral-raise","name_fr":"Élévations latérales haltères assis","name_en":"Seated Dumbbell Lateral Raise","aliases_fr":["Élévations latérales assis"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"lateral-raise","variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["lateral_deltoid"],"secondary_muscles":["anterior_deltoid","trapezius"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Assieds-toi sur un banc avec un haltère dans chaque main, le long du corps.","Garde le dos droit et les abdominaux gainés.","Monte les deux haltères sur les côtés jusqu'à hauteur d'épaules.","Garde une légère flexion des coudes.","Redescends les haltères de façon contrôlée.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/seated-dumbbell-lateral-raise/start.webp","image_end":"/exercises/seated-dumbbell-lateral-raise/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-seated-dumbbell-lateral-raise"],"attribution_required":true,"exportable":false},
{"id":"cc10e6f9-b0e7-588c-870a-89adb772687f","key":"seated-dumbbell-tricep-extension","name_fr":"Extension triceps haltère assis","name_en":"Seated Dumbbell Tricep Extension","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-tricep-extension","variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["triceps_brachii"],"secondary_muscles":["anterior_deltoid"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Assieds-toi sur un banc, un haltère tenu à deux mains au-dessus de la tête.","Garde les bras verticaux, près des oreilles.","Descends l'haltère derrière la tête en fléchissant les coudes.","Tends les bras pour repousser l'haltère au-dessus de la tête.","Contracte les triceps en haut.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/seated-dumbbell-tricep-extension/start.webp","image_end":"/exercises/seated-dumbbell-tricep-extension/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-seated-dumbbell-tricep-extension"],"attribution_required":true,"exportable":false},
{"id":"8365468b-2e3b-5bc5-a770-3cb58de5a7db","key":"seated-forward-fold","name_fr":"Flexion avant assise","name_en":"Seated Forward Fold","aliases_fr":["Pince assise","Paschimottanasana"],"aliases_en":["Seated forward bend"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["hamstrings"],"secondary_muscles":["erector_spinae"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Assieds-toi au sol, les deux jambes tendues devant toi.","Garde le dos long et penche-toi en avant en pliant aux hanches.","Tends les mains vers tes pieds.","Tiens la position 20 à 30 secondes en respirant calmement."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-seated-forward-fold"],"attribution_required":true,"exportable":false},
{"id":"737d52e0-4f6b-5653-990b-48e988e5ac5f","key":"seated-leg-curl","name_fr":"Leg curl assis","name_en":"Seated Leg Curl","aliases_fr":["Curl ischio assis"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"leg-curl","variant_of":null,"equipment":["leg_curl"],"primary_muscles":["hamstrings"],"secondary_muscles":["gastrocnemius"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":["legs"],"instructions_fr":["Règle le dossier et le pad de chevilles pour que tes genoux soient alignés avec le pivot de la machine.","Assieds-toi bien droit, pose l'arrière des chevilles sur le pad et attrape les poignées.","Ramène les jambes vers le bas et vers l'arrière sous le siège, aussi loin que la machine le permet.","Marque une pause à la contraction maximale, puis ramène la charge lentement à la position de départ.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/seated-leg-curl/start.webp","image_end":"/exercises/seated-leg-curl/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-seated-leg-curl"],"attribution_required":true,"exportable":false},
{"id":"3dbd9ba8-ec82-5c57-bb16-a61ba31be5df","key":"seated-smith-machine-shoulder-press","name_fr":"Développé épaules Smith machine assis","name_en":"Seated Smith Machine Shoulder Press","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"overhead-press","variant_of":null,"equipment":["smith_machine"],"primary_muscles":["anterior_deltoid","lateral_deltoid"],"secondary_muscles":["trapezius","triceps_brachii"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Place un banc à l'intérieur d'une Smith machine.","Assieds-toi face à l'avant, la barre à hauteur d'épaules.","Prends la barre un peu plus large que les épaules.","Décroche la barre et pousse-la droit vers le haut jusqu'à l'extension des bras.","Redescends la barre à hauteur d'épaules en contrôlant.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/seated-smith-machine-shoulder-press/start.webp","image_end":"/exercises/seated-smith-machine-shoulder-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-seated-smith-machine-shoulder-press"],"attribution_required":true,"exportable":false},
{"id":"814c909a-fbee-54a2-8d00-6426dc14b86c","key":"seated-spinal-twist","name_fr":"Torsion assise de la colonne","name_en":"Seated Spinal Twist","aliases_fr":["Torsion assise"],"aliases_en":["Seated twist"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["erector_spinae","obliques"],"secondary_muscles":["gluteus_maximus"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":["Assieds-toi avec une jambe tendue et croise l'autre pied par-dessus.","Appuie le coude opposé contre l'extérieur du genou plié.","Tourne le buste vers le genou plié et regarde par-dessus ton épaule.","Tiens la position 20 à 30 secondes en respirant calmement.","Change de côté et recommence."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-seated-spinal-twist"],"attribution_required":true,"exportable":false},
{"id":"eb8e48a5-fd20-58b7-9aaf-a6e4f8c66aa2","key":"seated-straddle-stretch","name_fr":"Grand écart assis","name_en":"Seated Straddle Stretch","aliases_fr":["Écart assis","Upavistha Konasana"],"aliases_en":["Straddle stretch"],"category":"mobility","visibility":"hidden","disciplines":["mobility"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":[],"primary_muscles":["adductors","hamstrings"],"secondary_muscles":["erector_spinae"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Assieds-toi jambes tendues et largement écartées en V.","Garde le dos long et penche-toi en avant en pliant aux hanches.","Fais avancer les mains au sol devant toi.","Tiens la position 20 à 30 secondes en respirant calmement."],"image_main":null,"image_start":null,"image_end":null,"image_source":null,"source":"repdb","source_ids":["repdb-seated-straddle-stretch"],"attribution_required":true,"exportable":false},
