{"id":"b3757b03-40e7-5048-b2a8-e052034d01b5","key":"shrimp-squat","name_fr":"Shrimp squat","name_en":"Shrimp Squat","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"squat","variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["erector_spinae","gastrocnemius","gluteus_medius","hamstrings"],"difficulty":"advanced","metrics":["reps","tempo"],"unilateral":true,"bodyweight":true,"tags":["legs","calisthenics"],"instructions_fr":["Tiens-toi sur une jambe, fléchis l'autre genou et attrape ce pied derrière toi avec la main du même côté.","Garde les bras et la poitrine stables et commence à fléchir le genou d'appui, en descendant les hanches vers le bas et légèrement vers l'arrière.","Descends jusqu'à ce que le genou arrière touche légèrement le sol derrière le pied d'appui.","Garde la poitrine haute et le talon d'appui au sol pendant toute la descente.","Pousse avec tout le pied d'appui et tends cette jambe pour te relever sans lâcher le pied arrière.","Fais le nombre de répétitions prévu, puis répète sur l'autre jambe."],"image_main":null,"image_start":"/exercises/shrimp-squat/start.webp","image_end":"/exercises/shrimp-squat/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-shrimp-squat"],"attribution_required":true,"exportable":false},
{"id":"9dc060af-43b0-5200-ac9d-76ca2089114a","key":"shrug","name_fr":"Shrugs barre","name_en":"Barbell Shrug","aliases_fr":["Haussements d'épaules barre"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"shrug","variant_of":null,"equipment":["barbell"],"primary_muscles":["trapezius"],"secondary_muscles":["rhomboids"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":false,"bodyweight":false,"tags":[],"instructions_fr":["Tiens-toi debout avec une barre, bras tendus le long du corps, en pronation.","Hausse les épaules à la verticale vers les oreilles.","Marque une brève pause en haut.","Redescends les épaules de façon contrôlée.","Répète."],"image_main":null,"image_start":"/exercises/shrug/start.webp","image_end":"/exercises/shrug/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-shrug"],"attribution_required":true,"exportable":false},
{"id":"128dc8ee-92d9-52ff-b4b9-8945637e5ceb","key":"side-lunge","name_fr":"Fentes latérales","name_en":"Side Lunge","aliases_fr":[],"aliases_en":["Lateral lunge"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"lunge","variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["gluteus_medius","hamstrings","hip_flexors"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":["Tiens-toi debout, pieds à largeur de hanches, les mains contre la poitrine.","Fais un grand pas sur le côté avec une jambe, l'autre jambe restant tendue.","Fléchis le genou de la jambe qui avance et recule les hanches en squat latéral.","Garde la poitrine haute et le talon de travail bien posé.","Pousse avec la jambe fléchie pour revenir debout.","Fais toutes les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/side-lunge/start.webp","image_end":"/exercises/side-lunge/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-side-lunge"],"attribution_required":true,"exportable":false},
{"id":"d8139c6c-4716-507c-b57b-5cfaed057eb9","key":"side-lying-hip-abduction","name_fr":"Abduction de hanche allongé sur le côté","name_en":"Side-Lying Hip Abduction","aliases_fr":["Élévation latérale de jambe allongé"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"hip-abduction","variant_of":null,"equipment":[],"primary_muscles":["abductors","gluteus_medius"],"secondary_muscles":[],"difficulty":"beginner","metrics":["reps","tempo"],"unilateral":true,"bodyweight":true,"tags":["legs"],"instructions_fr":["Allonge-toi sur le côté, jambes empilées.","Garde la jambe du dessous légèrement fléchie.","Lève la jambe du dessus vers le plafond.","Redescends sous contrôle.","Répète des deux côtés."],"image_main":null,"image_start":"/exercises/side-lying-hip-abduction/start.webp","image_end":"/exercises/side-lying-hip-abduction/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-side-lying-hip-abduction"],"attribution_required":true,"exportable":false},
{"id":"ede36bee-6f2d-5a14-b0f6-fd7cd3330781","key":"side-lying-hip-abduction-hold","name_fr":"Abduction de hanche allongé isométrique","name_en":"Side-Lying Hip Abduction Hold","aliases_fr":["Maintien abduction de hanche allongé"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"hip-abduction","variant_of":null,"equipment":[],"primary_muscles":["abductors","gluteus_medius"],"secondary_muscles":[],"difficulty":"beginner","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":["legs"],"instructions_fr":["Allonge-toi sur le côté, jambes empilées et tendues, la tête appuyée sur le bras du dessous.","Gaine le tronc pour que le buste reste face à l'avant et ne bascule pas en arrière.","Lève la jambe du dessus à environ 30 à 45 degrés, orteils pointés vers l'avant.","Maintiens la jambe en position pendant le temps prévu, en respirant normalement.","Redescends la jambe sous contrôle et répète de l'autre côté."],"image_main":"/exercises/side-lying-hip-abduction-hold/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-side-lying-hip-abduction-hold"],"attribution_required":true,"exportable":false},
{"id":"368d6b00-9e75-531b-9806-e593d5f63d2f","key":"side-lying-hip-adduction","name_fr":"Adduction de hanche allongé sur le côté","name_en":"Side Lying Hip Adduction","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"hip-adduction","variant_of":null,"equipment":[],"primary_muscles":["adductors"],"secondary_muscles":[],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Allonge-toi sur le côté, jambe du dessous tendue.","Fléchis la jambe du dessus et pose son pied à plat devant la cuisse du dessous.","Appuie ta tête sur le bras du dessous.","Lève la jambe du dessous vers le plafond.","Redescends la jambe sous contrôle.","Fais toutes les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/side-lying-hip-adduction/start.webp","image_end":"/exercises/side-lying-hip-adduction/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-side-lying-hip-adduction"],"attribution_required":true,"exportable":false},
{"id":"e76e4d02-d732-508b-870e-101915957c96","key":"side-lying-hip-adduction-hold","name_fr":"Adduction de hanche allongé isométrique","name_en":"Side-Lying Hip Adduction Hold","aliases_fr":["Maintien adduction de hanche allongé"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"hip-adduction","variant_of":null,"equipment":[],"primary_muscles":["adductors"],"secondary_muscles":[],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":[],"instructions_fr":["Allonge-toi sur le côté, jambe du dessous tendue et jambe du dessus croisée par-dessus, pied à plat au sol.","Appuie la tête sur le bras du dessous et garde les hanches empilées à la verticale.","Lève la jambe du dessous aussi haut que possible, genou tendu et orteils pointés vers l'avant.","Maintiens cette position levée pendant le temps prévu, sans basculer les hanches en arrière.","Redescends la jambe sous contrôle et répète de l'autre côté."],"image_main":"/exercises/side-lying-hip-adduction-hold/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-side-lying-hip-adduction-hold"],"attribution_required":true,"exportable":false},
{"id":"25c59c73-17c8-5292-8f96-c815afc5872a","key":"side-lying-lateral-raise","name_fr":"Élévations latérales allongé sur le côté","name_en":"Side-Lying Lateral Raise","aliases_fr":["Side-lying lateral raise"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":null,"variant_of":null,"equipment":["dumbbell","bench"],"primary_muscles":["lateral_deltoid"],"secondary_muscles":["supraspinatus","trapezius"],"difficulty":"beginner","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":["shoulders","push"],"instructions_fr":["Allonge-toi sur le côté sur un banc plat, le bras du bas soutenant la tête ou agrippant le bord du banc.","Tiens un haltère dans la main du haut, bras le long du corps.","Coude légèrement fléchi, monte l'haltère jusqu'à ce que le bras soit perpendiculaire au sol.","Marque une courte pause en haut, puis redescends lentement l'haltère le long du corps.","Fais toutes les répétitions d'un côté avant de changer."],"image_main":null,"image_start":"/exercises/side-lying-lateral-raise/start.webp","image_end":"/exercises/side-lying-lateral-raise/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-side-lying-lateral-raise"],"attribution_required":true,"exportable":false},
{"id":"ca8c0be9-2fce-5e69-920d-49f4468502a6","key":"side-plank","name_fr":"Planche latérale","name_en":"Side Plank","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"plank","variant_of":null,"equipment":[],"primary_muscles":["obliques","transverse_abdominis"],"secondary_muscles":["gluteus_medius","rectus_abdominis"],"difficulty":"beginner","metrics":["duration_s"],"unilateral":false,"bodyweight":true,"tags":["core","calisthenics"],"instructions_fr":["Allonge-toi sur le côté, avant-bras au sol, coude sous l'épaule.","Soulève les hanches du sol pour former une ligne droite de la tête aux pieds.","Tiens la position en gardant les abdominaux gainés.","Respire régulièrement.","Répète de chaque côté."],"image_main":"/exercises/side-plank/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-side-plank"],"attribution_required":true,"exportable":false},
{"id":"e7b55dce-b63d-5695-8e25-1837bd033b5f","key":"side-plank-leg-lift","name_fr":"Planche latérale avec levée de jambe","name_en":"Side Plank with Leg Lift","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"plank","variant_of":null,"equipment":[],"primary_muscles":["gluteus_medius","obliques"],"secondary_muscles":["gluteus_maximus","rectus_abdominis","transverse_abdominis"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":true,"bodyweight":true,"tags":["core","calisthenics","glutes"],"instructions_fr":["Allonge-toi sur le côté, avant-bras au sol, coude sous l'épaule.","Empile les pieds et soulève les hanches en planche latérale.","Depuis cette planche latérale stable, monte la jambe du dessus droit vers le plafond.","Redescends la jambe en contrôlant sans laisser tomber les hanches.","Fais les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/side-plank-leg-lift/start.webp","image_end":"/exercises/side-plank-leg-lift/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-side-plank-leg-lift"],"attribution_required":true,"exportable":false},
{"id":"e0258d66-fc99-50f0-970f-1aef7449591e","key":"side-plank-leg-lift-hold","name_fr":"Planche latérale avec jambe levée (maintien)","name_en":"Side Plank Leg Lift Hold","aliases_fr":[],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"plank","variant_of":null,"equipment":[],"primary_muscles":["gluteus_medius","obliques"],"secondary_muscles":["gluteus_maximus","rectus_abdominis","transverse_abdominis"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":["core","calisthenics","glutes"],"instructions_fr":["Mets-toi en planche latérale sur l'avant-bras, coude sous l'épaule et pieds empilés.","Soulève les hanches jusqu'à ce que le corps forme une ligne droite des chevilles à la tête.","Monte la jambe du dessus à peu près à hauteur de hanche, orteils pointés vers l'avant.","Tiens la position pendant le temps prescrit, hanches hautes et épaule d'appui bien au-dessus du coude.","Redescends la jambe et les hanches en contrôlant, puis répète de l'autre côté."],"image_main":"/exercises/side-plank-leg-lift-hold/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-side-plank-leg-lift-hold"],"attribution_required":true,"exportable":false},
