{"id":"d723b012-8ddc-5f93-b741-3b864abb91b6","key":"single-leg-press","name_fr":"Presse à cuisses à une jambe","name_en":"Single Leg Press","aliases_fr":["Presse unilatérale"],"aliases_en":[],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"leg-press","variant_of":null,"equipment":["leg_press"],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["hamstrings"],"difficulty":"intermediate","metrics":["reps","load_kg","tempo"],"unilateral":true,"bodyweight":false,"tags":[],"instructions_fr":["Assieds-toi dans une presse à cuisses avec un seul pied sur la plateforme.","Garde l'autre jambe hors de la plateforme, posée sur le côté.","Déverrouille les sécurités et descends la plateforme en fléchissant le genou.","Arrête-toi quand ton genou est proche de 90 degrés.","Pousse dans le talon pour remonter la plateforme.","Fais toutes les répétitions d'un côté, puis change."],"image_main":null,"image_start":"/exercises/single-leg-press/start.webp","image_end":"/exercises/single-leg-press/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-single-leg-press"],"attribution_required":true,"exportable":false},
{"id":"a8c13fed-4818-5c8a-9f56-5c3cf13fc4ee","key":"single-leg-rdl-hold","name_fr":"Soulevé de terre roumain une jambe isométrique","name_en":"Single Leg RDL Hold","aliases_fr":["Maintien SDT roumain unilatéral"],"aliases_en":["Single leg RDL isometric"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"deadlift","variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus","hamstrings"],"secondary_muscles":["adductors","erector_spinae","gluteus_medius","obliques"],"difficulty":"intermediate","metrics":["duration_s"],"unilateral":true,"bodyweight":true,"tags":["legs","core"],"instructions_fr":["Tiens-toi sur une jambe, genou légèrement fléchi, bras pendants devant toi.","Penche-toi en charnière de hanche en envoyant la jambe libre droite vers l'arrière pendant que le buste s'incline vers l'avant.","Garde le dos plat et les hanches face au sol.","Arrête-toi quand le buste et la jambe libre sont à peu près parallèles au sol et maintiens la position.","Reviens debout sous contrôle, puis change de jambe."],"image_main":"/exercises/single-leg-rdl-hold/main.webp","image_start":null,"image_end":null,"image_source":"repdb","source":"repdb","source_ids":["repdb-single-leg-rdl-hold"],"attribution_required":true,"exportable":false},
