{"id":"241b4346-f530-50f3-9174-9a7ba793ea33","key":"walking-lunge","name_fr":"Fentes marchées","name_en":"Walking Lunge","aliases_fr":[],"aliases_en":["Walking lunges"],"category":"strength","visibility":"active","disciplines":["strength"],"hyrox_station":null,"family":"lunge","variant_of":null,"equipment":[],"primary_muscles":["gluteus_maximus","quadriceps"],"secondary_muscles":["gluteus_medius","hamstrings"],"difficulty":"intermediate","metrics":["reps","tempo"],"unilateral":true,"bodyweight":true,"tags":[],"instructions_fr":["Tiens-toi droit, pieds à largeur de hanches et mains sur les hanches.","Fais un grand pas en avant en fente.","Descends jusqu'à ce que les deux genoux soient autour de 90 degrés.","Pousse dans le talon avant et amène le pied arrière devant.","Continue en alternant les jambes en avançant.","Répète pour le nombre de répétitions voulu."],"image_main":null,"image_start":"/exercises/walking-lunge/start.webp","image_end":"/exercises/walking-lunge/end.webp","image_source":"repdb","source":"repdb","source_ids":["repdb-walking-lunge"],"attribution_required":true,"exportable":false},
